#include <hpx/hpx_main.hpp>

/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
void luFactorize(std::vector<double> &A, size_t N) {
    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    for (size_t k = 0; k < N; ++k) {
        // Compute U(k, j) for j = k..N-1 in parallel
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += A[idx(k, p)] * A[idx(p, j)];
            A[idx(k, j)] -= sum;
        });

        double pivot = A[idx(k, k)];
        if (pivot == 0.0)
            throw std::runtime_error("Zero pivot encountered; pivoting required.");

        // Compute L(i, k) for i = k+1..N-1 in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += A[idx(i, p)] * A[idx(p, k)];
            A[idx(i, k)] = (A[idx(i, k)] - sum) / pivot;
        });
    }
}

