   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
void luFactorize(std::vector<double> &A, size_t N) {
    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    for (size_t k = 0; k < N; ++k) {
        // Compute U row k: A[k, j] -= sum_{p=0..k-1} L[k, p] * U[p, j]
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += A[idx(k, p)] * A[idx(p, j)];
            A[idx(k, j)] -= sum;
        });

        // Compute L column k: A[i, k] = (A[i, k] - sum_{p=0..k-1} L[i, p] * U[p, k]) / U[k, k]
        double pivot = A[idx(k, k)];
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += A[idx(i, p)] * A[idx(p, k)];
            A[idx(i, k)] = (A[idx(i, k)] - sum) / pivot;
        });
    }
}

