#include <hpx/hpx_main.hpp>

/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
{
    // Doolittle LU factorization without pivoting.
    // Stores U on and above diagonal, and L (with implicit unit diagonal) below diagonal.
    if (A.size() != N * N) return;

    for (size_t k = 0; k < N; ++k) {
        double pivot = A[k * N + k];
        if (pivot == 0.0) throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");

        // Compute multipliers for column k (L entries below diagonal)
        {
            std::vector<hpx::future<void>> futs;
            futs.reserve(N - k - 1);
            for (size_t i = k + 1; i < N; ++i) {
                futs.push_back(hpx::async([&, i, k, pivot] {
                    A[i * N + k] /= pivot;
                }));
            }
            hpx::when_all(futs).wait();
        }

        // Update trailing submatrix
        {
            std::vector<hpx::future<void>> futs;
            futs.reserve(N - k - 1);
            for (size_t i = k + 1; i < N; ++i) {
                futs.push_back(hpx::async([&, i, k] {
                    const double lik = A[i * N + k];
                    const size_t row_i = i * N;
                    const size_t row_k = k * N;
                    for (size_t j = k + 1; j < N; ++j) {
                        A[row_i + j] -= lik * A[row_k + j];
                    }
                }));
            }
            hpx::when_all(futs).wait();
        }
    }
}

