/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
void luFactorize(std::vector<double> &A, size_t N) {
    const double eps = 1e-12;

    for (size_t k = 0; k < N; ++k) {
        // Compute U row k: A[k, j] for j >= k
        auto uj_begin = hpx::counting_iterator<size_t>(k);
        auto uj_end   = hpx::counting_iterator<size_t>(N);
        hpx::for_each(hpx::execution::par, uj_begin, uj_end,
                      [&](size_t j) {
                          double s = 0.0;
                          for (size_t p = 0; p < k; ++p) {
                              s += A[k * N + p] * A[p * N + j];
                          }
                          A[k * N + j] -= s;
                      });

        double pivot = A[k * N + k];
        if (std::abs(pivot) < eps) {
            throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented).");
        }

        // Compute L column k: A[i, k] for i > k
        auto li_begin = hpx::counting_iterator<size_t>(k + 1);
        auto li_end   = hpx::counting_iterator<size_t>(N);
        hpx::for_each(hpx::execution::par, li_begin, li_end,
                      [&](size_t i) {
                          double s = 0.0;
                          for (size_t p = 0; p < k; ++p) {
                              s += A[i * N + p] * A[p * N + k];
                          }
                          A[i * N + k] = (A[i * N + k] - s) / pivot;
                      });
    }
    // Note: L has unit diagonal (not stored), U is on and above diagonal, L is strictly below.
}

