   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
{
    // Doolittle LU without pivoting: stores L (unit diagonal implied) and U in-place in A.
    // A is row-major, size N*N.
    // Requires nonzero pivots; no partial pivoting implemented.
    #include <hpx/execution.hpp>
    #include <hpx/algorithm.hpp>
    #include <hpx/iterator_support/counting_iterator.hpp>

    for (size_t k = 0; k < N; ++k) {
        double pivot = A[k * N + k];
        if (pivot == 0.0) throw std::runtime_error("Zero pivot encountered; pivoting not implemented.");

        // Compute multipliers for column k: L(i,k) = A(i,k) / U(k,k)
        auto ibeg = hpx::util::counting_iterator<std::size_t>(k + 1);
        auto iend = hpx::util::counting_iterator<std::size_t>(N);
        hpx::for_each(hpx::execution::par, ibeg, iend,
            [&](std::size_t i) {
                A[i * N + k] /= pivot;
            });

        // Rank-1 update of the trailing submatrix: A(i,j) -= L(i,k) * U(k,j)
        hpx::for_each(hpx::execution::par, ibeg, iend,
            [&](std::size_t i) {
                double lik = A[i * N + k];
                double const* Uk = &A[k * N];      // row k
                double* Ai = &A[i * N];            // row i
                for (size_t j = k + 1; j < N; ++j) {
                    Ai[j] -= lik * Uk[j];
                }
            });
    }
}

