*/
void luFactorize(std::vector<double> &A, size_t N) {

generated_output:
void luFactorize(std::vector<double> &A, size_t N) {
    if (A.size() != N * N) throw std::invalid_argument("A size != N*N");
    constexpr double eps = 1e-12;

    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    for (size_t k = 0; k < N; ++k) {
        // U row k: for j = k..N-1
        auto fu = hpx::async([&]() {
            hpx::for_each(hpx::execution::par,
                          hpx::counting_iterator<size_t>(k),
                          hpx::counting_iterator<size_t>(N),
                          [&](size_t j) {
                              double sum = 0.0;
                              for (size_t m = 0; m < k; ++m)
                                  sum += A[idx(k, m)] * A[idx(m, j)];
                              A[idx(k, j)] -= sum; // U(k,j)
                          });
        });
        fu.get();

        double pivot = A[idx(k, k)];
        if (std::abs(pivot) < eps) throw std::runtime_error("Zero or near-zero pivot encountered");

        // L column k: for i = k+1..N-1
        auto fl = hpx::async([&]() {
            hpx::for_each(hpx::execution::par,
                          hpx::counting_iterator<size_t>(k + 1),
                          hpx::counting_iterator<size_t>(N),
                          [&](size_t i) {
                              double sum = 0.0;
                              for (size_t m = 0; m < k; ++m)
                                  sum += A[idx(i, m)] * A[idx(m, k)];
                              A[idx(i, k)] = (A[idx(i, k)] - sum) / pivot; // L(i,k)
                          });
        });
        fl.get();
    }
}

