/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    const double eps = 1e-12;

    for (size_t k = 0; k < N; ++k) {
        // Pivoting (sequential)
        size_t pivot = k;
        double maxval = std::abs(M[k*N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i*N + k]);
            if (v > maxval) { maxval = v; pivot = i; }
        }
        if (maxval < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k*N + j], M[pivot*N + j]);
            std::swap(rhs[k], rhs[pivot]);
        }

        double pivot_val = M[k*N + k];

        // Elimination (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[i*N + k] / pivot_val;
            M[i*N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[i*N + j] -= factor * M[k*N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution (sequential)
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i*N + j] * x[j];
        double diag = M[i*N + i];
        if (std::abs(diag) < eps) throw std::runtime_error("Singular or ill-conditioned matrix");
        x[i] = (rhs[i] - sum) / diag;
    }
}

