void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N)
        throw std::invalid_argument("Dimension mismatch");

    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    const double eps = 1e-12;

    // Forward elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Find pivot
        size_t piv = k;
        double maxabs = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double val = std::abs(M[i * N + k]);
            if (val > maxabs) {
                maxabs = val;
                piv = i;
            }
        }
        if (maxabs < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        // Swap rows if needed
        if (piv != k) {
            for (size_t j = k; j < N; ++j)
                std::swap(M[k * N + j], M[piv * N + j]);
            std::swap(rhs[k], rhs[piv]);
        }

        double pivot = M[k * N + k];

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[i * N + k] / pivot;
            for (size_t j = k + 1; j < N; ++j)
                M[i * N + j] -= factor * M[k * N + j];
            rhs[i] -= factor * rhs[k];
            M[i * N + k] = 0.0;
        });
    }

    // Back substitution
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        double sum = 0.0;
        for (size_t j = static_cast<size_t>(ii) + 1; j < N; ++j)
            sum += M[static_cast<size_t>(ii) * N + j] * x[j];

        double diag = M[static_cast<size_t>(ii) * N + static_cast<size_t>(ii)];
        if (std::abs(diag) < eps) throw std::runtime_error("Singular or ill-conditioned matrix");
        x[static_cast<size_t>(ii)] = (rhs[static_cast<size_t>(ii)] - sum) / diag;
    }
}

