void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    if (N == 0) { x.clear(); return; }

    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.resize(N);

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t pivot_row = k;
        double max_abs = std::fabs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(M[i * N + k]);
            if (v > max_abs) { max_abs = v; pivot_row = i; }
        }
        if (max_abs == 0.0) throw std::runtime_error("Singular matrix");

        if (pivot_row != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k * N + j], M[pivot_row * N + j]);
            std::swap(rhs[k], rhs[pivot_row]);
        }

        double pivot = M[k * N + k];

        // Eliminate below pivot in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[i * N + k] / pivot;
            M[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[i * N + j] -= factor * M[k * N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double diag = M[i * N + i];
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i * N + j] * x[j];
        x[i] = (rhs[i] - sum) / diag;
    }
}

