    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting: find row with max |M[i,k]| for i>=k
        size_t pivot = k;
        double maxabs = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > maxabs) {
