void solveLinearSystem(std::vector<double> const& Ain, std::vector<double> const& bin, std::vector<double> &x, size_t N) {
    if (Ain.size() != N * N || bin.size() != N) throw std::invalid_argument("Dimension mismatch");
    x.assign(N, 0.0);
    if (N == 0) return;

    std::vector<double> A = Ain;
    std::vector<double> b = bin;

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t p = k;
        double maxa = std::fabs(A[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(A[i * N + k]);
            if (v > maxa) { maxa = v; p = i; }
        }
        if (maxa == 0.0) throw std::runtime_error("Singular matrix");

        if (p != k) {
            for (size_t j = k; j < N; ++j) std::swap(A[k * N + j], A[p * N + j]);
            std::swap(b[k], b[p]);
        }

        double pivot = A[k * N + k];

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double m = A[i * N + k] / pivot;
            if (m == 0.0) return;
            A[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                A[i * N + j] -= m * A[k * N + j];
            }
            b[i] -= m * b[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += A[i * N + j] * x[j];
        double aii = A[i * N + i];
        if (aii == 0.0) throw std::runtime_error("Singular matrix during back substitution");
        x[i] = (b[i] - sum) / aii;
    }
}

