void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    // Working copies
    std::vector<double> M = A;
    std::vector<double> y = b;
    x.assign(N, 0.0);

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Pivot selection (serial)
        size_t piv = k;
        double maxabs = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        // Swap rows if needed
        if (piv != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[idx(k, j)], M[idx(piv, j)]);
            std::swap(y[k], y[piv]);
        }

        double pivot = M[idx(k, k)];
        // Eliminate below pivot in parallel over rows
        if (k + 1 < N) {
            std::vector<size_t> rows(N - (k + 1));
            std::iota(rows.begin(), rows.end(), k + 1);

            hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
                [&](size_t i) {
                    double factor = M[idx(i, k)] / pivot;
                    if (factor == 0.0) return;
                    for (size_t j = k; j < N; ++j)
                        M[idx(i, j)] -= factor * M[idx(k, j)];
                    y[i] -= factor * y[k];
                });
        }
    }

    // Back substitution (serial outer loop)
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double diag = M[idx(i, i)];
