            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i * N + j] * x[j];
        double diag = M[i * N + i];
        if (diag == 0.0) throw std::runtime_error("Singular matrix on back substitution");
        x[i] = (rhs[i] - sum) / diag;
    }
}

