/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) {
        throw std::invalid_argument("Invalid dimensions");
    }

    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t pivot = k;
        double maxabs = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double val = std::abs(M[i * N + k]);
            if (val > maxabs) {
                maxabs = val;
                pivot = i;
            }
        }
        if (maxabs == 0.0) {
            throw std::runtime_error("Singular matrix");
        }
        if (pivot != k) {
            for (size_t j = k; j < N; ++j) {
                std::swap(M[k * N + j], M[pivot * N + j]);
            }
            std::swap(rhs[k], rhs[pivot]);
        }

        double Akk = M[k * N + k];

        // Eliminate below pivot in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[i * N + k] / Akk;
            M[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[i * N + j] -= factor * M[k * N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(N) - 1; i >= 0; --i) {
        double sum = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            sum -= M[static_cast<size_t>(i) * N + j] * x[j];
        }
        double diag = M[static_cast<size_t>(i) * N + static_cast<size_t>(i)];
        if (diag == 0.0) {
            throw std::runtime_error("Singular matrix");
        }
        x[static_cast<size_t>(i)] = sum / diag;
        if (i == 0) break;
    }
}

