/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    x = b;

    auto idx = [N](size_t r, size_t c) { return r * N + c; };
    const double eps = 1e-12;

    // Forward elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Pivot selection (sequential for robustness)
        size_t pivot = k;
        double maxv = std::fabs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(M[idx(i, k)]);
            if (v > maxv) { maxv = v; pivot = i; }
        }
        if (maxv < eps) throw std::runtime_error("Matrix is singular or ill-conditioned");

        // Swap rows if needed
        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[idx(k, j)], M[idx(pivot, j)]);
            std::swap(x[k], x[pivot]);
        }

        double pivot_val = M[idx(k, k)];

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[idx(i, k)] / pivot_val;
            if (factor != 0.0) {
                for (size_t j = k + 1; j < N; ++j)
                    M[idx(i, j)] -= factor * M[idx(k, j)];
                M[idx(i, k)] = 0.0;
                x[i] -= factor * x[k];
            }
        });
    }

    // Back substitution (sequential; small N impact, stable)
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[idx(i, j)] * x[j];
        double d = M[idx(i, i)];
        if (std::fabs(d) < eps) throw std::runtime_error("Matrix is singular or ill-conditioned");
        x[i] = (x[i] - sum) / d;
    }
}

