    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = rhs[size_t(i)];
        for (size_t j = size_t(i) + 1; j < N; ++j) sum -= M[idx(size_t(i), j)] * x[j];
