   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N || A.size() != N * N) throw std::invalid_argument("Dimension mismatch");
    x.resize(N);
    if (N == 0) return;

    std::vector<double> M = A;        // working copy of A
    std::vector<double> y = b;        // working copy of b

    auto at = [&](size_t i, size_t j) -> double& { return M[i * N + j]; };
    const double eps = 1e-12;

    for (size_t k = 0; k < N; ++k)
    {
        // Partial pivoting
        size_t piv = k;
        double maxv = std::fabs(at(k, k));
        for (size_t i = k + 1; i < N; ++i)
        {
            double v = std::fabs(at(i, k));
            if (v > maxv) { maxv = v; piv = i; }
        }
        if (maxv < eps) throw std::runtime_error("Matrix is singular or nearly singular");

        if (piv != k)
        {
            for (size_t j = k; j < N; ++j) std::swap(at(k, j), at(piv, j));
            std::swap(y[k], y[piv]);
        }

        // Elimination (rows i = k+1..N-1) in parallel
        std::vector<hpx::future<void>> tasks;
        tasks.reserve(N - k - 1);
        for (size_t i = k + 1; i < N; ++i)
        {
            tasks.push_back(hpx::async([&, i, k] {
                double factor = at(i, k) / at(k, k);
                at(i, k) = 0.0;
                for (size_t j = k + 1; j < N; ++j)
                    at(i, j) -= factor * at(k, j);
                y[i] -= factor * y[k];
            }));
        }
        hpx::when_all(tasks).wait();
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i)
    {
        double s = y[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j)
            s -= at(static_cast<size_t>(i), j) * x[j];
        double diag = at(static_cast<size_t>(i), static_cast<size_t>(i));
        if (std::fabs(diag) < eps) throw std::runtime_error("Zero on diagonal during back-substitution");
        x[static_cast<size_t>(i)] = s / diag;
    }
}

