void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    const double eps = 1e-12;

    std::vector<double> M = A;      // working copy of A
    std::vector<double> r = b;      // working copy of b
    x.assign(N, 0.0);

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Find pivot
        size_t p = k;
        double maxv = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i * N + k]);
            if (v > maxv) { maxv = v; p = i; }
        }
        if (maxv < eps) throw std::runtime_error("Singular matrix");

        // Swap rows k and p
        if (p != k) {
            hpx::for_loop(hpx::execution::par, 0, N, [&](size_t j) {
                std::swap(M[k * N + j], M[p * N + j]);
            });
            std::swap(r[k], r[p]);
        }

        double* pivotRow = &M[k * N];
        double pivot = pivotRow[k];

        // Eliminate below pivot in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double* row = &M[i * N];
            double factor = (pivot == 0.0) ? 0.0 : row[k] / pivot;
            if (factor == 0.0) { row[k] = 0.0; return; }
            for (size_t j = k; j < N; ++j)
                row[j] -= factor * pivotRow[j];
            r[i] -= factor * r[k];
            row[k] = 0.0;
        });
    }

    // Back substitution
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        size_t i = static_cast<size_t>(ii);
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i * N + j] * x[j];
        double diag = M[i * N + i];
        if (std::abs(diag) < eps) throw std::runtime_error("Singular matrix");
