void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    x.assign(N, 0.0);

    std::vector<double> M = A;       // mutable copy of A
    std::vector<double> rhs = b;     // mutable copy of b

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    for (size_t k = 0; k < N; ++k) {
        // Pivot selection (partial pivoting)
        size_t p = k;
        double maxabs = std::fabs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(M[idx(i, k)]);
            if (v > maxabs) { maxabs = v; p = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        // Swap rows if needed
        if (p != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[idx(k, j)], M[idx(p, j)]);
            std::swap(rhs[k], rhs[p]);
        }

        double piv = M[idx(k, k)];

        // Eliminate below pivot in parallel
        hpx::for_each(hpx::execution::par, size_t(k + 1), N, [&](size_t i) {
            double factor = M[idx(i, k)] / piv;
            if (factor != 0.0) {
                for (size_t j = k; j < N; ++j) {
                    M[idx(i, j)] -= factor * M[idx(k, j)];
                }
                rhs[i] -= factor * rhs[k];
            }
        });
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = rhs[size_t(i)];
        for (size_t j = size_t(i) + 1; j < N; ++j) {
            sum -= M[idx(size_t(i), j)] * x[j];
        }
        double diag = M[idx(size_t(i), size_t(i))];
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        x[size_t(i)] = sum / diag;
    }
}

