    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    auto at = [&](size_t r, size_t c) -> double& { return M[r * N + c]; };
    auto cat = [&](size_t r, size_t c) -> double { return M[r * N + c]; };

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // pivot search
        size_t p = k;
        double maxv = std::fabs(cat(k, k));
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(cat(i, k));
            if (v > maxv) { maxv = v; p = i; }
        }
        if (maxv < eps) throw std::runtime_error("Singular or nearly singular matrix");

        // swap rows
        if (p != k) {
            for (size_t j = k; j < N; ++j) std::swap(at(k, j), at(p, j));
            std::swap(rhs[k], rhs[p]);
        }

        double pivot = cat(k, k);

        // eliminate rows below in parallel
        std::vector<hpx::future<void>> tasks;
        tasks.reserve((N > k + 1) ? (N - (k + 1)) : 0);

        for (size_t i = k + 1; i < N; ++i) {
            if (std::fabs(cat(i, k)) < eps) continue;
            tasks.push_back(hpx::async([&, i, k, pivot] {
                double m = cat(i, k) / pivot;
                // update row i from column k+1 onward
                for (size_t j = k + 1; j < N; ++j) {
                    at(i, j) -= m * cat(k, j);
                }
                rhs[i] -= m * rhs[k];
                at(i, k) = 0.0;
            }));
        }
        hpx::wait_all(tasks);
    }

    // back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            sum -= cat(static_cast<size_t>(i), j) * x[j];
        }
        double diag = cat(static_cast<size_t>(i), static_cast<size_t>(i));
        if (std::fabs(diag) < eps) throw std::runtime_error("Singular matrix on back substitution");
        x[static_cast<size_t>(i)] = sum / diag;
    }
}

