   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A_in,
                       std::vector<double> const& b_in,
                       std::vector<double> &x,
                       size_t N)
{
    if (A_in.size() != N*N || b_in.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> A = A_in;   // work copy (row-major)
    std::vector<double> b = b_in;   // work copy
    x.assign(N, 0.0);

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Find pivot
        size_t pivot = k;
        double maxabs = std::fabs(A[k*N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(A[i*N + k]);
            if (v > maxabs) { maxabs = v; pivot = i; }
        }
        if (maxabs < 1e-12) throw std::runtime_error("Singular or ill-conditioned matrix");

        // Swap rows if needed
        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(A[k*N + j], A[pivot*N + j]);
            std::swap(b[k], b[pivot]);
        }

        double Akk = A[k*N + k];

        // Eliminate below pivot in parallel over rows i
        auto first = hpx::counting_iterator<size_t>(k + 1);
        auto last  = hpx::counting_iterator<size_t>(N);
        hpx::for_each(hpx::execution::par, first, last, [&](size_t i) {
            double factor = A[i*N + k] / Akk;
            A[i*N + k] = 0.0; // explicitly zero the column
            // Update remaining columns
            for (size_t j = k + 1; j < N; ++j) {
                A[i*N + j] -= factor * A[k*N + j];
            }
            b[i] -= factor * b[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = b[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            sum -= A[static_cast<size_t>(i)*N + j] * x[j];
        }
        double diag = A[static_cast<size_t>(i)*N + static_cast<size_t>(i)];
        if (std::fabs(diag) < 1e-12) throw std::runtime_error("Singular or ill-conditioned matrix");
        x[static_cast<size_t>(i)] = sum / diag;
    }
}

