void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t piv = k;
        double maxabs = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (piv != k) {
            // Swap rows in parallel
            hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
                std::swap(M[idx(k, j)], M[idx(piv, j)]);
            });
            std::swap(rhs[k], rhs[piv]);
        }

        double diag = M[idx(k, k)];
        // Eliminate below pivot: parallel over rows
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[idx(i, k)] / diag;
            if (factor == 0.0) return;
            // Update row entries
            for (size_t j = k + 1; j < N; ++j) {
                M[idx(i, j)] -= factor * M[idx(k, j)];
            }
            rhs[i] -= factor * rhs[k];
            M[idx(i, k)] = 0.0;
        });
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = hpx::transform_reduce(
            hpx::execution::par, M.begin() + idx(i, i + 1), M.begin() + idx(i, N),
            x.begin() + (i + 1), 0.0, std::plus<double>(),
            [](double a_ij, double xj) { return a_ij * xj; }
        );
        double denom = M[idx(i, i)];
        if (denom == 0.0) throw std::runtime_error("Singular matrix");
        x[size_t(i)] = (rhs[size_t(i)] - sum) / denom;
    }
}

