void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (A.size() != N*N || b.size() != N) throw std::invalid_argument("Size mismatch");
    x.resize(N);

    std::vector<double> M = A;       // working copy of A
    std::vector<double> y = b;       // working copy of b

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Find pivot
        size_t piv = k;
        double maxabs = std::fabs(M[k*N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(M[i*N + k]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs < eps) throw std::runtime_error("Matrix is singular or near-singular");

        // Swap rows if needed
        if (piv != k) {
            for (size_t j = k; j < N; ++j)
                std::swap(M[k*N + j], M[piv*N + j]);
            std::swap(y[k], y[piv]);
        }

        double pivot = M[k*N + k];

        // Eliminate below pivot in parallel by rows
        std::vector<hpx::future<void>> futs;
        futs.reserve(N - (k + 1));
        for (size_t i = k + 1; i < N; ++i) {
            futs.push_back(hpx::async([&, i, k, pivot, N] {
                double factor = M[i*N + k] / pivot;
                M[i*N + k] = 0.0;
                for (size_t j = k + 1; j < N; ++j)
                    M[i*N + j] -= factor * M[k*N + j];
                y[i] -= factor * y[k];
            }));
        }
        hpx::wait_all(futs);
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double s = y[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j)
            s -= M[static_cast<size_t>(i)*N + j] * x[j];
        double diag = M[static_cast<size_t>(i)*N + static_cast<size_t>(i)];
        if (std::fabs(diag) < eps) throw std::runtime_error("Matrix is singular or near-singular");
        x[static_cast<size_t>(i)] = s / diag;
    }
}

