   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
{
    // Basic checks
    if (A.size() != N * N || b.size() != N) {
        throw std::invalid_argument("Invalid sizes for A or b");
    }
    x.assign(N, 0.0);

    // Work copies
    std::vector<double> M = A;
    std::vector<double> rhs = b;

    auto idx = [N](size_t r, size_t c) { return r * N + c; };
    auto at = [&](size_t r, size_t c) -> double& { return M[idx(r, c)]; };

    constexpr double eps = 1e-12;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Pivot selection
        size_t piv = k;
        double maxabs = std::abs(at(k, k));
        for (size_t i = k + 1; i < N; ++i) {
            double val = std::abs(at(i, k));
            if (val > maxabs) {
