        if (piv != k) {
            for (size_t j = 0; j < N; ++j) {
                std::swap(at(k, j), at(piv, j));
            }
            std::swap(rhs[k], rhs[piv]);
        }

        // Normalize pivot row
        double pivot = at(k, k);
        for (size_t j = k; j < N; ++j) at(k, j) /= pivot;
        rhs[k] /= pivot;

        // Eliminate below pivot in parallel
        std::vector<hpx::future<void>> futs;
        futs.reserve(N - k - 1);
        for (size_t i = k + 1; i < N; ++i) {
            futs.push_back(hpx::async([&, i] {
                double factor = at(i, k);
                if (factor == 0.0) return;
                for (size_t j = k; j < N; ++j) {
                    at(i, j) -= factor * at(k, j);
                }
                rhs[i] -= factor * rhs[k];
                at(i, k) = 0.0;
            }));
        }
        hpx::wait_all(futs);
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double s = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            s -= at(static_cast<size_t>(i), j) * x[j];
        }
        x[static_cast<size_t>(i)] = s; // diagonal is 1 due to normalization
    }
}

