                if (std::abs(factor) < 1e-300) {
                    a[idx(i, k)] = 0.0;
                    return;
                }
                a[idx(i, k)] = 0.0;
                for (size_t j = k + 1; j < N; ++j)
                    a[idx(i, j)] -= factor * a[idx(k, j)];
                rhs[i] -= factor * rhs[k];
            }));
        }
        hpx::when_all(tasks).wait();
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j)
            sum += a[idx(i, j)] * x[j];
        double diag = a[idx(i, i)];
        if (std::abs(diag) < eps) throw std::runtime_error("Singular matrix");
        x[i] = (rhs[i] - sum) / diag;
    }
}

