   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (A.size() != N * N || b.size() != N) {
        throw std::invalid_argument("Dimension mismatch");
    }
    x.assign(N, 0.0);

    // Work copies
    std::vector<double> M(A.begin(), A.end());
    std::vector<double> y(b.begin(), b.end());

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Pivot selection
        size_t p = k;
        double max_abs = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > max_abs) {
                max_abs = v;
                p = i;
            }
        }
        if (max_abs == 0.0) {
            throw std::runtime_error("Singular matrix");
        }
        // Swap rows if needed
        if (p != k) {
            for (size_t j = k; j < N; ++j) {
                std::swap(M[idx(k, j)], M[idx(p, j)]);
            }
            std::swap(y[k], y[p]);
        }

        double pivot = M[idx(k, k)];

        // Eliminate rows below pivot in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[idx(i, k)] / pivot;
            M[idx(i, k)] = 0.0;
            // Update rest of row i
            for (size_t j = k + 1; j < N; ++j) {
                M[idx(i, j)] -= factor * M[idx(k, j)];
            }
            y[i] -= factor * y[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) {
            sum += M[idx(i, j)] * x[j];
        }
        double diag = M[idx(i, i)];
        if (diag == 0.0) {
            throw std::runtime_error("Singular matrix on back substitution");
        }
        x[i] = (y[i] - sum) / diag;
    }
}

