void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };
    const double eps = 1e-12;

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t p = k;
        double maxv = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > maxv) { maxv = v; p = i; }
        }
        if (maxv < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        if (p != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[idx(k, j)], M[idx(p, j)]);
            std::swap(rhs[k], rhs[p]);
        }

        double piv = M[idx(k, k)];

        // Eliminate below pivot in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[idx(i, k)] / piv;
            M[idx(i, k)] = 0.0;
            for (size_t j = k + 1; j < N; ++j)
                M[idx(i, j)] -= factor * M[idx(k, j)];
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double s = 0.0;
        for (size_t j = i + 1; j < N; ++j) s += M[idx(i, j)] * x[j];
        double piv = M[idx(i, i)];
        if (std::abs(piv) < eps) throw std::runtime_error("Singular or ill-conditioned matrix");
        x[i] = (rhs[i] - s) / piv;
    }
}

