    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");

    std::vector<double> U = A;
    std::vector<double> y = b;
    x.assign(N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t p = k;
        double maxabs = std::abs(U[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(U[i * N + k]);
            if (v > maxabs) { maxabs = v; p = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (p != k) {
            for (size_t j = k; j < N; ++j) std::swap(U[p * N + j], U[k * N + j]);
            std::swap(y[p], y[k]);
        }

        double pivot = U[k * N + k];

        // Elimination (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = U[i * N + k] / pivot;
            U[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j)
                U[i * N + j] -= factor * U[k * N + j];
            y[i] -= factor * y[k];
        });
    }

    // Back substitution (sequential)
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += U[i * N + j] * x[j];
        double denom = U[i * N + i];
        if (denom == 0.0) throw std::runtime_error("Singular matrix");
        x[i] = (y[i] - sum) / denom;
    }
}

