    std::vector<double> M = A;       // working copy of A (row-major)
    std::vector<double> rhs = b;     // working copy of b

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t pivot = k;
        double maxabs = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i * N + k]);
            if (v > maxabs) { maxabs = v; pivot = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k * N + j], M[pivot * N + j]);
            std::swap(rhs[k], rhs[pivot]);
        }

        double diag = M[k * N + k];
        // Normalize pivot row
        hpx::for_loop(par, k, N, [&](size_t j) { M[k * N + j] /= diag; });
        rhs[k] /= diag;

        // Eliminate rows below
        hpx::for_loop(par, k + 1, N, [&](size_t i) {
            double factor = M[i * N + k];
            if (factor == 0.0) {
                M[i * N + k] = 0.0;
                return;
            }
            M[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[i * N + j] -= factor * M[k * N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution (upper triangular with unit diagonal)
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            sum -= M[static_cast<size_t>(i) * N + j] * x[j];
        }
        x[static_cast<size_t>(i)] = sum;
    }
}

