{
    // Copy inputs to mutable storage
    std::vector<double> a(A.begin(), A.end());
    std::vector<double> y(b.begin(), b.end());
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };
    const double eps = 1e-12;

    for (size_t k = 0; k < N; ++k)
    {
        // Pivot selection (partial pivoting)
        size_t pivot = k;
        double maxabs = std::abs(a[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i)
        {
            double v = std::abs(a[idx(i, k)]);
            if (v > maxabs)
            {
                maxabs = v;
                pivot = i;
            }
        }
        if (maxabs < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        // Swap rows if needed
        if (pivot != k)
