/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
{
    // Preconditions
    if (A.size() != N * N || b.size() != N) {
        throw std::invalid_argument("Invalid dimensions");
    }
    x.resize(N);

    // Work copies since A is const
    std::vector<double> M = A;
    std::vector<double> rhs = b;

    auto idx = [N](size_t i, size_t j) { return i * N + j; };
    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Pivot selection (sequential)
        size_t piv = k;
        double maxv = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > maxv) { maxv = v; piv = i; }
        }
        if (maxv < eps) {
            throw std::runtime_error("Singular or ill-conditioned matrix");
        }

        // Row swap if needed
        if (piv != k) {
            for (size_t j = k; j < N; ++j) {
                std::swap(M[idx(k, j)], M[idx(piv, j)]);
            }
            std::swap(rhs[k], rhs[piv]);
        }

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[idx(i, k)] / M[idx(k, k)];
            M[idx(i, k)] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[idx(i, j)] -= factor * M[idx(k, j)];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution (sequential)
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            sum -= M[idx(static_cast<size_t>(i), j)] * x[j];
        }
        double diag = M[idx(static_cast<size_t>(i), static_cast<size_t>(i))];
        if (std::abs(diag) < eps) {
            throw std::runtime_error("Singular or ill-conditioned matrix");
        }
        x[static_cast<size_t>(i)] = sum / diag;
    }
}

