void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) {
        throw std::invalid_argument("Dimension mismatch");
    }

    std::vector<double> M = A;      // mutable copy of A
    std::vector<double> rhs = b;    // mutable copy of b
    x.assign(N, 0.0);

    for (std::size_t k = 0; k < N; ++k) {
        // Partial pivoting
        std::size_t pivot = k;
        double maxabs = std::abs(M[k * N + k]);
        for (std::size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i * N + k]);
            if (v > maxabs) {
                maxabs = v;
                pivot = i;
            }
        }
        if (maxabs == 0.0) {
            throw std::runtime_error("Singular matrix");
        }
        if (pivot != k) {
            for (std::size_t j = 0; j < N; ++j) {
                std::swap(M[pivot * N + j], M[k * N + j]);
            }
            std::swap(rhs[pivot], rhs[k]);
        }

        double pivot_val = M[k * N + k];

        // Elimination (parallel over rows below pivot)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](std::size_t i) {
            double factor = M[i * N + k] / pivot_val;
            M[i * N + k] = 0.0;
            for (std::size_t j = k + 1; j < N; ++j) {
                M[i * N + j] -= factor * M[k * N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        std::size_t i = static_cast<std::size_t>(ii);
        double sum = 0.0;
        for (std::size_t j = i + 1; j < N; ++j) {
            sum += M[i * N + j] * x[j];
        }
        double diag = M[i * N + i];
        if (diag == 0.0) {
            throw std::runtime_error("Zero diagonal encountered");
        }
        x[i] = (rhs[i] - sum) / diag;
    }
}

