void solveLinearSystem(std::vector<double> const& Ain, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (Ain.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    // Work copies (we’ll modify in place)
    std::vector<double> A = Ain;
    std::vector<double> rhs = b;

    for (size_t i = 0; i < N; ++i) {
        // Partial pivoting
        size_t piv = i;
        double maxabs = std::abs(A[idx(i, i)]);
        for (size_t r = i + 1; r < N; ++r) {
            double v = std::abs(A[idx(r, i)]);
            if (v > maxabs) { maxabs = v; piv = r; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (piv != i) {
            for (size_t c = i; c < N; ++c) std::swap(A[idx(i, c)], A[idx(piv, c)]);
            std::swap(rhs[i], rhs[piv]);
        }

        double pivval = A[idx(i, i)];
        if (std::abs(pivval) < 1e-15) throw std::runtime_error("Numerically singular matrix");

        // Eliminate below pivot in parallel over rows
        auto beg = hpx::make_counting_iterator<std::size_t>(i + 1);
        auto end = hpx::make_counting_iterator<std::size_t>(N);
        hpx::for_each(hpx::execution::par, beg, end, [&](std::size_t r) {
            double factor = A[idx(r, i)] / pivval;
            if (factor != 0.0) {
                A[idx(r, i)] = 0.0;
                for (size_t c = i + 1; c < N; ++c)
                    A[idx(r, c)] -= factor * A[idx(i, c)];
                rhs[r] -= factor * rhs[i];
            }
        });
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double s = rhs[size_t(i)];
        for (size_t c = size_t(i) + 1; c < N; ++c)
            s -= A[idx(size_t(i), c)] * x[c];
        x[size_t(i)] = s / A[idx(size_t(i), size_t(i))];
    }
}

