    if (A.size() != N*N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    auto row = [&](size_t i, size_t j) -> double& { return M[i*N + j]; };

    for (size_t k = 0; k < N; ++k) {
        // Pivot
        size_t p = k;
        double maxabs = std::abs(row(k,k));
        for (size_t i = k+1; i < N; ++i) {
            double val = std::abs(row(i,k));
            if (val > maxabs) { maxabs = val; p = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (p != k) {
            for (size_t j = k; j < N; ++j) std::swap(row(k,j), row(p,j));
            std::swap(rhs[k], rhs[p]);
        }

        double pivot = row(k,k);
        // Eliminate below pivot in parallel
        std::vector<size_t> rows;
        rows.reserve(N - (k+1));
        for (size_t i = k+1; i < N; ++i) rows.push_back(i);

        hpx::ranges::for_each(hpx::execution::par, rows, [&](size_t i) {
            double factor = row(i,k) / pivot;
            row(i,k) = 0.0;
            for (size_t j = k+1; j < N; ++j) {
                row(i,j) -= factor * row(k,j);
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += row(i,j) * x[j];
        double diag = row(i,i);
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        x[i] = (rhs[i] - sum) / diag;
    }
}

