void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (A.size() != N*N || b.size() != N)
        throw std::invalid_argument("Dimension mismatch");

    std::vector<double> M = A;       // working copy of A
    std::vector<double> rhs = b;     // working copy of b
    x.assign(N, 0.0);

    auto idx = [N](size_t i, size_t j) { return i*N + j; };

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k)
    {
        // Find pivot
        size_t p = k;
        double maxabs = std::fabs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i)
        {
            double v = std::fabs(M[idx(i, k)]);
            if (v > maxabs) { maxabs = v; p = i; }
        }
        if (maxabs == 0.0)
            throw std::runtime_error("Singular matrix");

        // Swap rows if needed
        if (p != k)
        {
            for (size_t j = k; j < N; ++j)
                std::swap(M[idx(k, j)], M[idx(p, j)]);
            std::swap(rhs[k], rhs[p]);
        }

        double pivot = M[idx(k, k)];

        // Eliminate rows below pivot in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i)
        {
            double factor = M[idx(i, k)] / pivot;
            if (factor == 0.0) return;

            // Update row i from column k to end
            for (size_t j = k; j < N; ++j)
                M[idx(i, j)] -= factor * M[idx(k, j)];
            rhs[i] -= factor * rhs[k];
            M[idx(i, k)] = 0.0; // keep it clean
        });
    }

    // Back substitution
    for (ptrdiff_t i = static_cast<ptrdiff_t>(N) - 1; i >= 0; --i)
    {
        double sum = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j)
            sum -= M[idx(static_cast<size_t>(i), j)] * x[j];

        double diag = M[idx(static_cast<size_t>(i), static_cast<size_t>(i))];
        if (diag == 0.0)
            throw std::runtime_error("Singular matrix during back substitution");
        x[static_cast<size_t>(i)] = sum / diag;
    }
}

