void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    x.assign(N, 0.0);
    if (A.size() != N*N || b.size() != N || N == 0) return;

    std::vector<double> M = A;
    std::vector<double> rhs = b;

    for (size_t k = 0; k < N; ++k) {
        // Pivot
        size_t pivot = k;
        double maxval = std::abs(M[k*N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double val = std::abs(M[i*N + k]);
            if (val > maxval) { maxval = val; pivot = i; }
        }
        if (maxval == 0.0) return; // singular

        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k*N + j], M[pivot*N + j]);
            std::swap(rhs[k], rhs[pivot]);
        }

        double diag = M[k*N + k];
        for (size_t j = k; j < N; ++j) M[k*N + j] /= diag;
        rhs[k] /= diag;

        // Eliminate below in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[i*N + k];
            if (factor == 0.0) return;
            M[i*N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[i*N + j] -= factor * M[k*N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i*N + j] * x[j];
        x[i] = rhs[i] - sum; // M[i*N+i] is 1 due to normalization
    }
}

