void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N || A.size() != N * N) throw std::invalid_argument("Dimension mismatch");
    if (N == 0) { x.clear(); return; }

    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // Pivot selection (serial for simplicity)
        size_t p = k;
        double maxv = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i * N + k]);
            if (v > maxv) { maxv = v; p = i; }
        }
        if (maxv == 0.0) throw std::runtime_error("Singular matrix");

        // Swap rows k and p (parallel over columns)
        if (p != k) {
            hpx::for_loop(hpx::execution::par, k, static_cast<long>(N), [&](long j) {
                std::swap(M[k * N + static_cast<size_t>(j)], M[p * N + static_cast<size_t>(j)]);
