        hpx::for_loop(hpx::execution::par, static_cast<long>(k + 1), static_cast<long>(N), [&](long il) {
            size_t i = static_cast<size_t>(il);
            double factor = M[i * N + k] / pivot;
            if (factor != 0.0) {
                for (size_t j = k; j < N; ++j) {
                    M[i * N + j] -= factor * M[k * N + j];
                }
                rhs[i] -= factor * rhs[k];
            }
        });
    }

    // Back substitution (serial; low complexity vs elimination)
    for (long il = static_cast<long>(N) - 1; il >= 0; --il) {
        size_t i = static_cast<size_t>(il);
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i * N + j] * x[j];
        double diag = M[i * N + i];
        if (diag == 0.0) throw std::runtime_error("Singular matrix during back substitution");
