void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    x.resize(N);

    std::vector<double> M = A;
    std::vector<double> rhs = b;

    const double eps = 1e-12;

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t pivot = k;
        double maxabs = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double val = std::abs(M[i * N + k]);
            if (val > maxabs) {
                maxabs = val;
                pivot = i;
            }
        }
        if (maxabs < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k * N + j], M[pivot * N + j]);
            std::swap(rhs[k], rhs[pivot]);
        }

        double diag = M[k * N + k];

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[i * N + k] / diag;
            M[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                M[i * N + j] -= factor * M[k * N + j];
            }
            rhs[i] -= factor * rhs[k];
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = rhs[static_cast<size_t>(i)];
        for (size_t j = static_cast<size_t>(i) + 1; j < N; ++j) {
            sum -= M[static_cast<size_t>(i) * N + j] * x[j];
        }
        x[static_cast<size_t>(i)] = sum / M[static_cast<size_t>(i) * N + static_cast<size_t>(i)];
    }
}

