void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    x.assign(N, 0.0);
    if (N == 0) return;

    std::vector<double> M = A;
    std::vector<double> y = b;

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t pivot = k;
        double maxval = std::abs(M[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i * N + k]);
            if (v > maxval) {
                maxval = v;
                pivot = i;
            }
        }
        if (maxval == 0.0) throw std::runtime_error("Singular matrix");

        if (pivot != k) {
            for (size_t c = k; c < N; ++c) std::swap(M[k * N + c], M[pivot * N + c]);
            std::swap(y[k], y[pivot]);
        }

        double diag = M[k * N + k];
        // Eliminate below pivot in parallel by rows
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t j) {
            double factor = M[j * N + k] / diag;
            // Update row j from column k+1 onward
            for (size_t i = k + 1; i < N; ++i) {
                M[j * N + i] -= factor * M[k * N + i];
            }
            y[j] -= factor * y[k];
            M[j * N + k] = 0.0;
        });
    }

    // Back substitution
    for (int i = static_cast<int>(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[i * N + j] * x[j];
        double diag = M[i * N + i];
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        x[i] = (y[i] - sum) / diag;
    }
}

