void solveLinearSystem(std::vector<double> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (A.size() != N*N || b.size() != N) throw std::invalid_argument("size mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Find pivot
        size_t piv = k;
        double maxabs = std::abs(M[k*N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i*N + k]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs < eps) throw std::runtime_error("singular or ill-conditioned matrix");

        // Swap rows
        if (piv != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k*N + j], M[piv*N + j]);
            std::swap(rhs[k], rhs[piv]);
        }

        double Akk = M[k*N + k];

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double f = M[i*N + k] / Akk;
            M[i*N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j)
                M[i*N + j] -= f * M[k*N + j];
            rhs[i] -= f * rhs[k];
        });
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = rhs[size_t(i)];
        for (size_t j = size_t(i) + 1; j < N; ++j)
            sum -= M[size_t(i)*N + j] * x[j];
        double diag = M[size_t(i)*N + size_t(i)];
        if (std::abs(diag) < eps) throw std::runtime_error("singular or ill-conditioned matrix");
        x[size_t(i)] = sum / diag;
    }
}

