    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting: find row with max abs in column k from k..N-1
        size_t piv = k;
        double maxabs = std::abs(M[k*N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[i*N + k]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        // Swap rows if needed
        if (piv != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[k*N + j], M[piv*N + j]);
            std::swap(rhs[k], rhs[piv]);
        }

        double pivot = M[k*N + k];

        // Eliminate below pivot in parallel over rows i=k+1..N-1
        std::vector<size_t> rows;
        rows.reserve(N - (k + 1));
        for (size_t i = k + 1; i < N; ++i) rows.push_back(i);

        hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
            [&](size_t i) {
                double factor = M[i*N + k] / pivot;
                // Update row entries j=k+1..N-1
                for (size_t j = k + 1; j < N; ++j) {
                    M[i*N + j] -= factor * M[k*N + j];
                }
                M[i*N + k] = 0.0;
                rhs[i] -= factor * rhs[k];
            }
        );
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = rhs[size_t(i)];
        for (size_t j = size_t(i) + 1; j < N; ++j) {
            sum -= M[size_t(i)*N + j] * x[j];
        }
        double diag = M[size_t(i)*N + size_t(i)];
        if (std::abs(diag) < eps) throw std::runtime_error("Singular or ill-conditioned matrix");
        x[size_t(i)] = sum / diag;
    }
}

