    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t piv = k;
        double maxabs = std::fabs(M[idx(k, k, N)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(M[idx(i, k, N)]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs < eps) throw std::runtime_error("Singular or ill-conditioned matrix");

        if (piv != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[idx(k, j, N)], M[idx(piv, j, N)]);
