void solveLinearSystem(std::vector<double> const& Ain, std::vector<double> const& bin, std::vector<double> &x, size_t N) {
    if (Ain.size() != N * N || bin.size() != N) throw std::invalid_argument("Dimension mismatch");
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    // Work copies (A modified in-place)
    std::vector<double> A = Ain;
    std::vector<double> b = bin;

    // Gaussian elimination with partial pivoting
    for (size_t k = 0; k < N; ++k) {
        // Pivot
        size_t piv = k;
        double maxabs = std::fabs(A[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(A[idx(i, k)]);
            if (v > maxabs) { maxabs = v; piv = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (piv != k) {
            for (size_t j = k; j < N; ++j) std::swap(A[idx(k, j)], A[idx(piv, j)]);
            std::swap(b[k], b[piv]);
        }

        double Akk = A[idx(k, k)];
        // Eliminate below pivot in parallel
        std::vector<hpx::future<void>> futs;
        futs.reserve(N - k - 1);
        for (size_t i = k + 1; i < N; ++i) {
            futs.push_back(hpx::async([&, i, k, Akk]() {
                double m = A[idx(i, k)] / Akk;
                A[idx(i, k)] = 0.0;
                for (size_t j = k + 1; j < N; ++j) {
                    A[idx(i, j)] -= m * A[idx(k, j)];
                }
                b[i] -= m * b[k];
            }));
        }
        hpx::wait_all(futs);
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = b[size_t(i)];
        for (size_t j = size_t(i) + 1; j < N; ++j) sum -= A[idx(size_t(i), j)] * x[j];
        double diag = A[idx(size_t(i), size_t(i))];
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        x[size_t(i)] = sum / diag;
    }
}

