void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> r = b;
    x.assign(N, 0.0);

    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting
        size_t pivot = k;
        double maxabs = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double val = std::abs(M[idx(i, k)]);
            if (val > maxabs) { maxabs = val; pivot = i; }
        }
        if (maxabs == 0.0) throw std::runtime_error("Singular matrix");

        if (pivot != k) {
            for (size_t j = k; j < N; ++j) std::swap(M[idx(k, j)], M[idx(pivot, j)]);
            std::swap(r[k], r[pivot]);
        }

        double pivot_val = M[idx(k, k)];

        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double factor = M[idx(i, k)] / pivot_val;
            M[idx(i, k)] = 0.0;
            for (size_t j = k + 1; j < N; ++j)
                M[idx(i, j)] -= factor * M[idx(k, j)];
            r[i] -= factor * r[k];
        });
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j) sum += M[idx(i, j)] * x[j];
        x[i] = (r[size_t(i)] - sum) / M[idx(size_t(i), size_t(i))];
    }
}

