void solveLinearSystem(std::vector<double> const& Ain, std::vector<double> const& bin, std::vector<double> &x, size_t N) {
    if (Ain.size() != N * N || bin.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> A = Ain;           // local mutable copy
    std::vector<double> b = bin;
    x.assign(N, 0.0);

    for (size_t i = 0; i < N; ++i) {
        // Partial pivoting (sequential for stability)
        size_t piv = i;
        double maxv = std::abs(A[i*N + i]);
        for (size_t r = i + 1; r < N; ++r) {
            double v = std::abs(A[r*N + i]);
            if (v > maxv) { maxv = v; piv = r; }
        }
        if (maxv == 0.0) throw std::runtime_error("Singular matrix");

        if (piv != i) {
            for (size_t c = i; c < N; ++c) std::swap(A[i*N + c], A[piv*N + c]);
            std::swap(b[i], b[piv]);
        }

        double diag = A[i*N + i];

        // Eliminate below pivot: parallel over rows
        hpx::for_loop(hpx::execution::par, i + 1, N, [&](size_t k) {
            double factor = A[k*N + i] / diag;
            A[k*N + i] = 0.0;
            for (size_t j = i + 1; j < N; ++j)
                A[k*N + j] -= factor * A[i*N + j];
            b[k] -= factor * b[i];
        });
    }

    // Back substitution (sequential, tiny compared to elimination)
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = b[size_t(i)];
        for (size_t j = size_t(i) + 1; j < N; ++j)
            sum -= A[size_t(i)*N + j] * x[j];
        double diag = A[size_t(i)*N + size_t(i)];
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        x[size_t(i)] = sum / diag;
    }
}

