   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (A.size() != N * N || b.size() != N) throw std::invalid_argument("Dimension mismatch");
    std::vector<double> M = A;
    std::vector<double> rhs = b;
    x.assign(N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    for (size_t k = 0; k < N; ++k) {
        // Partial pivoting (serial)
        size_t piv = k;
        double maxv = std::abs(M[idx(k, k)]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::abs(M[idx(i, k)]);
            if (v > maxv) { maxv = v; piv = i; }
        }
        if (maxv == 0.0) throw std::runtime_error("Singular matrix");

        // Swap rows in parallel if needed
        if (piv != k) {
            hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t j) {
                std::swap(M[idx(k, j)], M[idx(piv, j)]);
            });
            std::swap(rhs[k], rhs[piv]);
        }

        double pivot = M[idx(k, k)];
        // Eliminate below pivot (parallel over rows)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double f = M[idx(i, k)] / pivot;
            M[idx(i, k)] = 0.0;
            for (size_t j = k + 1; j < N; ++j)
                M[idx(i, j)] -= f * M[idx(k, j)];
            rhs[i] -= f * rhs[k];
        });
    }

    // Back substitution
    for (int i = int(N) - 1; i >= 0; --i) {
        double sum = hpx::transform_reduce(
            hpx::execution::par,
            M.data() + idx(size_t(i), size_t(i + 1)),
            M.data() + idx(size_t(i), N),
            x.data() + size_t(i + 1),
            0.0,
            std::plus<double>(),
            [](double aij, double xj) { return aij * xj; }
        );
        double diag = M[idx(size_t(i), size_t(i))];
        if (diag == 0.0) throw std::runtime_error("Singular matrix");
        x[size_t(i)] = (rhs[size_t(i)] - sum) / diag;
    }
}

