void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C,
          size_t M, size_t K, size_t N)
{
    if (C.size() != M * N) C.assign(M * N, 0.0);
    else std::fill(C.begin(), C.end(), 0.0);

    auto const* Ad = A.data();
    auto const* Bd = B.data();
    auto* Cd = C.data();

    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        auto const* Ai = Ad + i * K;
        auto* Ci = Cd + i * N;

        for (size_t k = 0; k < K; ++k) {
            double aik = Ai[k];
            auto const* Bk = Bd + k * N;

            for (size_t j = 0; j < N; ++j) {
                Ci[j] += aik * Bk[j];
            }
        }
    });
}

