/* Multiply the matrix A by the matrix B. Store the results in the matrix C.
   A is an MxK matrix, B is a KxN matrix, and C is a MxN matrix. The matrices are stored in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[[1, -1, 2], [0, -2, 1]] B=[[4, 1], [-1, 0], [2, 2]]
   output: C=[[9, 5], [4, 2]]
*/
void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {

generated_output:
{
    // Ensure C has correct size
    if (C.size() != M * N) C.assign(M * N, 0.0);

    std::size_t P = hpx::get_os_thread_count();
    std::size_t block = (M + P - 1) / P;

    std::vector<hpx::future<void>> futs;
    futs.reserve(P);

    for (std::size_t p = 0; p < P; ++p) {
        std::size_t start = p * block;
        if (start >= M) break;
        std::size_t end = std::min(M, start + block);

        futs.push_back(hpx::async([&, start, end]() {
            for (std::size_t i = start; i < end; ++i) {
                for (std::size_t j = 0; j < N; ++j) {
                    double sum = 0.0;
                    for (std::size_t k = 0; k < K; ++k) {
                        sum += A[i * K + k] * B[k * N + j];
                    }
                    C[i * N + j] = sum;
                }
            }
        }));
    }

    hpx::wait_all(futs);
}

