void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    if (C.size() != M * N) C.assign(M * N, 0.0);
    else std::fill(C.begin(), C.end(), 0.0);

    std::vector<hpx::future<void>> tasks;
    tasks.reserve(M);

    for (size_t i = 0; i < M; ++i) {
        tasks.emplace_back(hpx::async([&, i] {
            const double* arow = A.data() + i * K;
            double* crow = C.data() + i * N;

            for (size_t j = 0; j < N; ++j) {
                double s = 0.0;
                for (size_t p = 0; p < K; ++p) {
                    s += arow[p] * B[p * N + j];
                }
                crow[j] = s;
            }
        }));
    }

    hpx::wait_all(tasks);
}

