   input: x=[1, -5, 2, 9] y=[0, 4, 1, -1] alpha=2
   output: z=[2, -6, 5, 17]
*/
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {

generated_output:
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    if (x.size() != y.size()) {
        throw std::invalid_argument("x and y must have the same size");
    }
    z.resize(x.size());
    hpx::transform(hpx::execution::par, x.begin(), x.end(), y.begin(), z.begin(),
                   [alpha](double xi, double yi) { return alpha * xi + yi; });
}

