prompt:
#include <hpx/hpx_main.hpp>

/* Compute z = alpha*x+y where x and y are vectors. Store the result in z.
Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: x=[1, -5, 2, 9] y=[0, 4, 1, -1] alpha=2
   output: z=[2, -6, 5, 17]
*/
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {

generated_output:
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    assert(x.size() == y.size());
    z.resize(x.size());

    hpx::ranges::transform(
        hpx::execution::par_unseq,
        x, y, z.begin(),
        [alpha](double xi, double yi) { return alpha * xi + yi; }
    );
}

