void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    if (A.size() != M * N || x.size() != N || y.size() != M) {
        throw std::invalid_argument("Dimension mismatch");
    }

    auto first = hpx::util::counting_iterator<size_t>(0);
    auto last  = first + M;

    hpx::transform(
        hpx::execution::par, first, last, y.begin(),
        [&](size_t i) {
            double s = 0.0;
            size_t base = i * N;
            for (size_t j = 0; j < N; ++j) s += A[base + j] * x[j];
            return s;
        });
}

