void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    y.resize(M);
    auto first = hpx::util::counting_iterator<std::size_t>(0);
    auto last  = first + M;

    hpx::transform(hpx::execution::par, first, last, y.begin(),
        [&](std::size_t i) {
            double s = 0.0;
            std::size_t base = i * N;
            for (std::size_t j = 0; j < N; ++j)
                s += A[base + j] * x[j];
            return s;
        });
}

