void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    assert(A.size() == M * N);
    assert(x.size() == N);
    y.resize(M);

    auto first = hpx::make_counting_iterator<size_t>(0);
    auto last  = hpx::make_counting_iterator<size_t>(M);

    hpx::for_each(hpx::execution::par, first, last, [&](size_t i) {
        const double* row = &A[i * N];
        double sum = 0.0;
        for (size_t j = 0; j < N; ++j)
            sum += row[j] * x[j];
        y[i] = sum;
    });
}

