        throw std::invalid_argument("Dimension mismatch");
    }

    y.resize(M);

    std::vector<std::size_t> idx(M);
    std::iota(idx.begin(), idx.end(), 0);

    hpx::for_each(hpx::execution::par, idx.begin(), idx.end(),
        [&](std::size_t i) {
