#include <hpx/hpx_main.hpp>

struct COOElement {
   size_t row, column;
   double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) throw std::invalid_argument("b size != N");
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);
    rows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
    }
    std::vector<double> diag(N, 0.0);
    for (size_t i = 0; i < N; ++i) {
        for (auto const& [c, v] : rows[i]) {
            if (c == i) { diag[i] = v; break; }
        }
        if (diag[i] == 0.0) throw std::runtime_error("Zero/absent diagonal entry at row " + std::to_string(i));
    }
    if (x.size() != N) x.assign(N, 0.0);

    auto matvec = [&](std::vector<double> const& xv, std::vector<double>& y) {
        y.assign(N, 0.0);
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double s = 0.0;
            for (auto const& [c, v] : rows[i]) s += v * xv[c];
            y[i] = s;
        });
    };

    const size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old = x, x_new(N, 0.0), Ax(N, 0.0), r(N, 0.0);

    // Initial residual
    matvec(x_old, Ax);
    double res = 0.0;
    {
        double sum = 0.0;
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double ri = b[i] - Ax[i];
            r[i] = ri;
        });
        for (size_t i = 0; i < N; ++i) sum += r[i]*r[i];
        res = std::sqrt(sum);
    }

    size_t it = 0;
    while (res > tol && it < max_iters) {
        // Jacobi update
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double sigma = 0.0;
            for (auto const& [c, v] : rows[i]) {
                if (c != i) sigma += v * x_old[c];
            }
            x_new[i] = (b[i] - sigma) / diag[i];
        });

        // Check residual with new x
        matvec(x_new, Ax);
        double sum = 0.0;
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double ri = b[i] - Ax[i];
            r[i] = ri;
        });
        for (size_t i = 0; i < N; ++i) sum += r[i]*r[i];
        res = std::sqrt(sum);

        x_old.swap(x_new);
        ++it;
    }

    x = std::move(x_old);
    if (res > tol) throw std::runtime_error("Jacobi did not converge");
}

