void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    // Build row-wise structure and diagonals
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) continue;
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] = e.value;
    }

    // Initialize x
    if (x.size() != N) x.assign(N, 0.0);

    std::vector<double> x_new(N, 0.0);
    std::vector<double> Ax(N, 0.0);

    auto matvec = [&](std::vector<double> const& xv, std::vector<double>& yv) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double s = 0.0;
            for (auto const& ij : rows[i]) s += ij.second * xv[ij.first];
            yv[i] = s;
        });
    };

    const double tol = 1e-10;
    const int max_iters = 10000;

    // Precompute ||b|| for relative tolerance
    double nb = std::sqrt(hpx::transform_reduce(
        hpx::execution::par, b.begin(), b.end(), 0.0,
        std::plus<>(), [](double v){ return v*v; }));

    for (int it = 0; it < max_iters; ++it) {
        // Jacobi update in parallel
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double s = 0.0;
            for (auto const& ij : rows[i]) {
                if (ij.first != i) s += ij.second * x[ij.first];
            }
            // If diagonal is zero, keep previous value (or could handle pivoting)
            x_new[i] = (diag[i] != 0.0) ? (b[i] - s) / diag[i] : x[i];
        });

        // Check residual r = b - A x_new
        matvec(x_new, Ax);
        double rsq = hpx::transform_reduce(
            hpx::execution::par, size_t(0), N, 0.0, std::plus<>(),
            [&](size_t i){
                double r = b[i] - Ax[i];
                return r*r;
            });
        double nr = std::sqrt(rsq);
        if (nr <= tol * (1.0 + nb)) {
            x = std::move(x_new);
            return;
        }

        x.swap(x_new);
    }

    // If max iterations reached, return last iterate
    return;
}

