void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Group entries by row and capture diagonal
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (std::size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal; Jacobi not applicable");
    }

    std::vector<double> x_new(N, 0.0);
    std::vector<double> r(N, 0.0);

    const double tol = 1e-10;
    const std::size_t max_iter = 10000;

    for (std::size_t iter = 0; iter < max_iter; ++iter) {
        // Jacobi update
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sum = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) sum += e.value * x[e.column];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Compute residual r = b - A x_new
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double ax = 0.0;
            for (auto const& e : rows[i]) ax += e.value * x_new[e.column];
            r[i] = b[i] - ax;
        });

        double r2 = 0.0;
        for (double ri : r) r2 += ri * ri;
        if (r2 <= tol * tol) {
            x.swap(x_new);
            return;
        }

        x.swap(x_new);
    }

    // If reached here, max_iter hit; x holds last iterate
}

