void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) return;
    x.assign(N, 0.0);

    // Build row-wise structure and diagonals
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] += e.value;
    }

    // Ensure all diagonals are present
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) return; // singular or unsupported for Jacobi
    }

    // Precompute ||b||
    double bnorm2 = hpx::transform_reduce(hpx::execution::par, b.begin(), b.end(), 0.0,
                                          std::plus<double>(),
                                          [](double v){ return v*v; });
    double tol = 1e-10;
    double atol2 = tol*tol * (bnorm2 > 0.0 ? bnorm2 : 1.0);

    std::vector<double> x_new(N, 0.0);
    std::vector<double> r(N, 0.0);

    std::size_t max_iters = 10000;
    for (std::size_t iter = 0; iter < max_iters; ++iter) {
        // Jacobi update
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i){
            double sum = b[i];
            for (auto const& e : rows[i]) {
                if (e.column == i) continue;
                sum -= e.value * x[e.column];
            }
            x_new[i] = sum / diag[i];
        });

        // Swap
        x.swap(x_new);

        // Compute residual r = A x - b and its norm
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i){
            double ax = 0.0;
            for (auto const& e : rows[i]) {
                ax += e.value * x[e.column];
            }
            r[i] = ax - b[i];
        });

        double rnorm2 = hpx::transform_reduce(hpx::execution::par, r.begin(), r.end(), 0.0,
                                              std::plus<double>(),
                                              [](double v){ return v*v; });

        if (rnorm2 <= atol2) break;
    }
}

