void solveLinearSystem(std::vector<COOElement> const& Acoo, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    using hpx::execution::par;

    struct CSR {
        std::vector<size_t> row_ptr;
        std::vector<size_t> col_idx;
        std::vector<double> val;
    };

    auto coo_to_csr = [&](std::vector<COOElement> A) -> CSR {
        CSR csr;
        csr.row_ptr.assign(N + 1, 0);

        std::sort(A.begin(), A.end(), [](auto const& a, auto const& b){
            return a.row == b.row ? a.column < b.column : a.row < b.row;
        });

        csr.col_idx.resize(A.size());
        csr.val.resize(A.size());

        for (auto const& e : A) {
            if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of bounds in COO");
            csr.row_ptr[e.row + 1]++;
        }
        for (size_t i = 1; i <= N; ++i) csr.row_ptr[i] += csr.row_ptr[i - 1];

        std::vector<size_t> ctr = csr.row_ptr;
        for (auto const& e : A) {
            size_t p = ctr[e.row]++;
            csr.col_idx[p] = e.column;
            csr.val[p] = e.value;
        }
        return csr;
    };

    auto csr = coo_to_csr(Acoo);

    // Extract diagonal; ensure it exists and nonzero
    std::vector<double> diag(N, 0.0);
    hpx::for_loop(par, size_t(0), N, [&](size_t i){
        for (size_t p = csr.row_ptr[i]; p < csr.row_ptr[i + 1]; ++p) {
            if (csr.col_idx[p] == i) { diag[i] = csr.val[p]; break; }
        }
    });
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero or missing diagonal entry; Jacobi not applicable");

    auto spmv = [&](std::vector<double> const& v, std::vector<double>& y){
        y.assign(N, 0.0);
        hpx::for_loop(par, size_t(0), N, [&](size_t i){
            double s = 0.0;
            for (size_t p = csr.row_ptr[i]; p < csr.row_ptr[i + 1]; ++p)
                s += csr.val[p] * v[csr.col_idx[p]];
            y[i] = s;
        });
    };

    // Jacobi iteration
    const size_t max_iters = 10000;
    const double tol = 1e-12;

    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0), Ax(N), r(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        // x_new[i] = (b[i] - sum_{j!=i} A_ij x[j]) / A_ii
        hpx::for_loop(par, size_t(0), N, [&](size_t i){
            double sum = 0.0;
