/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");
    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi cannot proceed");
    }

    // Initial guess
    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);

    const double tol = 1e-10;
    const size_t max_iters = 10000;

    auto ib = hpx::make_counting_iterator<size_t>(0);
    auto ie = hpx::make_counting_iterator<size_t>(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        // Jacobi update in parallel over rows
        hpx::for_each(hpx::execution::par, ib, ie, [&](size_t i) {
            double sum = 0.0;
            for (auto const& [j, aij] : rows[i]) {
                if (j != i) sum += aij * x_old[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Convergence check: ||x_new - x_old||_2
        double diff2 = hpx::transform_reduce(
            hpx::execution::par, ib, ie, 0.0, std::plus<double>{},
            [&](size_t i) {
                double d = x_new[i] - x_old[i];
                return d * d;
            });

        if (std::sqrt(diff2) < tol) {
            x = x_new;
            return;
        }
        std::swap(x_old, x_new);
    }

    // If not converged, return last iterate
    x = x_old;
}

