   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    x.assign(N, 0.0);

    // Build per-row sparse structure
    std::vector<std::vector<std::pair<std::size_t, double>>> rows(N);
    rows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
    }

    // Diagonal
    std::vector<double> D(N, 0.0);
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        double di = 0.0;
        for (auto const& kv : rows[i]) {
            if (kv.first == i) di += kv.second;
        }
        D[i] = di;
    });
    for (std::size_t i = 0; i < N; ++i) {
        if (D[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi not applicable");
    }

    // Jacobi iterations
    const double tol = 1e-10;
    const std::size_t maxit = 10000;
    std::vector<double> x_new(N, 0.0), diff_sq(N, 0.0);

    for (std::size_t it = 0; it < maxit; ++it) {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double s = b[i];
            for (auto const& kv : rows[i]) {
                std::size_t j = kv.first;
                double aij = kv.second;
                if (j != i) s -= aij * x[j];
            }
            x_new[i] = s / D[i];
        });

        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double d = x_new[i] - x[i];
            diff_sq[i] = d * d;
        });
        double diff = hpx::reduce(hpx::execution::par, diff_sq.begin(), diff_sq.end(), 0.0);
        x.swap(x_new);
        if (std::sqrt(diff) < tol) break;
    }
}

