void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");
    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi cannot proceed");
    }

    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    // Initial guess: diagonal scaling
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
        x[i] = b[i] / diag[i];
    });

    // Precompute ||b||
    double bnorm = std::sqrt(std::inner_product(b.begin(), b.end(), b.begin(), 0.0));
    if (bnorm == 0.0) bnorm = 1.0;

    const double tol = 1e-10;
    const size_t max_iters = 10000;

    std::vector<size_t> idx(N);
    std::iota(idx.begin(), idx.end(), 0);

    for (size_t it = 0; it < max_iters; ++it) {
        // Jacobi update: x_new = x + (b - A x)/D
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double Ax_i = 0.0;
            for (auto const& kv : rows[i]) {
                Ax_i += kv.second * x[kv.first];
            }
            x_new[i] = x[i] + (b[i] - Ax_i) / diag[i];
        });

        // Residual norm ||b - A x_new||
        double r2 = hpx::transform_reduce(
            hpx::execution::par,
            idx.begin(), idx.end(),
            0.0, std::plus<double>{},
            [&](size_t i){
                double Ax_i = 0.0;
                for (auto const& kv : rows[i]) {
                    Ax_i += kv.second * x_new[kv.first];
                }
                double ri = b[i] - Ax_i;
                return ri * ri;
            });

        x.swap(x_new);

        if (std::sqrt(r2) / bnorm < tol) break;
    }
}

