void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    struct Entry { size_t col; double val; };

    std::vector<std::vector<Entry>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of bounds");
        if (e.row == e.column) diag[e.row] += e.value;
        else rows[e.row].push_back({e.column, e.value});
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(i));

    const double tol = 1e-12;
    const size_t max_iters = 10000;

    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);

    auto par = hpx::execution::par;
    auto first = hpx::util::counting_iterator<size_t>(0);
    auto last  = hpx::util::counting_iterator<size_t>(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& en : rows[i]) sum += en.val * x_old[en.col];
            x_new[i] = (b[i] - sum) / diag[i];
        });

        double maxdiff = hpx::transform_reduce(
            par, first, last, 0.0,
            hpx::maximum<double>(),
            [&](size_t i) { return std::abs(x_new[i] - x_old[i]); }
        );

        x_old.swap(x_new);
        if (maxdiff < tol) break;
    }

    x = std::move(x_old);
}

