void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       std::size_t N)
{
    if (x.size() != N) x.assign(N, 0.0);

    // r = A^T b - (A^T A) x; start with x=0 => r = A^T b
    std::vector<double> r = matvec_AT(A, b, N);
    std::vector<double> p = r;
    double rsold = dot_par(r, r);

    const double tol = 1e-10;
    const std::size_t maxit = std::max<std::size_t>(1000, 10*N);

    for (std::size_t k = 0; k < maxit; ++k) {
        // Ap = (A^T A) p = A^T (A p)
        std::vector<double> Ap = matvec_AT(A, matvec_A(A, p, N), N);

        double pAp = dot_par(p, Ap);
        if (std::fabs(pAp) < 1e-30) break;

        double alpha = rsold / pAp;

        // x = x + alpha p
        axpy_par(alpha, p, x);

        // r = r - alpha Ap
        std::vector<double> Ap_scaled = Ap;
        scal_par(alpha, Ap_scaled);
        hpx::for_each(hpx::execution::par, std::size_t(0), N,
                      [&](std::size_t i){ r[i] -= Ap_scaled[i]; });

        double rsnew = dot_par(r, r);
        if (std::sqrt(rsnew) < tol) break;

        double beta = rsnew / rsold;

        // p = r + beta p
        hpx::for_each(hpx::execution::par, std::size_t(0), N,
                      [&](std::size_t i){ p[i] = r[i] + beta * p[i]; });

        rsold = rsnew;
    }
}

