        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
            if (cols[k] == i) d += vals[k]; // sum if multiple diagonal entries
        }
        diag[i] = d;
    });
    for (size_t i = 0; i < N; ++i) {
