   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] = e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi cannot proceed");
    }

    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0), y(N, 0.0);

    auto idx_range = std::views::iota(size_t{0}, N);
    double bnorm2 = hpx::transform_reduce(hpx::execution::par, idx_range.begin(), idx_range.end(), 0.0,
                                          std::plus<>(), [&](size_t i) { return b[i] * b[i]; });
    double bnorm = std::sqrt(bnorm2);
    if (bnorm == 0.0) {
        // Solve Ax = 0 -> return zero vector
        std::fill(x.begin(), x.end(), 0.0);
        return;
    }

    const size_t max_iters = 10000;
    const double tol = 1e-10;

    for (size_t it = 0; it < max_iters; ++it) {
        // Jacobi update: x_new[i] = (b[i] - sum_{j!=i} A_ij x[j]) / A_ii
        hpx::for_loop(hpx::execution::par, size_t{0}, N, [&](size_t i) {
            double s = 0.0;
            for (auto const& [j, v] : rows[i]) {
                if (j != i) s += v * x[j];
            }
            x_new[i] = (b[i] - s) / diag[i];
        });

        x.swap(x_new);

        // Compute residual r = Ax - b
        hpx::for_loop(hpx::execution::par, size_t{0}, N, [&](size_t i) {
            double s = 0.0;
            for (auto const& [j, v] : rows[i]) s += v * x[j];
            y[i] = s - b[i];
        });

        double r2 = hpx::transform_reduce(hpx::execution::par, idx_range.begin(), idx_range.end(), 0.0,
                                          std::plus<>(), [&](size_t i) { return y[i] * y[i]; });
        if (std::sqrt(r2) / bnorm < tol) break;
    }
}

