   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) throw std::invalid_argument("b size != N");
    // Build row-wise storage and extract diagonal
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] += e.value; // allow sum if multiple entries
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered");

    if (x.size() != N) x.assign(N, 0.0);

    const double tol = 1e-10;
    const size_t max_iters = 10000;

    std::vector<double> x_new(N, 0.0);
    std::vector<double> diffs(N, 0.0);
    std::vector<size_t> indices(N);
    std::iota(indices.begin(), indices.end(), 0);

    for (size_t it = 0; it < max_iters; ++it) {
        // Jacobi update per row (in parallel)
        hpx::for_each(hpx::execution::par, indices.begin(), indices.end(),
            [&](size_t i) {
                double s = 0.0;
                for (auto const& e : rows[i]) {
                    if (e.column != i) s += e.value * x[e.column];
                }
                x_new[i] = (b[i] - s) / diag[i];
            });

        // Compute infinity-norm of update (in parallel)
        hpx::for_each(hpx::execution::par, indices.begin(), indices.end(),
            [&](size_t i) { diffs[i] = std::fabs(x_new[i] - x[i]); });

        double maxdiff = hpx::reduce(hpx::execution::par, diffs.begin(), diffs.end(), 0.0,
                                     [](double a, double b) { return a > b ? a : b; });

        x.swap(x_new);
        if (maxdiff < tol) break;
    }
}

