void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure
    std::vector<std::vector<COOElement>> rows(N);
    rows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
    }

    std::vector<double> x_new(N, 0.0);
    const size_t max_iters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double diag = 0.0, sum = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column == i) diag += e.value;
                else sum += e.value * x[e.column];
            }
            if (diag == 0.0) throw std::runtime_error("Zero diagonal entry encountered");
            x_new[i] = (b[i] - sum) / diag; // Jacobi
        });

        // Convergence check (infinity norm of update)
        double max_diff = 0.0;
        for (size_t i = 0; i < N; ++i) {
            double d = std::abs(x_new[i] - x[i]);
            if (d > max_diff) max_diff = d;
        }
        x.swap(x_new);
        if (max_diff < tol) break;
    }
}

