void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using std::size_t;
    if (b.size() != N) throw std::runtime_error("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("A index out of range");
        if (e.row == e.column) diag[e.row] += e.value;
        else rows[e.row].emplace_back(e.column, e.value);
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(i));

    std::vector<double> x_new(N, 0.0);

    const size_t max_iters = 10000;
    const double tol = 1e-10;

    for (size_t it = 0; it < max_iters; ++it) {
        // Jacobi update: x_new = D^{-1}(b - (L+U)x)
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& [j, v] : rows[i]) sum += v * x[j];
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Compute residual norm ||b - A x_new||_2
        double res2 = hpx::transform_reduce(
            hpx::execution::par,
            size_t(0), N, 0.0,
            std::plus<double>{},
            [&](size_t i) {
                double Ax_i = diag[i] * x_new[i];
                for (auto const& [j, v] : rows[i]) Ax_i += v * x_new[j];
                double r = b[i] - Ax_i;
                return r * r;
            }
        );

        if (std::sqrt(res2) < tol) {
            x.swap(x_new);
            return;
        }

        x.swap(x_new);
    }
    // If we reach here, max iterations hit; x holds the last iterate.
}

