void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    // Build per-row structure and diagonal
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        if (e.row == e.column) diag[e.row] += e.value;
        rows[e.row].emplace_back(e.column, e.value);
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi cannot proceed");
    }

    // Initial guess
    x.resize(N);
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        x[i] = b[i] / diag[i];
    });

    const size_t max_iters = 10000;
    const double tol = 1e-10;
    std::vector<double> x_new(N), diffs(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& kv : rows[i]) {
                if (kv.first != i) sum += kv.second * x[kv.first];
            }
            double xi = (b[i] - sum) / diag[i];
            x_new[i] = xi;
            diffs[i] = std::abs(xi - x[i]);
        });

        double max_diff = hpx::reduce(hpx::execution::par, diffs.begin(), diffs.end(), 0.0, hpx::maximum<double>());

        std::swap(x, x_new);
        if (max_diff < tol) break;
    }
}

