void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    using namespace hpx;

    if (b.size() != N) throw std::invalid_argument("b size != N");

    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] += e.value;
    }

    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi cannot proceed");
    }

    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);

    const std::size_t max_iter = 10000;
    const double tol = 1e-10;

    for (std::size_t it = 0; it < max_iter; ++it) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& kv : rows[i]) {
                size_t j = kv.first;
                double aij = kv.second;
                if (j != i) sum += aij * x_old[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Compute L2 norm of update
        double diff = hpx::transform_reduce(
            hpx::execution::par,
            size_t(0), N, 0.0,
            std::plus<double>(),
            [&](size_t i) {
                double d = x_new[i] - x_old[i];
                return d * d;
            }
        );
        diff = std::sqrt(diff);

        x_old.swap(x_new);
        if (diff < tol) break;
    }

    x = std::move(x_old);
}

