void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");
    x.assign(N, 0.0);

    // Build row-wise structure and extract diagonal
    std::vector<std::vector<COOElement>> rows(N);
    rows.reserve(N);
    std::vector<double> diag(N, 0.0);
    std::vector<bool> has_diag(N, false);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N)
            throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) {
            diag[e.row] = e.value;
            has_diag[e.row] = true;
        }
    }
    for (size_t i = 0; i < N; ++i) {
        if (!has_diag[i] || std::abs(diag[i]) <= std::numeric_limits<double>::epsilon())
            throw std::runtime_error("Jacobi requires nonzero diagonal entry for every row");
    }

    // Jacobi iteration
    const size_t max_iters = 10'000;
    const double tol = 1e-10;

    std::vector<double> x_old(N, 0.0), x_new(N, 0.0);
    std::vector<double> Ax(N, 0.0);

    // Precompute ||b||
    double bnrm2 = 0.0;
    for (double bi : b) bnrm2 += bi * bi;
    bnrm2 = std::sqrt(bnrm2);
    if (bnrm2 == 0.0) {
        std::fill(x.begin(), x.end(), 0.0);
        return;
    }

    // Start with zero initial guess
    std::fill(x_old.begin(), x_old.end(), 0.0);

    for (size_t k = 0; k < max_iters; ++k) {
        // Jacobi update per row in parallel
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double sum_off = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i)
                    sum_off += e.value * x_old[e.column];
            }
            x_new[i] = (b[i] - sum_off) / diag[i];
        });

        // Check residual
        spmv_coo_rows(rows, x_new, Ax);
        double rnrm2 = 0.0;
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double r = Ax[i] - b[i];
            // Use atomic-like accumulation with reduction via local temporary
            // For simplicity, accumulate per-thread and reduce serially after loop
        });

        // Compute residual norm serially for simplicity (cheap)
        rnrm2 = 0.0;
        for (size_t i = 0; i < N; ++i) {
            double r = Ax[i] - b[i];
            rnrm2 += r * r;
        }
        rnrm2 = std::sqrt(rnrm2);

        if (rnrm2 / bnrm2 < tol) {
            x = std::move(x_new);
            return;
        }

        x_old.swap(x_new);
    }

    // If not converged, return last iterate
    x = std::move(x_old);
}

