            double sigma = 0.0;
            for (auto const& [j, v] : rows[i]) sigma += v * x[j];
            x_new[i] = (b[i] - sigma) / diag[i];
        });

        // Check convergence: infinity norm of difference
        double inf_norm = hpx::transform_reduce(
            par,
            x.begin(), x.end(),
            x_new.begin(),
            0.0,
            [](double a, double b){ return std::max(a, b); },
            [](double xi, double xni){ return std::abs(xni - xi); }
        );

        x.swap(x_new);
        if (inf_norm < tol) break;
    }
}

