void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A)
    {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi cannot proceed");

    // Initial guess
    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    // Precompute ||b||
    double bnorm2 = hpx::transform_reduce(
        hpx::execution::par, b.begin(), b.end(), 0.0,
        std::plus<double>{},
        [](double bi){ return bi*bi; });
    double bnorm = std::sqrt(bnorm2);

    const double tol = 1e-12;
    const size_t max_iters = 10000;

    for (size_t iter = 0; iter < max_iters; ++iter)
    {
        // Jacobi update: x_new[i] = (b[i] - sum_{j!=i} A_ij x[j]) / A_ii
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double sum = 0.0;
            for (auto const& [j, aij] : rows[i])
            {
                if (j != i) sum += aij * x[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Residual norm ||A x_new - b||
        double r2 = hpx::transform_reduce(
            hpx::execution::par, size_t(0), N, 0.0,
            std::plus<double>{},
            [&](size_t i){
                double s = 0.0;
                for (auto const& [j, aij] : rows[i]) s += aij * x_new[j];
                double d = s - b[i];
                return d*d;
            });

        if (std::sqrt(r2) <= tol * (bnorm + 1.0))
        {
            x = std::move(x_new);
            return;
        }

        std::swap(x, x_new);
    }

    // If not converged, return last iterate
    x = std::move(x_new);
}

