                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    // Build CSR from COO
    const size_t nnz = Acoo.size();
    std::vector<COOElement> A = Acoo;
    std::sort(A.begin(), A.end(), [](auto const& a, auto const& b) {
        return a.row < b.row || (a.row == b.row && a.column < b.column);
    });

    std::vector<size_t> row_ptr(N + 1, 0);
    std::vector<size_t> col(nnz);
    std::vector<double> val(nnz);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of range");
        row_ptr[e.row + 1]++;
    }
    for (size_t i = 1; i <= N; ++i) row_ptr[i] += row_ptr[i - 1];
    // Fill CSR
    std::vector<size_t> offset = row_ptr;
    for (auto const& e : A) {
        size_t pos = offset[e.row]++;
        col[pos] = e.column;
        val[pos] = e.value;
    }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t i = 0; i < N; ++i) {
        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
            if (col[k] == i) {
                diag[i] = val[k];
                break;
            }
        }
        if (diag[i] == 0.0) throw std::runtime_error("Zero or missing diagonal at row " + std::to_string(i));
    }

    if (b.size() != N) throw std::runtime_error("Size mismatch");
    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    const size_t max_iters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
                size_t j = col[k];
                if (j != i) sum += val[k] * x[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Check convergence using infinity norm of update
        double max_delta = 0.0;
        std::mutex m;
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double d = std::abs(x_new[i] - x[i]);
            if (d > 0.0) {
