void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    std::vector<std::vector<COOElement>> rows(N);
    rows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
    }
    std::vector<double> diag(N, 0.0);
    for (size_t i = 0; i < N; ++i) {
        for (auto const& e : rows[i]) {
            if (e.column == i) diag[i] += e.value;
        }
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi not applicable");
    }

    std::vector<double> x_old(N, 0.0), x_new(N, 0.0);
    if (x.size() == N) x_old = x; // use provided initial guess if any

    constexpr size_t max_iter = 10000;
    constexpr double tol = 1e-10;

    auto begin = hpx::util::counting_iterator<size_t>(0);
    auto end = begin + N;

    for (size_t it = 0; it < max_iter; ++it) {
        hpx::for_each(hpx::execution::par, begin, end, [&](size_t i) {
            double sum = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) sum += e.value * x_old[e.column];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        double maxdiff = hpx::transform_reduce(
            hpx::execution::par, begin, end, 0.0,
            [](double a, double b) { return a > b ? a : b; },
            [&](size_t i) { return std::abs(x_new[i] - x_old[i]); }
        );

        if (maxdiff < tol) {
            x = x_new;
            return;
        }
        std::swap(x_old, x_new);
    }
    x = x_old; // best effort if not converged
}

