void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using std::size_t;

    // Build row-wise structure and extract diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    std::vector<char> has_diag(N, 0);

    for (auto const& e : A)
    {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) { diag[e.row] = e.value; has_diag[e.row] = 1; }
    }

    for (size_t i = 0; i < N; ++i)
        if (!has_diag[i] || diag[i] == 0.0) throw std::runtime_error("Matrix missing nonzero diagonal");

    if (b.size() != N) throw std::runtime_error("b has wrong size");
    if (x.size() != N) x.assign(N, 0.0);

    std::vector<double> x_new(N, 0.0);

    const double tol = 1e-10;
    const int max_iters = 10000;

    for (int iter = 0; iter < max_iters; ++iter)
    {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& [j, v] : rows[i])
            {
                if (j != i) sum += v * x[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Compute residual norm ||Ax - b||_2
        double res2 = 0.0;
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double ai = 0.0;
            for (auto const& [j, v] : rows[i]) ai += v * x_new[j];
            double ri = ai - b[i];
            // Atomic add to res2
            hpx::experimental::detail::with_lock_guard(
                hpx::detail::get_shared_mutex(res2),
                [&]() { res2 += ri * ri; });
        });

        // Swap x <- x_new
        x.swap(x_new);

        if (std::sqrt(res2) < tol) break;
    }
}

