void solveLinearSystem(std::vector<COOElement> const& Acoo, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Convert COO -> CSR (sum duplicates)
    std::vector<COOElement> A = Acoo;
    std::sort(A.begin(), A.end(), [](auto const& a, auto const& b){
        return a.row < b.row || (a.row == b.row && a.column < b.column);
    });

    std::vector<size_t> row_ptr(N+1, 0);
    std::vector<size_t> col;
    std::vector<double> val;

    size_t cur_row = 0;
    for (size_t k = 0; k < A.size(); ) {
        size_t i = A[k].row;
        while (cur_row <= i) { row_ptr[cur_row++] = col.size(); }
        // accumulate duplicates in row i
        size_t j = A[k].column;
        double sumv = 0.0;
        while (k < A.size() && A[k].row == i && A[k].column == j) {
            sumv += A[k].value;
            ++k;
        }
        if (std::abs(sumv) > 0.0) {
            col.push_back(j);
            val.push_back(sumv);
        }
    }
    while (cur_row <= N) { row_ptr[cur_row++] = col.size(); }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t i = 0; i < N; ++i) {
        for (size_t p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
            if (col[p] == i) { diag[i] = val[p]; break; }
        }
    }

    // Initialize x if empty
    if (x.size() != N) x.assign(N, 0.0);

    auto spmv = [&](std::vector<double> const& xv, std::vector<double>& y) {
        y.assign(N, 0.0);
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double s = 0.0;
            for (size_t p = row_ptr[i]; p < row_ptr[i+1]; ++p)
                s += val[p] * xv[col[p]];
            y[i] = s;
        });
    };

    const size_t max_iters = 10000;
    const double tol = 1e-10;

    // Jacobi iterations
    std::vector<double> x_new(N, 0.0), r(N, 0.0), Ax(N, 0.0);
    // If any diagonal is zero where equation has nonzero b or off-diagonals, method fails
    for (size_t i = 0; i < N; ++i) if (diag[i] == 0.0) { /* fallback to no-op */ return; }

    double b_norm = std::sqrt(std::inner_product(b.begin(), b.end(), b.begin(), 0.0));
    if (b_norm == 0.0) { std::fill(x.begin(), x.end(), 0.0); return; }

    for (size_t it = 0; it < max_iters; ++it) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double s = 0.0;
            for (size_t p = row_ptr[i]; p < row_ptr[i+1]; ++p) {
                size_t j = col[p];
                if (j != i) s += val[p] * x[j];
            }
            x_new[i] = (b[i] - s) / diag[i];
        });

        x.swap(x_new);

        // Check residual
        spmv(x, Ax);
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){ r[i] = Ax[i] - b[i]; });
        double r_norm = std::sqrt(hpx::transform_reduce(hpx::execution::par, r.begin(), r.end(), 0.0,
                                                        std::plus<>(), [](double v){ return v*v; }));
        if (r_norm / b_norm < tol) break;
    }
}

