   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (N == 0) { x.clear(); return; }

    // Sort A by row (then column)
    std::vector<COOElement> As = A;
    std::sort(As.begin(), As.end(), [](auto const& lhs, auto const& rhs){
        return lhs.row < rhs.row || (lhs.row == rhs.row && lhs.column < rhs.column);
    });

    // Build row pointers and diagonal
    std::vector<size_t> row_start(N + 1, 0);
    for (auto const& e : As) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        row_start[e.row + 1]++;
    }
    std::partial_sum(row_start.begin(), row_start.end(), row_start.begin());

    std::vector<double> diag(N, 0.0);
    for (auto const& e : As) {
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi cannot proceed");
    }

    // Initialize x
    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    // Jacobi iteration
    constexpr size_t max_iters = 1000;
    constexpr double tol = 1e-10;

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double sum = 0.0;
            for (size_t p = row_start[i]; p < row_start[i + 1]; ++p) {
                auto const& e = As[p];
                if (e.column != i) sum += e.value * x[e.column];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Check convergence: infinity norm of update
        double max_diff = hpx::transform_reduce(
            hpx::execution::par,
            x_new.begin(), x_new.end(), x.begin(),
            0.0,
            [](double a, double b){ return std::max(a, b); },
            [](double a, double b){ return std::abs(a - b); }
        );

        x.swap(x_new);
        if (max_diff < tol) break;
    }
}

