                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using hpx::execution::par;

    // Build row-wise structure and capture diagonal
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] = e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry; Jacobi cannot proceed");
    }

    // Initial guess
    if (x.size() != N) x.assign(N, 0.0);

    std::vector<double> x_new(N, 0.0);

    const size_t max_iters = 10000;
    const double tol = 1e-10;
    const double tol2 = tol * tol;

    for (size_t iter = 0; iter < max_iters; ++iter) {
        // Jacobi update in parallel
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) sum += e.value * x[e.column];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Check convergence: ||x_new - x||_2^2
        std::atomic<double> diff2_atomic{0.0};
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double d = x_new[i] - x[i];
            // atomic add
            double old = diff2_atomic.load(std::memory_order_relaxed), desired;
            do {
                desired = old + d * d;
            } while (!diff2_atomic.compare_exchange_weak(old, desired, std::memory_order_relaxed));
        });
        double diff2 = diff2_atomic.load(std::memory_order_relaxed);

        // Swap for next iteration
        x.swap(x_new);

        if (diff2 <= tol2) break;
    }
}

