void solveLinearSystem(std::vector<COOElement> const& Acoo, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    CSR A = coo_to_csr(Acoo, N);

    x.assign(N, 0.0);
    std::vector<double> r = b, r_hat = r, p(N, 0.0), v(N, 0.0), s, t;

    double rho_prev = 1.0, alpha = 1.0, omega = 1.0;
    double tol = 1e-10;
    size_t max_it = std::max<size_t>(1000, 10*N);

    for (size_t it = 0; it < max_it; ++it) {
        double rho = dot(r_hat, r);
        if (std::abs(rho) < 1e-30) break;
        double beta = (rho / rho_prev) * (alpha / omega);

        // p = r + beta * (p - omega * v)
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            p[i] = r[i] + beta * (p[i] - omega * v[i]);
        });

        spmv_csr(A, p, v);
        double denom = dot(r_hat, v);
        if (std::abs(denom) < 1e-30) break;
        alpha = rho / denom;

        // s = r - alpha * v
        s = r;
        axpy(-alpha, v, s);

        // check ||s||
        double s_norm2 = dot(s, s);
        if (std::sqrt(s_norm2) < tol) {
            // x += alpha * p
            axpy(alpha, p, x);
            break;
        }

        spmv_csr(A, s, t);
        double tt = dot(t, t);
        if (tt < 1e-30) break;
        double ts = dot(t, s);
        omega = ts / tt;

        // x += alpha * p + omega * s
        axpy(alpha, p, x);
        axpy(omega, s, x);

        // r = s - omega * t
        r = s;
        axpy(-omega, t, r);

        double rnorm = std::sqrt(dot(r, r));
        if (rnorm < tol) break;

        if (std::abs(omega) < 1e-30) break;
        rho_prev = rho;
    }
}

