void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<std::size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of bounds");
        if (e.row == e.column) diag[e.row] += e.value;
        else rows[e.row].emplace_back(e.column, e.value);
    }
    for (std::size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(i));

    // Jacobi iteration
    const std::size_t max_iter = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);

    for (std::size_t iter = 0; iter < max_iter; ++iter) {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sum = 0.0;
            for (auto const& [j, aij] : rows[i]) sum += aij * x_old[j];
            x_new[i] = (b[i] - sum) / diag[i];
        });

        double diff = hpx::transform_reduce(
            hpx::execution::par,
            x_new.begin(), x_new.end(),
            x_old.begin(),
            0.0,
            std::plus<double>(),
            [](double a, double b) {
                double d = a - b;
                return d * d;
            }
        );
        diff = std::sqrt(diff);

        x_old.swap(x_new);
        if (diff < tol) break;
    }

    x = std::move(x_old);
}

