void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    std::vector<std::size_t> row_ptr, col_idx;
    std::vector<double> vals, diag;
    coo_to_csr(A, N, row_ptr, col_idx, vals, diag);

    // Jacobi iteration
    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_new(N, 0.0), Ax(N, 0.0), r(N, 0.0);
    for (std::size_t k = 0; k < max_iters; ++k) {
        // x_new[i] = (b[i] - sum_{j!=i} A_ij * x[j]) / A_ii
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i){
            double s = 0.0;
            for (std::size_t p = row_ptr[i]; p < row_ptr[i + 1]; ++p) {
                auto j = col_idx[p];
                if (j != i) s += vals[p] * x[j];
