            x_new[i] = (b[i] - s) / diag[i];
        });

        // Check residual
        csr_spmv(row_ptr, col_idx, vals, x_new, Ax, N);
        double r2 = 0.0;
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i){
            double ri = Ax[i] - b[i];
            r[i] = ri;
        });
        r2 = hpx::reduce(hpx::execution::par, r.begin(), r.end(), 0.0,
                         [](double a, double c){ return a + c * c; });
        if (std::sqrt(r2) < tol) { x = x_new; return; }

        x.swap(x_new);
    }

    x = x_new; // best effort after max_iters
}

