/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::runtime_error("Size mismatch");
    // Build row-wise structure (CSR-like)
    std::vector<COOElement> As = A;
    std::stable_sort(As.begin(), As.end(),
        [](auto const& lhs, auto const& rhs){
            return lhs.row < rhs.row || (lhs.row == rhs.row && lhs.column < rhs.column);
        });

    std::vector<size_t> row_ptr(N+1, 0);
    for (auto const& e : As) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of range");
        row_ptr[e.row+1]++;
    }
    for (size_t i=1;i<=N;++i) row_ptr[i] += row_ptr[i-1];

    std::vector<size_t> cols(As.size());
    std::vector<double> vals(As.size());
    for (size_t i=0;i<As.size();++i){ cols[i]=As[i].column; vals[i]=As[i].value; }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t i=0;i<N;++i){
        for (size_t k=row_ptr[i]; k<row_ptr[i+1]; ++k){
            if (cols[k]==i){ diag[i]=vals[k]; break; }
        }
        if (diag[i]==0.0) throw std::runtime_error("Zero/missing diagonal");
    }

    // Jacobi iterations
    const size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old(N, 0.0);
    if (x.size()==N) x_old = x;
    std::vector<double> x_new(N, 0.0);
    std::vector<double> r(N, 0.0);

    for (size_t iter=0; iter<max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double sum = 0.0;
            for (size_t k=row_ptr[i]; k<row_ptr[i+1]; ++k){
                size_t j = cols[k];
                if (j!=i) sum += vals[k]*x_old[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double yi = 0.0;
            for (size_t k=row_ptr[i]; k<row_ptr[i+1]; ++k){
                yi += vals[k]*x_new[cols[k]];
            }
            r[i] = yi - b[i];
        });

        double norm2 = hpx::transform_reduce(hpx::execution::par, r.begin(), r.end(), 0.0,
                                             std::plus<double>(), [](double v){ return v*v; });
        if (std::sqrt(norm2) < tol) { x = x_new; return; }
        std::swap(x_old, x_new);
    }
    x = x_old; // return last iterate if not converged
}

