{
    if (b.size() != N) throw std::runtime_error("Size mismatch");
    // Build row-wise structure (CSR-like)
    std::vector<COOElement> As = A;
    std::stable_sort(As.begin(), As.end(),
        [](auto const& lhs, auto const& rhs){
            return lhs.row < rhs.row || (lhs.row == rhs.row && lhs.column < rhs.column);
        });

    std::vector<size_t> row_ptr(N+1, 0);
    for (auto const& e : As) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of range");
        row_ptr[e.row+1]++;
    }
    for (size_t i=1;i<=N;++i) row_ptr[i] += row_ptr[i-1];

    std::vector<size_t> cols(As.size());
    std::vector<double> vals(As.size());
    for (size_t i=0;i<As.size();++i){ cols[i]=As[i].column; vals[i]=As[i].value; }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t i=0;i<N;++i){
        for (size_t k=row_ptr[i]; k<row_ptr[i+1]; ++k){
            if (cols[k]==i){ diag[i]=vals[k]; break; }
        }
        if (diag[i]==0.0) throw std::runtime_error("Zero/missing diagonal");
    }

    // Jacobi iterations
    const size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old(N, 0.0);
