void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure and diagonal
    std::vector<double> diag(N, 0.0);
    std::vector<std::vector<std::pair<std::size_t,double>>> rows(N);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        if (e.row == e.column) diag[e.row] += e.value;
        else rows[e.row].emplace_back(e.column, e.value);
    }
    for (std::size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi cannot proceed");
    }

    // Jacobi iterations
    const std::size_t max_iters = 10000;
    const double tol = 1e-12;

    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);
    std::vector<double> diffs(N, 0.0);

    for (std::size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double s = 0.0;
            for (auto const& kv : rows[i]) {
                s += kv.second * x_old[kv.first];
            }
            x_new[i] = (b[i] - s) / diag[i];
        });

        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            diffs[i] = std::abs(x_new[i] - x_old[i]);
        });

        double max_diff = hpx::reduce(hpx::execution::par, diffs.begin(), diffs.end(), 0.0,
                                      [](double a, double c){ return a > c ? a : c; });

        x_old.swap(x_new);
        if (max_diff < tol) break;
    }

    x = std::move(x_old);
}

