        // prefix sum
        for (size_t i = 1; i <= N; ++i) csr.row_ptr[i] += csr.row_ptr[i - 1];

        // insert; if duplicates, accumulate
        std::vector<size_t> next = csr.row_ptr;
        for (size_t k = 0; k < A.size(); ++k) {
            size_t r = A[k].row;
            size_t idx = next[r]++;
            csr.col_ind[idx] = A[k].column;
            csr.val[idx] = A[k].value;
        }
        // combine duplicates in-place (rare; due to previous sort they are adjacent)
        for (size_t i = 0; i < N; ++i) {
