/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    using hpx::execution::par;

    if (b.size() != N) throw std::runtime_error("b size != N");

    // Empty matrix: x = b (no coupling)
    if (A.empty())
    {
        x = b;
        return;
    }

    // Build CSR from COO (sorted by row, then column)
    std::vector<COOElement> coo = A;
    hpx::ranges::sort(par, coo, [](auto const& lhs, auto const& rhs) {
        if (lhs.row != rhs.row) return lhs.row < rhs.row;
        return lhs.column < rhs.column;
    });

    std::vector<size_t> row_ptr(N + 1, 0);
    for (auto const& e : coo)
    {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of bounds");
        ++row_ptr[e.row + 1];
    }
    for (size_t i = 1; i <= N; ++i) row_ptr[i] += row_ptr[i - 1];

    std::vector<size_t> col_idx(coo.size());
    std::vector<double> vals(coo.size());
    {
        std::vector<size_t> offset = row_ptr; // copy
        for (auto const& e : coo)
        {
            size_t pos = offset[e.row]++;
            col_idx[pos] = e.column;
            vals[pos]    = e.value;
        }
    }

    // Ensure diagonal exists and is nonzero
    std::vector<double> diag(N, 0.0);
    hpx::for_loop(par, size_t(0), N, [&](size_t i) {
        double d = 0.0;
        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k)
            if (col_idx[k] == i) { d = vals[k]; break; }
        diag[i] = d;
    });
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero or missing diagonal at row " + std::to_string(i));

    // Jacobi iteration: x^{k+1} = D^{-1}(b - (L+U)x^{k})
    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    const size_t max_iters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < max_iters; ++iter)
    {
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            double di = diag[i];
            for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k)
            {
                size_t j = col_idx[k];
                double aij = vals[k];
                if (j != i) sum += aij * x[j];
            }
            x_new[i] = (b[i] - sum) / di;
        });

        // Convergence check: infinity norm of update
        double maxdiff = 0.0;
        for (size_t i = 0; i < N; ++i)
        {
            double d = std::abs(x_new[i] - x[i]);
            if (d > maxdiff) maxdiff = d;
        }
        x.swap(x_new);
        if (maxdiff < tol) break;
    }
}

