void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");
    x.assign(N, 0.0);

    // Build per-row structure and diagonal
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (std::size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal; Jacobi cannot proceed");

    // Jacobi iteration
    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_new(N, 0.0);
    std::vector<std::size_t> idx(N); std::iota(idx.begin(), idx.end(), 0);

    std::vector<double> Ax(N, 0.0);

    for (std::size_t it = 0; it < max_iters; ++it) {
        // x_new = Jacobi update
        hpx::for_each(hpx::execution::par, idx.begin(), idx.end(),
            [&](std::size_t i){
                double sum = 0.0;
                for (auto const& e : rows[i]) {
                    if (e.column != i) sum += e.value * x[e.column];
