void solveLinearSystem(std::vector<COOElement> const& Acoo,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build CSR from COO (sorted by row, then column)
    std::vector<COOElement> A = Acoo;
    std::sort(A.begin(), A.end(),
              [](auto const& a, auto const& c) {
                  return (a.row < c.row) || (a.row == c.row && a.column < c.column);
              });

    std::vector<std::size_t> rowptr(N + 1, 0);
    std::vector<std::size_t> col;
    std::vector<double> val;
    col.reserve(A.size());
    val.reserve(A.size());

    // Merge duplicates and build row counts
    std::size_t irow = 0;
    std::size_t idx = 0;
    while (idx < A.size() && A[idx].row < N) {
        while (irow < A[idx].row && irow < N) {
            rowptr[irow + 1] = col.size();
            ++irow;
        }
        std::size_t r = A[idx].row;
        std::size_t c = A[idx].column;
        double v = A[idx].value;
        ++idx;
        // merge same (r,c)
        while (idx < A.size() && A[idx].row == r && A[idx].column == c) {
            v += A[idx].value;
            ++idx;
        }
        col.push_back(c);
        val.push_back(v);
    }
    while (irow < N) {
        rowptr[irow + 1] = col.size();
        ++irow;
    }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (std::size_t r = 0; r < N; ++r) {
        for (std::size_t k = rowptr[r]; k < rowptr[r + 1]; ++k) {
            if (col[k] == r) {
                diag[r] = val[k];
                break;
            }
        }
        if (diag[r] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(r));
    }

    // Jacobi iteration
    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_new(N, 0.0);

    for (std::size_t it = 0; it < max_iters; ++it) {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t r) {
            double sum = b[r];
            for (std::size_t k = rowptr[r]; k < rowptr[r + 1]; ++k) {
                std::size_t j = col[k];
                if (j != r) sum -= val[k] * x[j];
            }
            x_new[r] = sum / diag[r];
        });

        // Check convergence: ||x_new - x|| / (1 + ||x_new||) < tol
        double num = hpx::transform_reduce(
            hpx::execution::par,
            x_new.begin(), x_new.end(), x.begin(),
            0.0,
            std::plus<>(),
            [](double a, double b) {
                double d = a - b;
                return d * d;
            });

        double den = hpx::transform_reduce(
            hpx::execution::par,
            x_new.begin(), x_new.end(),
            0.0, std::plus<>(),
            [](double a) { return a * a; });

        double rel = std::sqrt(num) / (1.0 + std::sqrt(den));
        x.swap(x_new);
        if (rel < tol) break;
    }
}

