void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");

    // Build CSR from COO (sorted by row, then column)
    std::vector<COOElement> coo = A;
    std::sort(coo.begin(), coo.end(),
              [](auto const& a, auto const& c) {
                  return (a.row < c.row) || (a.row == c.row && a.column < c.column);
              });

    std::vector<size_t> row_ptr(N + 1, 0);
    std::vector<size_t> col_idx;
    std::vector<double> vals;
    col_idx.reserve(coo.size());
    vals.reserve(coo.size());

    for (auto const& e : coo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        row_ptr[e.row + 1]++;
    }
    for (size_t i = 1; i <= N; ++i) row_ptr[i] += row_ptr[i - 1];
    {
        std::vector<size_t> next = row_ptr;
        col_idx.resize(coo.size());
        vals.resize(coo.size());
        for (auto const& e : coo) {
            size_t p = next[e.row]++;
            col_idx[p] = e.column;
            vals[p] = e.value;
        }
    }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t i = 0; i < N; ++i) {
        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
            if (col_idx[k] == i) {
                diag[i] = vals[k];
                break;
            }
        }
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry; Jacobi not applicable");
    }

    // Jacobi iterations
    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);
    std::vector<size_t> idx(N);
    std::iota(idx.begin(), idx.end(), 0);

    const double tol = 1e-10;
    const size_t max_iter = 10000;

    for (size_t iter = 0; iter < max_iter; ++iter) {
        hpx::ranges::for_each(hpx::execution::par, idx, [&](size_t i) {
            double sum = 0.0;
            for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
                size_t j = col_idx[k];
                double aij = vals[k];
                if (j != i) sum += aij * x[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        double maxdiff = hpx::ranges::transform_reduce(
            hpx::execution::par, idx, 0.0, hpx::maximum<double>{},
            [&](size_t i) { return std::fabs(x_new[i] - x[i]); });

        std::swap(x, x_new);
        if (maxdiff < tol) break;
    }
}

