void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using hpx::execution::par;

    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    x.assign(N, 0.0);

    // Build row-wise structure and diagonal
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] = e.value;
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi cannot proceed");

    // Jacobi iterations
    std::vector<double> x_old(N, 0.0), x_new(N, 0.0);
    const size_t max_iters = 10000;
    const double tol = 1e-10;

    auto first = hpx::make_counting_iterator<size_t>(0);
    auto last  = hpx::make_counting_iterator<size_t>(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        x_old.swap(x_new);

        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double sigma = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) sigma += e.value * x_old[e.column];
            }
            x_new[i] = (b[i] - sigma) / diag[i];
        });

        double diff2 = hpx::transform_reduce(
            par, first, last, 0.0, std::plus<>(),
            [&](size_t i) {
                double d = x_new[i] - x_old[i];
                return d * d;
            });

        if (diff2 < tol * tol) break;
    }

    x = std::move(x_new);
}

