{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    x.assign(N, 0.0);

    // Build CSR from COO (sorted, coalesced)
    std::vector<COOElement> A = Acoo;
    hpx::sort(hpx::execution::par, A.begin(), A.end(),
              [](auto const& a, auto const& b) {
                  return a.row < b.row || (a.row == b.row && a.column < b.column);
              });

    std::vector<size_t> row_ptr(N + 1, 0);
    std::vector<size_t> col_idx;
    std::vector<double>  vals;

    size_t i = 0;
    while (i < A.size()) {
        size_t r = A[i].row, c = A[i].column;
        double v = A[i].value;
        ++i;
        while (i < A.size() && A[i].row == r && A[i].column == c) {
            v += A[i].value;
            ++i;
        }
        if (r >= N || c >= N) throw std::out_of_range("COO index out of range");
        ++row_ptr[r + 1];
        col_idx.push_back(c);
        vals.push_back(v);
    }
    for (size_t r = 0; r < N; ++r) row_ptr[r + 1] += row_ptr[r];

    // Diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t r = 0; r < N; ++r) {
        for (size_t k = row_ptr[r]; k < row_ptr[r + 1]; ++k) {
            if (col_idx[k] == r) diag[r] = vals[k];
        }
        if (diag[r] == 0.0) throw std::runtime_error("Zero diagonal; Jacobi fails");
    }

    // Jacobi iterations
    const size_t max_iters = 10000;
    const double tol = 1e-10;
    std::vector<double> x_new(N, 0.0);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t r) {
            double sum = 0.0;
            for (size_t k = row_ptr[r]; k < row_ptr[r + 1]; ++k) {
                size_t c = col_idx[k];
                if (c != r) sum += vals[k] * x[c];
            }
            x_new[r] = (b[r] - sum) / diag[r];
        });

        // Check residual ||Ax - b||
        double res2 = hpx::transform_reduce(
            hpx::execution::par, size_t(0), N, 0.0,
            std::plus<>(),
