   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    std::vector<double> diag(N, 0.0);
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("A index out of range");
        if (e.row == e.column) diag[e.row] += e.value;
        else rows[e.row].emplace_back(e.column, e.value);
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected");

    x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    const double tol = 1e-10;
    const size_t max_iters = 10000;

    for (size_t iter = 0; iter < max_iters; ++iter) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double s = 0.0;
            for (auto const& kv : rows[i]) s += kv.second * x[kv.first];
            x_new[i] = (b[i] - s) / diag[i];
        });

        auto first = hpx::counting_iterator<size_t>(0);
        auto last  = hpx::counting_iterator<size_t>(N);
        double err = hpx::transform_reduce(
            hpx::execution::par, first, last, 0.0,
            [](double a, double b){ return a > b ? a : b; },
            [&](size_t i){ return std::abs(x_new[i] - x[i]); }
        );

        x.swap(x_new);
        if (err < tol) break;
    }
}

