void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");
    x.assign(N, 0.0);

    // Build row-wise storage and diagonal
    std::vector<std::vector<std::pair<std::size_t, double>>> rows(N);
    rows.reserve(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] = e.value;
    }

    // Check diagonals
    for (std::size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(i));
    }

    // Optional: sort columns within each row for better cache behavior
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        std::sort(rows[i].begin(), rows[i].end(),
                  [](auto const& a, auto const& b) { return a.first < b.first; });
    });

    // Jacobi iteration
    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_new(N, 0.0);

    for (std::size_t iter = 0; iter < max_iters; ++iter) {
        // x_new[i] = (b[i] - sum_{j!=i} a_ij * x[j]) / diag[i]
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sum = 0.0;
            for (auto const& [j, aij] : rows[i]) {
                if (j != i) sum += aij * x[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Convergence check: infinity norm of difference
        double max_diff = hpx::transform_reduce(
            hpx::execution::par,
            x.begin(), x.end(),
            x_new.begin(),
            0.0,
            [](double a, double b) { return std::max(a, b); },
            [](double xi, double xni) { return std::abs(xni - xi); });

        x.swap(x_new);
        if (max_diff < tol) break;
    }
}

