// Build CSR from COO
static void coo_to_csr(std::vector<COOElement> const& A,
                       size_t N,
                       std::vector<size_t>& row_ptr,
                       std::vector<size_t>& col_idx,
                       std::vector<double>& values)
{
    std::vector<COOElement> sorted = A;
    std::stable_sort(sorted.begin(), sorted.end(),
                     [](auto const& a, auto const& b){
                         return a.row < b.row || (a.row == b.row && a.column < b.column);
                     });

    row_ptr.assign(N + 1, 0);
    col_idx.resize(sorted.size());
    values.resize(sorted.size());

    for (auto const& e : sorted) ++row_ptr[e.row + 1];
    std::partial_sum(row_ptr.begin(), row_ptr.end(), row_ptr.begin());

    // If duplicates exist, merge them
    std::vector<size_t> next = row_ptr;
    for (auto const& e : sorted) {
        size_t pos = next[e.row]++;
        col_idx[pos] = e.column;
        values[pos]  = e.value;
    }
    // Merge duplicates per row (optional but robust)
    std::vector<size_t> new_col;
    std::vector<double> new_val;
    std::vector<size_t> new_row(N + 1, 0);
    new_col.reserve(col_idx.size());
    new_val.reserve(values.size());

    for (size_t r = 0; r < N; ++r) {
        size_t begin = row_ptr[r], end = row_ptr[r + 1];
        size_t i = begin;
        while (i < end) {
            size_t c = col_idx[i];
            double v = values[i];
            ++i;
            while (i < end && col_idx[i] == c) { v += values[i]; ++i; }
            if (std::abs(v) > 0) {
                new_col.push_back(c);
                new_val.push_back(v);
                ++new_row[r + 1];
            }
        }
    }
    std::partial_sum(new_row.begin(), new_row.end(), new_row.begin());
    row_ptr.swap(new_row);
    col_idx.swap(new_col);
    values.swap(new_val);
}

// y = A x (CSR)
static void spmv_csr(std::vector<size_t> const& row_ptr,
                     std::vector<size_t> const& col_idx,
                     std::vector<double> const& values,
                     std::vector<double> const& x,
                     std::vector<double>& y)
{
