void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using hpx::execution::par;

    if (b.size() != N) throw std::invalid_argument("b size != N");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        if (e.row == e.column) diag[e.row] += e.value;
        rows[e.row].emplace_back(e.column, e.value);
    }

    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi requires nonzero diagonal");
    }

    // Jacobi iteration
    const size_t max_iter = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);
    std::vector<double> residual(N, 0.0);

    auto spmv_row_sum = [&](size_t i, std::vector<double> const& xv) {
        double s = 0.0;
        for (auto const& kv : rows[i]) s += kv.second * xv[kv.first];
        return s;
    };

    auto compute_residual = [&] {
        // r = b - A*x_old
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            residual[i] = b[i] - spmv_row_sum(i, x_old);
        });
        // ||r||_2
        double norm2 = hpx::transform_reduce(par, residual.begin(), residual.end(), 0.0,
                                             std::plus<double>(),
                                             [](double v){ return v*v; });
        return std::sqrt(norm2);
    };

    double rnorm = compute_residual();
    if (rnorm <= tol) { x = x_old; return; }

    for (size_t it = 0; it < max_iter; ++it) {
        // x_new[i] = (b[i] - sum_{j!=i} a_ij * x_old[j]) / a_ii
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double sigma = 0.0;
            for (auto const& kv : rows[i]) {
                if (kv.first != i) sigma += kv.second * x_old[kv.first];
            }
            x_new[i] = (b[i] - sigma) / diag[i];
        });

        x_old.swap(x_new);

        rnorm = compute_residual();
        if (rnorm <= tol) break;
    }

    x = x_old;
}

