void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (std::abs(diag[i]) < 1e-30)
            throw std::runtime_error("Zero (or missing) diagonal entry at row " + std::to_string(i));
    }

    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> new_x(N, 0.0);

    const double tol = 1e-12;
    const std::size_t max_iters = 10000;

    for (std::size_t iter = 0; iter < max_iters; ++iter) {
        // Jacobi update in parallel per row
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sum = 0.0;
            for (auto const& [j, aij] : rows[i]) {
                if (j != i) sum += aij * x[j];
            }
            new_x[i] = (b[i] - sum) / diag[i];
        });

        // Check convergence using infinity norm of update
        double maxdiff = 0.0;
        for (size_t i = 0; i < N; ++i)
            maxdiff = std::max(maxdiff, std::abs(new_x[i] - x[i]));

        x.swap(new_x);
        if (maxdiff < tol) break;
    }
}

