void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure and diagonals
    std::vector<std::vector<std::pair<size_t,double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered; Jacobi not applicable");
    }

    std::vector<double> x_new(N, 0.0);
    constexpr size_t max_iters = 10000;
    constexpr double tol = 1e-10;

    auto begin = hpx::make_counting_iterator<size_t>(0);
    auto end   = hpx::make_counting_iterator<size_t>(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        // Jacobi update in parallel
        hpx::for_each(hpx::execution::par, begin, end, [&](size_t i) {
            double sum = 0.0;
            for (auto const& [j, aij] : rows[i]) {
                if (j != i) sum += aij * x[j];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Convergence check (||x_new - x||_2)
        double diff_sq = hpx::transform_reduce(
            hpx::execution::par,
            begin, end,
            0.0,
            std::plus<double>{},
            [&](size_t i) {
                double d = x_new[i] - x[i];
                return d * d;
            }
        );

        x.swap(x_new);
        if (std::sqrt(diff_sq) < tol) break;
    }
}

