void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build CSR from COO
    std::vector<COOElement> coo = A;
    std::stable_sort(coo.begin(), coo.end(),
        [](COOElement const& a, COOElement const& c){
            return (a.row < c.row) || (a.row == c.row && a.column < c.column);
        });

    std::vector<size_t> row_ptr(N + 1, 0);
    for (auto const& e : coo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        row_ptr[e.row + 1]++;
    }
    std::partial_sum(row_ptr.begin() + 1, row_ptr.end(), row_ptr.begin() + 1);

    std::vector<size_t> col_idx(coo.size());
    std::vector<double> vals(coo.size());
    {
        auto curr = row_ptr; // copy
        for (auto const& e : coo) {
            size_t p = curr[e.row]++;
            col_idx[p] = e.column;
            vals[p]    = e.value;
        }
    }

    // Jacobi iteration
    const size_t max_iter = 10000;
    const double tol = 1e-10;

    std::vector<double> x_new(N, 0.0);

    auto residual_norm = [&](std::vector<double> const& xv) {
        std::vector<double> y(N, 0.0);
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i){
            double s = 0.0;
            for (size_t k = row_ptr[i]; k < row_ptr[i+1]; ++k) {
                s += vals[k] * xv[col_idx[k]];
            }
