        std::vector<double> partials(N, 0.0);
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double ai_x = 0.0;
            for (auto const& [j, v] : rows[i]) {
                ai_x += v * x_new[j];
            }
            double r = ai_x - b[i];
            partials[i] = r * r;
        });
        double norm2 = std::accumulate(partials.begin(), partials.end(), 0.0);
        if (std::sqrt(norm2) < tol) {
            x = std::move(x_new);
            return;
        }

        x.swap(x_new);
