*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    if (b.size() != N) throw std::runtime_error("b size mismatch");
    // Group elements by row and extract diagonal
    std::vector<std::vector<COOElement>> rows(N);
    rows.reserve(N);
    std::vector<double> diag(N, std::numeric_limits<double>::quiet_NaN());
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] = e.value;
    }
    for (size_t i = 0; i < N; ++i) {
        if (!std::isfinite(diag[i]) || diag[i] == 0.0)
            throw std::runtime_error("Missing or zero diagonal entry at row " + std::to_string(i));
    }

    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_old = x, x_new(N, 0.0);

    // Precompute ||b||
    double nb2 = 0.0;
    for (double v : b) nb2 += v * v;
    double nb = std::sqrt(nb2);

    const double tol = 1e-10;
    const size_t max_iters = std::max<size_t>(10000, 10 * N);

    for (size_t it = 0; it < max_iters; ++it) {
        // Jacobi update: x_new[i] = (b[i] - sum_{j!=i} A_ij * x_old[j]) / A_ii
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) sum += e.value * x_old[e.column];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Compute residual r = b - A*x_new and its norm
        double res2 = hpx::transform_reduce(
            hpx::execution::par,
            size_t(0), N, 0.0,
            std::plus<double>{},
            [&](size_t i) {
                double Ax_i = 0.0;
                for (auto const& e : rows[i]) Ax_i += e.value * x_new[e.column];
                double ri = b[i] - Ax_i;
                return ri * ri;
            }
        );
        double res = std::sqrt(res2);
        if (res <= tol * (nb + 1.0)) {
            x = std::move(x_new);
            return;
        }
        x_old.swap(x_new);
    }

    // If not converged, return last iterate
    x = std::move(x_old);
}

