void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");

    // Build per-row sparse structure (excluding diagonal) and diagonal
    std::vector<double> diag(N, 0.0);
    std::vector<std::vector<std::pair<std::size_t, double>>> rows(N);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        if (e.row == e.column) {
            diag[e.row] += e.value; // accumulate if multiple diagonal entries
        } else {
            rows[e.row].emplace_back(e.column, e.value);
        }
    }
    for (std::size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi fails");
    }

    // Initial guess
    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);
    std::vector<double> diffs(N, 0.0);

    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    for (std::size_t it = 0; it < max_iters; ++it) {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N,
            [&](std::size_t i) {
                double sigma = 0.0;
                for (auto const& [j, val] : rows[i]) {
                    sigma += val * x[j];
                }
                x_new[i] = (b[i] - sigma) / diag[i];
            });

        hpx::for_loop(hpx::execution::par, std::size_t(0), N,
            [&](std::size_t i) {
                diffs[i] = std::abs(x_new[i] - x[i]);
            });

        double max_diff = *std::max_element(diffs.begin(), diffs.end());
        x.swap(x_new);
        if (max_diff < tol) break;
    }
}

