void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using hpx::execution::par;

    // Build row-wise structure
    std::vector<std::vector<COOElement>> rows(N);
    rows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
    }

    // Diagonal
    std::vector<double> diag(N, 0.0);
    hpx::for_loop(par, size_t(0), N, [&](size_t i) {
        double d = 0.0;
        for (auto const& e : rows[i]) {
            if (e.column == i) d += e.value; // accumulate if multiple diagonal entries
        }
        diag[i] = d;
    });

    // Check diagonal
    for (size_t i = 0; i < N; ++i) {
        if (diag[i] == 0.0) throw std::invalid_argument("Zero diagonal encountered; Jacobi cannot proceed");
    }

    // Initialize x if needed
    if (x.size() != N) x.assign(N, 0.0);

    // Jacobi iteration
    const size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old(N), x_new(N), diffs(N);

    for (size_t iter = 0; iter < max_iters; ++iter) {
        x_old = x;

        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) sum += e.value * x_old[e.column];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Convergence check: infinity norm of update
        hpx::for_loop(par, size_t(0), N, [&](size_t i) {
            diffs[i] = std::abs(x_new[i] - x_old[i]);
        });
        double delta = hpx::reduce(par, diffs.begin(), diffs.end(), 0.0,
                                   [](double a, double b) { return a > b ? a : b; });

        x.swap(x_new);

        if (delta < tol) break;
    }
}

