void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    // Build row-wise structure
    std::vector<std::vector<std::pair<std::size_t, double>>> rows(N);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].emplace_back(e.column, e.value);
    }
    // Diagonal
    std::vector<double> diag(N, 0.0);
    for (std::size_t i = 0; i < N; ++i) {
        for (auto const& kv : rows[i]) {
            if (kv.first == i) { diag[i] = kv.second; break; }
        }
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(i));
    }

    // Initial guess
    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_old = x, x_new(N, 0.0);

    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    // Precompute ||b||
    double nb2 = 0.0;
    for (double bi : b) nb2 += bi * bi;
    double nb = std::sqrt(nb2);

    for (std::size_t iter = 0; iter < max_iters; ++iter) {
        // Jacobi update in parallel
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sum = 0.0;
            for (auto const& kv : rows[i]) {
                if (kv.first != i) sum += kv.second * x_old[kv.first];
            }
            x_new[i] = (b[i] - sum) / diag[i];
        });

        // Check residual ||b - A x_new||
        double r2 = 0.0;
        for (std::size_t i = 0; i < N; ++i) {
            double ai = 0.0;
            for (auto const& kv : rows[i]) ai += kv.second * x_new[kv.first];
            double ri = b[i] - ai;
            r2 += ri * ri;
        }
        if (std::sqrt(r2) <= tol * (nb > 0.0 ? nb : 1.0)) {
            x = x_new;
            return;
        }

        x_old.swap(x_new);
    }

    // If not converged, return last iterate
    x = x_old;
}

