generated_output:
void solveLinearSystem(std::vector<COOElement> const& Acoo, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Build CSR from COO
    std::vector<size_t> row_ptr(N + 1, 0);
    std::vector<size_t> col_idx;
    std::vector<double>  val;
    col_idx.reserve(Acoo.size());
    val.reserve(Acoo.size());

    // Count entries per row
    for (auto const& e : Acoo) row_ptr[e.row + 1]++;
    // Prefix sum
    for (size_t i = 1; i <= N; ++i) row_ptr[i] += row_ptr[i - 1];
    // Temporary copy for insertion positions
    std::vector<size_t> insert_pos = row_ptr;

    col_idx.resize(Acoo.size());
    val.resize(Acoo.size());
    for (auto const& e : Acoo) {
        size_t pos = insert_pos[e.row]++;
        col_idx[pos] = e.column;
        val[pos]     = e.value;
    }
    // Optionally sort columns within rows for better locality
    for (size_t i = 0; i < N; ++i) {
        size_t start = row_ptr[i], end = row_ptr[i + 1];
        auto first = start, last = end;
        std::vector<size_t> order(last - first);
        std::iota(order.begin(), order.end(), 0);
        std::sort(order.begin(), order.end(), [&](size_t a, size_t b) {
            return col_idx[first + a] < col_idx[first + b];
        });
        std::vector<size_t> ctmp(last - first);
        std::vector<double> vtmp(last - first);
        for (size_t k = 0; k < order.size(); ++k) {
            ctmp[k] = col_idx[first + order[k]];
            vtmp[k] = val[first + order[k]];
        }
        for (size_t k = 0; k < order.size(); ++k) {
            col_idx[first + k] = ctmp[k];
            val[first + k]     = vtmp[k];
        }
    }

    auto spmv = [&](std::vector<double> const& xin, std::vector<double>& yout) {
