void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build per-row structure and extract diagonal
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        if (e.row == e.column) diag[e.row] += e.value;
        else rows[e.row].emplace_back(e.column, e.value);
    }
    for (size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal encountered");

    std::vector<double> x_new(N, 0.0);

    constexpr std::size_t max_iter = 10000;
    constexpr double tol = 1e-10;

    for (std::size_t iter = 0; iter < max_iter; ++iter) {
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sum = 0.0;
            for (auto const& [j, v] : rows[i]) sum += v * x[j];
            x_new[i] = (b[i] - sum) / diag[i];
        });

        double max_diff = hpx::transform_reduce(
            hpx::execution::par,
            x_new.begin(), x_new.end(),
            x.begin(),
            0.0,
            [](double a, double b) { return a > b ? a : b; },
            [](double a_new, double a_old) { return std::abs(a_new - a_old); }
        );

        x.swap(x_new);
        if (max_diff < tol) break;
    }
}

