void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N)
{
    using hpx::execution::par;

    // Build row- and column-adjacency from COO
    std::vector<std::vector<std::pair<size_t,double>>> rows(N), cols(N);
    rows.reserve(N); cols.reserve(N);
    for (auto const& e : A) {
        rows[e.row].emplace_back(e.column, e.value);
        cols[e.column].emplace_back(e.row, e.value);
    }

    auto spmv_rows = [&](std::vector<double> const& v, std::vector<double>& y) {
        y.assign(N, 0.0);
        hpx::for_loop(par, size_t(0), N, [&](size_t i){
            double s = 0.0;
            for (auto const& [j, aij] : rows[i]) s += aij * v[j];
            y[i] = s;
        });
    };

    auto spmv_cols_T = [&](std::vector<double> const& v, std::vector<double>& y) {
        // y = A^T v using column adjacency: y[j] = sum_i a_ij * v[i]
        y.assign(N, 0.0);
        hpx::for_loop(par, size_t(0), N, [&](size_t j){
            double s = 0.0;
            for (auto const& [i, aij] : cols[j]) s += aij * v[i];
            y[j] = s;
        });
    };

    auto apply_M = [&](std::vector<double> const& v, std::vector<double>& y) {
        // y = (A^T A) v
        static thread_local std::vector<double> tmp;
        tmp.resize(N);
        spmv_rows(v, tmp);       // tmp = A v
        spmv_cols_T(tmp, y);     // y = A^T tmp
    };

    // b' = A^T b
    std::vector<double> bprime(N, 0.0);
    spmv_cols_T(b, bprime);

    // Conjugate Gradient on M = A^T A (SPD)
    x.assign(N, 0.0);
    std::vector<double> r = bprime, p = r, Ap(N, 0.0);

    auto dot = [&](std::vector<double> const& u, std::vector<double> const& v){
        return hpx::transform_reduce(par, u.begin(), u.end(), v.begin(), 0.0);
    };

    const double tol = 1e-10;
    const size_t maxit = std::max<size_t>(1000, 10*N);
    double rsold = dot(r, r);

    for (size_t it = 0; it < maxit && rsold > tol*tol; ++it) {
        apply_M(p, Ap);
        double alpha = rsold / std::max(1e-30, dot(p, Ap));

        hpx::for_loop(par, size_t(0), N, [&](size_t i){
            x[i] += alpha * p[i];
            r[i] -= alpha * Ap[i];
        });

        double rsnew = dot(r, r);
        if (rsnew <= tol*tol) break;

        double beta = rsnew / rsold;
        hpx::for_loop(par, size_t(0), N, [&](size_t i){
            p[i] = r[i] + beta * p[i];
        });
        rsold = rsnew;
    }
}

