void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size mismatch");
    if (x.size() != N) x.assign(N, 0.0);

    // Build row-wise structure and diagonals
    std::vector<std::vector<COOElement>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        rows[e.row].push_back(e);
        if (e.row == e.column) diag[e.row] += e.value;
    }
    for (std::size_t i = 0; i < N; ++i) {
        if (rows[i].empty()) throw std::runtime_error("Row with no entries");
        if (std::abs(diag[i]) == 0.0) throw std::runtime_error("Zero diagonal detected");
    }

    const std::size_t max_iter = 1000;
    const double tol = 1e-10;

    std::vector<double> x_new(N, 0.0);
    std::vector<double> residuals(N, 0.0);

    for (std::size_t it = 0; it < max_iter; ++it) {
        // Jacobi update
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double s = 0.0;
            for (auto const& e : rows[i]) {
                if (e.column != i) s += e.value * x[e.column];
            }
            x_new[i] = (b[i] - s) / diag[i];
        });

        // Compute residual r = A x_new - b and its norm
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double ai = 0.0;
            for (auto const& e : rows[i]) ai += e.value * x_new[e.column];
            residuals[i] = ai - b[i];
        });

        double norm2 = hpx::reduce(hpx::execution::par, residuals.begin(), residuals.end(), 0.0,
                                   [](double a, double r) { return a + r * r; });
        if (std::sqrt(norm2) < tol) {
            x = std::move(x_new);
            return;
        }

        // Prepare next iteration
        hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            x[i] = x_new[i];
        });
    }

    x = std::move(x_new);
}

