   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {

generated_output:
void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double>& x,
                       std::size_t N)
{
    if (b.size() != N) throw std::invalid_argument("b size != N");

    // Build row-wise structure and diagonal
    std::vector<std::vector<std::pair<std::size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        if (e.row == e.column)
            diag[e.row] += e.value;
        else
            rows[e.row].emplace_back(e.column, e.value);
    }
    for (std::size_t i = 0; i < N; ++i)
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal entry at row " + std::to_string(i));

    if (x.size() != N) x.assign(N, 0.0);

    // Jacobi iteration
    const std::size_t max_iters = 10000;
    const double tol = 1e-10;

    std::vector<double> x_old = x;
    std::vector<double> x_new(N, 0.0);

    for (std::size_t it = 0; it < max_iters; ++it) {
        // Compute new iterate in parallel
        hpx::for_each(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
            double sigma = 0.0;
            for (auto const& [j, v] : rows[i]) {
                sigma += v * x_old[j];
            }
            x_new[i] = (b[i] - sigma) / diag[i];
        });

        // Check convergence using max-norm in parallel
        double maxdiff = hpx::transform_reduce(
            hpx::execution::par,
            std::size_t(0), N,
            0.0,
            [](double a, double b) { return std::max(a, b); },
            [&](std::size_t i) { return std::abs(x_new[i] - x_old[i]); }
        );

        x_old.swap(x_new);
        if (maxdiff < tol) break;
    }

    x = std::move(x_old);
}

