generated_output:
{
    // Build CSR-like structure from COO
    std::vector<size_t> row_ptr(N + 1, 0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::runtime_error("Index out of range");
        row_ptr[e.row + 1]++;
    }
    for (size_t i = 1; i <= N; ++i) row_ptr[i] += row_ptr[i - 1];

    std::vector<size_t> col_ind(A.size());
    std::vector<double> values(A.size());
    std::vector<size_t> next(N, 0);
    for (size_t i = 0; i < N; ++i) next[i] = row_ptr[i];
    for (auto const& e : A) {
        size_t pos = next[e.row]++;
        col_ind[pos] = e.column;
        values[pos]  = e.value;
    }

    // Extract diagonal
    std::vector<double> diag(N, 0.0);
    for (size_t i = 0; i < N; ++i) {
        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
            if (col_ind[k] == i) { diag[i] += values[k]; }
        }
        if (diag[i] == 0.0) throw std::runtime_error("Zero diagonal detected; Jacobi cannot proceed");
    }

    // Jacobi iteration: x^{k+1}_i = (b_i - sum_{j!=i} A_ij x^k_j) / A_ii
    if (x.size() != N) x.assign(N, 0.0);
    std::vector<double> x_new(N, 0.0);

    const size_t max_iter = 10000;
    const double tol = 1e-10;

    for (size_t it = 0; it < max_iter; ++it) {
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            double sum = 0.0;
            double di = diag[i];
            for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
                size_t j = col_ind[k];
                double aij = values[k];
                if (j != i) sum += aij * x[j];
            }
            x_new[i] = (b[i] - sum) / di;
        });

        // Compute infinity-norm difference
        std::vector<double> diffs(N);
        hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
            diffs[i] = std::abs(x_new[i] - x[i]);
        });
        double diff = *std::max_element(diffs.begin(), diffs.end());
        x.swap(x_new);
        if (diff < tol) break;
    }
}

