void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    Y.assign(M * N, 0.0);

    // Build row-wise views for A (by row i) and X (by row k)
    std::vector<std::vector<std::pair<size_t, double>>> A_rows(M);
    A_rows.reserve(M);
    for (auto const& e : A) {
        if (e.row < M && e.column < K)
            A_rows[e.row].emplace_back(e.column, e.value); // (k, a_ik)
    }

    std::vector<std::vector<std::pair<size_t, double>>> X_rows(K);
    X_rows.reserve(K);
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_rows[e.row].emplace_back(e.column, e.value); // (n, x_kn)
    }

    // Parallelize over rows of Y (no locks needed)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        double* yrow = Y.data() + i * N;
        auto const& arow = A_rows[i];
        for (auto const& ak : arow) {
            size_t k = ak.first;
            double a_ik = ak.second;
            auto const& xrow = X_rows[k];
            for (auto const& xn : xrow) {
                yrow[xn.first] += a_ik * xn.second;
            }
        }
    });
