void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare Y
    Y.resize(M * N);
    hpx::for_each(hpx::execution::par, Y.begin(), Y.end(), [](double& v){ v = 0.0; });

    // Build X grouped by row (row = K index)
    std::vector<size_t> row_ptr(K + 1, 0);
    for (auto const& e : X) {
        if (e.row < K) ++row_ptr[e.row + 1];
    }
    for (size_t k = 1; k <= K; ++k) row_ptr[k] += row_ptr[k - 1];

    std::vector<COOElement> X_by_row(X.size());
    std::vector<size_t> insert_pos = row_ptr; // working copy
    for (auto const& e : X) {
        if (e.row < K) {
            X_by_row[insert_pos[e.row]++] = e;
        }
    }

    // Row locks to guard updates to Y
