    // Parallel over A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            size_t i = a.row;
            size_t k = a.column;
            if (i >= M || k >= K) return;

            size_t b = row_ptr[k];
            size_t e = row_ptr[k + 1];
            if (b == e) return;

