            std::unique_lock<hpx::spinlock> lk(row_locks[i]);
            double* yrow = Y.data() + i * N;
            for (size_t t = b; t < e; ++t) {
                auto const& x = X_by_row[t];
                size_t j = x.column;
                if (j < N)
                    yrow[j] += a.value * x.value;
            }
        });
}

