void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Build row-wise index of X (K rows)
    std::vector<std::vector<std::pair<size_t, double>>> X_by_row(K);
    X_by_row.shrink_to_fit();
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_by_row[e.row].emplace_back(e.column, e.value);
    }

    // One lock per output row to avoid races
    std::vector<hpx::lcos::local::spinlock> row_locks(M);

    // Parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            size_t i = a.row;
            size_t k = a.column;
            double av = a.value;
            if (i >= M || k >= K) return;

            auto const& xr = X_by_row[k];
            if (xr.empty()) return;

            auto& lk = row_locks[i];
            std::lock_guard<hpx::lcos::local::spinlock> guard(lk);
            double* yi = Y.data() + i * N;
            for (auto const& [n, xv] : xr) {
                yi[n] += av * xv;
            }
        });
}

