/* Compute the matrix multiplication Y=AX. A is a sparse MxK matrix in COO format.
   X is a sparse KxN matrix in COO format. Y is a dense MxN matrix in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Group A by row: A_rows[i] = list of (k, a_ik)
    std::vector<std::vector<std::pair<size_t, double>>> A_rows(M);
    for (auto const& e : A) {
        if (e.row < M && e.column < K)
            A_rows[e.row].emplace_back(e.column, e.value);
    }

    // Group X by row (k): X_rows[k] = list of (j, x_kj)
    std::vector<std::vector<std::pair<size_t, double>>> X_rows(K);
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_rows[e.row].emplace_back(e.column, e.value);
    }

    Y.assign(M * N, 0.0);

    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        std::vector<double> row(N, 0.0);
        for (auto const& [k, a_ik] : A_rows[i]) {
            for (auto const& [j, x_kj] : X_rows[k]) {
                row[j] += a_ik * x_kj;
            }
        }
        // write back to dense Y
        double* dst = Y.data() + i * N;
        std::copy(row.begin(), row.end(), dst);
    });
}

