   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Early exits
    if (M == 0 || K == 0 || N == 0) return;
    if (A.empty() || X.empty()) return;

    // Make sorted copies grouped by row
    std::vector<COOElement> A_sorted = A;
    std::vector<COOElement> X_sorted = X;

    std::stable_sort(A_sorted.begin(), A_sorted.end(),
                     [](auto const& lhs, auto const& rhs) {
                         return lhs.row < rhs.row ||
                               (lhs.row == rhs.row && lhs.column < rhs.column);
                     });
    std::stable_sort(X_sorted.begin(), X_sorted.end(),
                     [](auto const& lhs, auto const& rhs) {
                         return lhs.row < rhs.row ||
                               (lhs.row == rhs.row && lhs.column < rhs.column);
                     });

    // Build row pointers (CSR-like) for A (MxK) and X (KxN)
    std::vector<size_t> A_row_ptr(M + 1, 0);
    for (auto const& e : A_sorted) {
        if (e.row < M) ++A_row_ptr[e.row + 1];
    }
    for (size_t i = 1; i <= M; ++i) A_row_ptr[i] += A_row_ptr[i - 1];

    std::vector<size_t> X_row_ptr(K + 1, 0);
    for (auto const& e : X_sorted) {
        if (e.row < K) ++X_row_ptr[e.row + 1];
    }
    for (size_t i = 1; i <= K; ++i) X_row_ptr[i] += X_row_ptr[i - 1];

    // Parallel over independent rows of Y
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        std::vector<double> acc(N, 0.0);

        size_t a_begin = A_row_ptr[i];
        size_t a_end   = A_row_ptr[i + 1];

        for (size_t p = a_begin; p < a_end; ++p) {
            auto const& a = A_sorted[p]; // a at (i, k)
            size_t k = a.column;
            if (k >= K) continue;

            size_t x_begin = X_row_ptr[k];
            size_t x_end   = X_row_ptr[k + 1];

            // Accumulate row i of Y
            for (size_t q = x_begin; q < x_end; ++q) {
                auto const& x = X_sorted[q]; // x at (k, j)
                size_t j = x.column;
                if (j < N)
                    acc[j] += a.value * x.value;
            }
        }

        // Write row i
        double* yrow = Y.data() + i * N;
        std::copy(acc.begin(), acc.end(), yrow);
    });
}

