            for (size_t q = x_begin; q < x_end; ++q) {
                auto const& x = X_sorted[q]; // x at (k, j)
                size_t j = x.column;
                if (j < N)
                    acc[j] += a.value * x.value;
            }
        }

        // Write row i
        double* yrow = Y.data() + i * N;
        std::copy(acc.begin(), acc.end(), yrow);
