   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X,
          std::vector<double> &Y, size_t M, size_t K, size_t N)
{
    Y.assign(M * N, 0.0);

    // Build adjacency for A by row and X by row (i.e., by k)
    std::vector<std::vector<std::pair<size_t, double>>> A_by_row(M);
    A_by_row.reserve(M);
    for (auto const& e : A) {
        if (e.row < M && e.column < K)
            A_by_row[e.row].emplace_back(e.column, e.value);
    }

    std::vector<std::vector<std::pair<size_t, double>>> X_by_row(K);
    X_by_row.reserve(K);
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_by_row[e.row].emplace_back(e.column, e.value);
    }

    // Parallelize over rows of Y (disjoint writes, no locking needed)
    std::vector<size_t> rows(M);
    std::iota(rows.begin(), rows.end(), 0);

    hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
        [&](size_t i) {
            auto& Yi = Y; // capture by reference is fine; indexing is disjoint per i
            for (auto const& [k, a_val] : A_by_row[i]) {
                auto const& xrow = X_by_row[k];
                for (auto const& [n, x_val] : xrow) {
                    Yi[i * N + n] += a_val * x_val;
                }
            }
        });
