void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Index X by its rows (k)
    std::vector<std::vector<std::pair<size_t, double>>> X_by_row(K);
    for (auto const& e : X)
        X_by_row[e.row].emplace_back(e.column, e.value);

    // Group A by its rows (i)
    std::vector<std::vector<COOElement>> A_by_row(M);
    for (auto const& e : A)
        A_by_row[e.row].push_back(e);

    // Parallelize over output rows (no cross-row write conflicts)
    std::vector<size_t> rows(M);
    std::iota(rows.begin(), rows.end(), 0);

    hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
        [&](size_t i) {
            auto& Ai = A_by_row[i];
            for (auto const& a : Ai) {
                auto const& Xr = X_by_row[a.column]; // row k in X
                for (auto const& entry : Xr) {
                    size_t j = entry.first;
                    double xv = entry.second;
                    Y[i * N + j] += a.value * xv;
                }
            }
        });
}

