   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Build A grouped by rows: A_rows[i] holds (k, a_ik)
    std::vector<std::vector<std::pair<size_t, double>>> A_rows(M);
    A_rows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row < M && e.column < K)
            A_rows[e.row].emplace_back(e.column, e.value);
    }

    // Build X grouped by rows (by k): X_rows[k] holds (n, x_kn)
    std::vector<std::vector<std::pair<size_t, double>>> X_rows(K);
    X_rows.shrink_to_fit();
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_rows[e.row].emplace_back(e.column, e.value);
    }

    // Prepare Y
    Y.assign(M * N, 0.0);

    // Parallel over rows of Y (and A)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        // Skip empty rows quickly
        auto const& ai = A_rows[i];
        if (ai.empty()) return;

        std::vector<double> tmp(N, 0.0);

        // Accumulate tmp[n] = sum_k a[i,k] * x[k,n]
        for (auto const& [k, aval] : ai) {
            auto const& xk = X_rows[k];
            for (auto const& [n, xval] : xk) {
                tmp[n] += aval * xval;
            }
        }

        // Store into Y row-major
        double* yrow = Y.data() + i * N;
        std::copy(tmp.begin(), tmp.end(), yrow);
    });
}

