/* Compute the matrix multiplication Y=AX. A is a sparse MxK matrix in COO format.
   X is a sparse KxN matrix in COO format. Y is a dense MxN matrix in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          std::size_t M, std::size_t K, std::size_t N)
{
    Y.assign(M * N, 0.0);

    // Sort X by row (k dimension) and build row offsets
    std::vector<COOElement> Xsorted = X;
    std::sort(Xsorted.begin(), Xsorted.end(),
              [](COOElement const& a, COOElement const& b) {
                  return (a.row < b.row) || (a.row == b.row && a.column < b.column);
              });

    std::vector<std::size_t> x_counts(K, 0);
    for (auto const& e : Xsorted) {
        if (e.row < K) ++x_counts[e.row];
    }

    std::vector<std::size_t> x_offsets(K + 1, 0);
    std::partial_sum(x_counts.begin(), x_counts.end(), x_offsets.begin() + 1);

    // Striped row locks to reduce contention
    std::size_t num_locks = std::min<std::size_t>(M, 1024);
    std::vector<hpx::spinlock> locks(num_locks);

    hpx::for_loop(hpx::execution::par, std::size_t(0), A.size(),
        [&](std::size_t idx) {
            auto const& a = A[idx];
            std::size_t i = a.row;
            if (i >= M) return;
            std::size_t k = a.column;
            if (k >= K) return;

            auto begin = x_offsets[k];
            auto end   = x_offsets[k + 1];
            if (begin == end) return;

            auto& lock = locks[i % num_locks];
            std::lock_guard<hpx::spinlock> g(lock);

            double aval = a.value;
            std::size_t row_base = i * N;
            for (std::size_t t = begin; t < end; ++t) {
                auto const& x = Xsorted[t];
                std::size_t j = x.column;
                if (j < N) {
                    Y[row_base + j] += aval * x.value;
                }
            }
        });
}

