   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          std::size_t M, std::size_t K, std::size_t N)
{
    // Group A by row (size M) and X by row (size K)
    std::vector<std::vector<COOElement>> A_rows(M), X_rows(K);
    for (auto const& a : A) {
        if (a.row < M && a.column < K) A_rows[a.row].push_back(a);
    }
    for (auto const& x : X) {
        if (x.row < K && x.column < N) X_rows[x.row].push_back(x);
    }

    // Initialize Y to zeros
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else hpx::fill(hpx::execution::par, Y.begin(), Y.end(), 0.0);

    // Parallel over rows of A/Y. Each iteration writes to a disjoint row of Y.
    auto first = hpx::make_counting_iterator<std::size_t>(0);
    auto last  = hpx::make_counting_iterator<std::size_t>(M);
    hpx::for_each(hpx::execution::par, first, last, [&](std::size_t i) {
        double* yrow = Y.data() + i * N;
        for (auto const& a : A_rows[i]) {
            auto const& xrow = X_rows[a.column]; // a.column is k
            for (auto const& x : xrow) {
                yrow[x.column] += a.value * x.value;
            }
        }
    });
}

