generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Ensure Y is zeroed
    std::fill(Y.begin(), Y.end(), 0.0);

    if (A.empty() || X.empty() || M == 0 || K == 0 || N == 0) return;

    // Build row-structured A (by row i)
    std::vector<COOElement> A_sorted = A;
    std::stable_sort(A_sorted.begin(), A_sorted.end(),
                     [](auto const& a, auto const& b){
                         return (a.row < b.row) || (a.row == b.row && a.column < b.column);
                     });
    std::vector<size_t> A_rowptr(M + 1, 0);
    for (auto const& e : A_sorted)
        if (e.row < M) ++A_rowptr[e.row + 1];
    for (size_t i = 1; i <= M; ++i) A_rowptr[i] += A_rowptr[i - 1];

    // Build row-structured X (by row k)
    std::vector<COOElement> X_sorted = X;
    std::stable_sort(X_sorted.begin(), X_sorted.end(),
                     [](auto const& a, auto const& b){
                         return (a.row < b.row) || (a.row == b.row && a.column < b.column);
                     });
    std::vector<size_t> X_rowptr(K + 1, 0);
    for (auto const& e : X_sorted)
        if (e.row < K) ++X_rowptr[e.row + 1];
    for (size_t k2 = 1; k2 <= K; ++k2) X_rowptr[k2] += X_rowptr[k2 - 1];

    // Parallel over rows of A; each task writes to a distinct row of Y (no locking)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        size_t a_begin = A_rowptr[i];
        size_t a_end   = A_rowptr[i + 1];

        double* Yi = Y.data() + i * N;

        for (size_t pa = a_begin; pa < a_end; ++pa) {
            auto const& a = A_sorted[pa];
            size_t k = a.column;
            if (k >= K) continue;

            size_t x_begin = X_rowptr[k];
            size_t x_end   = X_rowptr[k + 1];

            for (size_t px = x_begin; px < x_end; ++px) {
                auto const& x = X_sorted[px];
                size_t n = x.column;
                if (n < N) {
                    Yi[n] += a.value * x.value;
                }
            }
        }
    });
}

