void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Ensure Y is the correct size and zero-initialized
    Y.assign(M * N, 0.0);

    // Group A by row (i) and X by row (k)
    std::vector<std::vector<COOElement>> A_by_row(M);
    for (auto const& a : A) {
        if (a.row < M && a.column < K)
            A_by_row[a.row].push_back(a);
    }

    std::vector<std::vector<COOElement>> X_by_row(K);
    for (auto const& x : X) {
        if (x.row < K && x.column < N)
            X_by_row[x.row].push_back(x);
    }

    // Parallel over rows of Y; each iteration writes to a distinct row -> no locks needed
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        auto const& arow = A_by_row[i];
        if (arow.empty()) return;

        double* yrow = Y.data() + i * N;

        for (auto const& a : arow) {
            auto const& xrow = X_by_row[a.column]; // all X entries with row = k
            double aval = a.value;
            for (auto const& x : xrow) {
                yrow[x.column] += aval * x.value;
            }
        }
    });
}

