    }
    for (size_t i = 1; i <= K; ++i) x_row_ptr[i] += x_row_ptr[i - 1];
    std::vector<COOElement> X_sorted(X.size());
    {
        std::vector<size_t> tmp = x_row_ptr;
        for (auto const& e : X) {
            if (e.row < K && e.column < N) X_sorted[tmp[e.row]++] = e;
        }
    }

    // Parallelize over rows of Y to avoid write races
    auto worker = [&](size_t i) {
        double* yrow = Y.data() + i * N;
