void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Build CSR-like by-row index for A (MxK)
    std::vector<size_t> a_row_ptr(M + 1, 0);
    for (auto const& e : A) {
        if (e.row < M && e.column < K) ++a_row_ptr[e.row + 1];
    }
    for (size_t i = 1; i <= M; ++i) a_row_ptr[i] += a_row_ptr[i - 1];
    std::vector<COOElement> A_sorted(A.size());
    {
        std::vector<size_t> tmp = a_row_ptr;
        for (auto const& e : A) {
            if (e.row < M && e.column < K) A_sorted[tmp[e.row]++] = e;
        }
    }

    // Build CSR-like by-row index for X (KxN)
    std::vector<size_t> x_row_ptr(K + 1, 0);
    for (auto const& e : X) {
