generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Build row-wise index for X: for each k, all (k, j, val)
    std::vector<std::vector<COOElement const*>> X_by_row(K);
    for (auto const& x : X) {
        if (x.row < K && x.column < N)
            X_by_row[x.row].push_back(&x);
    }

    // One lock per output row to protect accumulation
    std::vector<hpx::spinlock> row_locks(M);

    // Parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            if (a.row >= M || a.column >= K) return;

            auto const& xrow = X_by_row[a.column];
            if (xrow.empty()) return;

            // Compute contributions for this (i,k) against all (k, j)
            // Accumulate locally to minimize locking
            std::vector<std::pair<size_t, double>> contrib;
            contrib.reserve(xrow.size());
            for (auto const* xp : xrow) {
                // xp->column < N guaranteed by construction
                contrib.emplace_back(xp->column, a.value * xp->value);
            }

            // Commit to Y with a single lock on the output row
            auto& lk = row_locks[a.row];
            std::lock_guard<hpx::spinlock> guard(lk);
            double* yrow = Y.data() + a.row * N;
            for (auto const& cj : contrib) {
                yrow[cj.first] += cj.second;
            }
        }
    );
}

