   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          std::size_t M, std::size_t K, std::size_t N)
{
    // Dense Y (row-major)
    Y.assign(M * N, 0.0);

    // Build CSR-like structure for X grouped by rows (k)
    std::vector<std::size_t> row_ptr(K + 1, 0);
    for (auto const& x : X) row_ptr[x.row + 1]++;

    for (std::size_t k = 1; k <= K; ++k) row_ptr[k] += row_ptr[k - 1];

    std::vector<std::size_t> cols_x(X.size());
    std::vector<double>      vals_x(X.size());
    std::vector<std::size_t> fill(row_ptr.begin(), row_ptr.end());

    for (auto const& x : X) {
        auto idx = fill[x.row]++;
        cols_x[idx] = x.column;
        vals_x[idx] = x.value;
    }

    // Per-row locks for Y
    std::vector<hpx::spinlock> row_locks(M);

    // Parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            std::size_t i = a.row;
            std::size_t k = a.column;
            double aval = a.value;

            auto b = row_ptr[k];
            auto e = row_ptr[k + 1];

            // Accumulate into row i of Y
            std::lock_guard<hpx::spinlock> lg(row_locks[i]);
            for (std::size_t p = b; p < e; ++p) {
                std::size_t j = cols_x[p];
                Y[i * N + j] += aval * vals_x[p];
            }
        });
}

