void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Preindex X by its row (k)
    std::vector<std::vector<std::pair<size_t, double>>> X_by_row(K);
    X_by_row.reserve(K);
    for (auto const& e : X)
        X_by_row[e.row].emplace_back(e.column, e.value);

    // One lock per output row to avoid excessive contention
    std::vector<hpx::spinlock> row_locks(M);

    // Parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            auto const& xs = X_by_row[a.column];
            if (xs.empty()) return;

            size_t i = a.row;
            double aval = a.value;

            // Lock once per affected row and accumulate
            hpx::spinlock& lk = row_locks[i];
            std::lock_guard<hpx::spinlock> guard(lk);
            for (auto const& [n, xval] : xs)
                Y[i * N + n] += aval * xval;
        });
}

