   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    Y.assign(M * N, 0.0);

    // Build row index for X (group X entries by row)
    std::vector<COOElement> X_sorted = X;
    std::sort(X_sorted.begin(), X_sorted.end(),
              [](COOElement const& a, COOElement const& b) {
                  if (a.row != b.row) return a.row < b.row;
                  return a.column < b.column;
              });
    std::vector<size_t> x_row_off(K + 1, 0);
    {
        size_t i = 0;
        for (size_t r = 0; r < K; ++r) {
            x_row_off[r] = i;
            while (i < X_sorted.size() && X_sorted[i].row == r) ++i;
        }
        x_row_off[K] = X_sorted.size();
    }

    // Row locks for thread-safe accumulation
    using spinlock = hpx::lcos::local::spinlock;
    std::vector<spinlock> row_locks(M);

    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
                  [&](COOElement const& a) {
        if (a.row >= M || a.column >= K) return;
        size_t beg = x_row_off[a.column];
        size_t end = x_row_off[a.column + 1];
        if (beg == end) return;

        auto& lock = row_locks[a.row];
        for (size_t idx = beg; idx < end; ++idx) {
            auto const& x = X_sorted[idx]; // x.row == a.column
            if (x.column >= N) continue;
            double contrib = a.value * x.value;
            std::lock_guard<spinlock> g(lock);
            Y[a.row * N + x.column] += contrib;
        }
    });
}

