void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {
    // initialize Y
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // group X entries by row (k)
    std::vector<std::vector<COOElement>> X_by_row(K);
    for (auto const& x : X) X_by_row[x.row].push_back(x);

    // parallel over A's nonzeros
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            auto const& xs = X_by_row[a.column];
            for (auto const& x : xs) {
                size_t idx = a.row * N + x.column;
                std::atomic_ref<double> ar(Y[idx]);
                ar.fetch_add(a.value * x.value, std::memory_order_relaxed);
            }
        });
}

