    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Parallel over rows; each iteration writes to a disjoint row of Y (no locks needed)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        auto& arow = A_rows[i];
        double* yrow = Y.data() + i * N;
        for (auto const& [k, aval] : arow) {
            for (auto const& [j, xval] : X_rows[k]) {
                yrow[j] += aval * xval;
