          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Ensure Y is MxN and zero-initialized
    if (Y.size() != M * N)
        Y.assign(M * N, 0.0);
    else
        hpx::fill(hpx::execution::par, Y.begin(), Y.end(), 0.0);

