    for (auto const& x : X) {
        if (x.row < K && x.column < N)
            X_rows[x.row].emplace_back(x.column, x.value);
    }

    // Row locks for Y
    std::vector<hpx::spinlock> row_locks(M);

    // Parallel over nonzeros of A
    hpx::for_loop(hpx::execution::par, size_t(0), A.size(),
        [&](size_t idx) {
            auto const& a = A[idx];
            if (a.row >= M || a.column >= K) return;

            auto const& xr = X_rows[a.column];
            if (xr.empty()) return;

            // Accumulate locally to minimize lock time
            std::unordered_map<size_t, double> acc;
            acc.reserve(xr.size());
            for (auto const& [j, xv] : xr) {
                if (j < N) acc[j] += a.value * xv;
            }

            // Commit once under lock
            std::scoped_lock<hpx::spinlock> guard(row_locks[a.row]);
            double* yrow = Y.data() + a.row * N;
            for (auto const& kv : acc) {
                yrow[kv.first] += kv.second;
            }
        }
    );
