void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Group A by row (i -> list of (k, a_ik))
    std::vector<std::vector<std::pair<size_t, double>>> A_rows(M);
    for (auto const& e : A)
        A_rows[e.row].emplace_back(e.column, e.value);

    // Group X by row (k -> list of (j, x_kj))
    std::vector<std::vector<std::pair<size_t, double>>> X_rows(K);
    for (auto const& e : X)
        X_rows[e.row].emplace_back(e.column, e.value);

    // Initialize Y to zero
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Parallelize over rows of A/Y; each row is independent
    hpx::for_each(hpx::execution::par,
                  hpx::util::counting_iterator<size_t>(0),
                  hpx::util::counting_iterator<size_t>(M),
                  [&](size_t i) {
        auto const& rowA = A_rows[i];
        double* Yi = Y.data() + i * N;

        for (auto const& [k, aik] : rowA) {
            for (auto const& [j, xkj] : X_rows[k]) {
                Yi[j] += aik * xkj;
            }
        }
    });
}

