    Y.assign(M * N, 0.0);

    // Group X by row (k): Xrows[k] = list of (j, x_kj)
    std::vector<std::vector<std::pair<size_t, double>>> Xrows(K);
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            Xrows[e.row].emplace_back(e.column, e.value);
