   X is a sparse KxN matrix in COO format. Y is a dense MxN matrix in row-major.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Group X by row k: X_k = {(j, x_kj)}
    std::vector<std::vector<std::pair<size_t, double>>> X_by_row(K);
    X_by_row.reserve(K);
    for (auto const& e : X)
        X_by_row[e.row].emplace_back(e.column, e.value);

    // Group A by row i: A_i = {(k, a_ik)}
    std::vector<std::vector<std::pair<size_t, double>>> A_by_row(M);
    A_by_row.reserve(M);
    for (auto const& e : A)
        A_by_row[e.row].emplace_back(e.column, e.value);

    // Ensure Y has size M*N
    if (Y.size() != M * N) Y.assign(M * N, 0.0);

    // Parallel over rows of A/Y; each thread works on a private row buffer -> no races
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        std::vector<double> y_row(N, 0.0);
        for (auto const& [k, a_ik] : A_by_row[i]) {
            auto const& Xk = X_by_row[k];
            for (auto const& [j, x_kj] : Xk)
                y_row[j] += a_ik * x_kj;
        }
        // Write back the whole row
        double* dst = Y.data() + i * N;
        std::copy(y_row.begin(), y_row.end(), dst);
    });
}

