void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    Y.assign(M * N, 0.0);

    // Group X by row (i.e., by k)
    std::vector<std::vector<COOElement>> X_by_row(K);
    X_by_row.shrink_to_fit();
    for (auto const& x : X) {
        if (x.row < K && x.column < N)
            X_by_row[x.row].push_back(x);
    }

    // Per-row locks for Y
    std::vector<hpx::spinlock> row_locks(M);

    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            if (a.row >= M || a.column >= K) return;
            auto const& xs = X_by_row[a.column]; // X row = k
            for (auto const& x : xs) {
                if (x.column >= N) continue;
                double prod = a.value * x.value;
                auto& lock = row_locks[a.row];
                std::lock_guard<hpx::spinlock> g(lock);
                Y[a.row * N + x.column] += prod;
            }
        });
}

