generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          std::size_t M, std::size_t K, std::size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Build row-wise buckets for A (by A.row) and X (by X.row == k)
    std::vector<std::vector<COOElement>> A_rows(M);
    std::vector<std::vector<std::pair<std::size_t, double>>> X_rows(K);

    for (auto const& a : A) {
        if (a.row < M && a.column < K) A_rows[a.row].push_back(a);
    }
    for (auto const& x : X) {
        if (x.row < K && x.column < N) X_rows[x.row].emplace_back(x.column, x.value);
    }

    // Parallel over rows of Y
    hpx::for_loop(hpx::execution::par, std::size_t(0), M, [&](std::size_t i) {
        // Temporary row accumulator to avoid synchronization
        std::vector<double> rowY(N, 0.0);

        for (auto const& a : A_rows[i]) {
            auto const k = a.column;
            double const aval = a.value;
            for (auto const& [j, xval] : X_rows[k]) {
                rowY[j] += aval * xval;
            }
        }

        // Write back to dense Y
        double* yrow = Y.data() + i * N;
        for (std::size_t j = 0; j < N; ++j) {
            yrow[j] = rowY[j];
        }
    });
}

