void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Build CSR for A by rows
    std::vector<size_t> a_row_ptr(M + 1, 0);
    for (auto const& e : A) ++a_row_ptr[e.row + 1];
    for (size_t i = 1; i <= M; ++i) a_row_ptr[i] += a_row_ptr[i - 1];

    std::vector<size_t> a_col_idx(A.size());
    std::vector<double> a_val(A.size());
    {
        std::vector<size_t> cursor = a_row_ptr;
        for (auto const& e : A) {
            size_t pos = cursor[e.row]++;
            a_col_idx[pos] = e.column;
            a_val[pos] = e.value;
        }
    }

    // Build CSR for X by rows (keyed by k)
    std::vector<size_t> x_row_ptr(K + 1, 0);
    for (auto const& e : X) ++x_row_ptr[e.row + 1];
    for (size_t k = 1; k <= K; ++k) x_row_ptr[k] += x_row_ptr[k - 1];

    std::vector<size_t> x_col_idx(X.size());
    std::vector<double> x_val(X.size());
    {
        std::vector<size_t> cursor = x_row_ptr;
        for (auto const& e : X) {
            size_t pos = cursor[e.row]++;
            x_col_idx[pos] = e.column;
            x_val[pos] = e.value;
        }
    }

    // Parallel over rows of Y (no synchronization needed across rows)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        size_t a_beg = a_row_ptr[i];
        size_t a_end = a_row_ptr[i + 1];
        for (size_t ap = a_beg; ap < a_end; ++ap) {
            size_t k = a_col_idx[ap];
            double aval = a_val[ap];
            size_t xb = x_row_ptr[k];
            size_t xe = x_row_ptr[k + 1];
            for (size_t xp = xb; xp < xe; ++xp) {
                size_t j = x_col_idx[xp];
                Y[i * N + j] += aval * x_val[xp];
            }
        }
    });
}

