void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Sort X by row and build row pointers
    std::vector<COOElement> X_sorted = X;
    std::sort(X_sorted.begin(), X_sorted.end(),
              [](COOElement const& a, COOElement const& b) {
                  if (a.row != b.row) return a.row < b.row;
                  return a.column < b.column;
              });

    std::vector<size_t> x_row_ptr(K + 1, 0);
    for (auto const& e : X_sorted) ++x_row_ptr[e.row + 1];
    for (size_t r = 1; r <= K; ++r) x_row_ptr[r] += x_row_ptr[r - 1];

    // Striped locks for concurrent accumulation
    constexpr size_t L = 4096;
    std::vector<hpx::spinlock> locks(L);

    auto& locks_ref = locks; // capture by reference in lambda
    auto lock_for = [&](size_t idx) -> hpx::spinlock& {
        return locks_ref[idx % L];
    };

    // Parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
                  [&](COOElement const& a) {
                      size_t k = a.column;
                      size_t i = a.row;
                      size_t begin = x_row_ptr[k];
                      size_t end = x_row_ptr[k + 1];

                      for (size_t p = begin; p < end; ++p) {
                          auto const& x = X_sorted[p]; // x.row == k
                          size_t n = x.column;
                          double v = a.value * x.value;
                          size_t y_idx = i * N + n;

                          std::scoped_lock<hpx::spinlock> g(lock_for(y_idx));
                          Y[y_idx] += v;
                      }
                  });
}

