generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // prepare Y
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // group X by k (row of X)
    std::vector<std::vector<COOElement>> X_by_k(K);
    X_by_k.shrink_to_fit();
    for (auto const& e : X) {
        if (e.row < K) X_by_k[e.row].push_back(e);
    }

    // per-row locks for Y
    std::vector<hpx::spinlock> row_locks(M);

    // parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            size_t i = a.row;
            size_t k = a.column;
            if (i >= M || k >= K) return;
            auto const& xlist = X_by_k[k];
            if (xlist.empty()) return;

            std::lock_guard<hpx::spinlock> g(row_locks[i]);
            double const aval = a.value;
            double* yrow = Y.data() + i * N;
            for (auto const& x : xlist) {
                size_t j = x.column;
                if (j < N) yrow[j] += aval * x.value;
            }
        });
}

