generated_output:
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N)
{
    // Build row-wise buckets for A (by A.row) and X (by X.row == k)
    std::vector<std::vector<std::pair<size_t, double>>> A_rows(M);
    A_rows.shrink_to_fit();
    for (auto const& a : A) A_rows[a.row].emplace_back(a.column, a.value);

    std::vector<std::vector<std::pair<size_t, double>>> X_rows(K);
    X_rows.shrink_to_fit();
    for (auto const& x : X) X_rows[x.row].emplace_back(x.column, x.value);

    Y.assign(M * N, 0.0);

    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        if (A_rows[i].empty()) return;

        std::vector<double> yrow(N, 0.0);
        for (auto const& [k, aval] : A_rows[i]) {
            if (k >= K) continue;
            for (auto const& [j, xval] : X_rows[k]) {
                yrow[j] += aval * xval;
            }
        }
        std::copy(yrow.begin(), yrow.end(), Y.begin() + i * N);
    });
}

