generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          std::size_t M, std::size_t K, std::size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Group X by row (i.e., by k)
    std::vector<std::vector<COOElement>> X_by_row(K);
    for (auto const& x : X) {
        if (x.row < K && x.column < N)
            X_by_row[x.row].push_back(x);
    }

    // One lock per output row
    std::vector<hpx::spinlock> row_locks(M);

    // Parallel over nonzeros of A
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& a) {
            std::size_t i = a.row;
            std::size_t k = a.column;
            if (i >= M || k >= K) return;

            auto const& xrow = X_by_row[k];
            if (xrow.empty()) return;

            // Lock the output row once per A element
            std::scoped_lock<hpx::spinlock> lk(row_locks[i]);
            double aval = a.value;
            double* yrow = Y.data() + i * N;
            for (auto const& x : xrow) {
                // x: (k, j, xval)
                if (x.column < N)
                    yrow[x.column] += aval * x.value;
            }
        });
}

