void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Preprocess X by rows (K)
    std::vector<std::vector<std::pair<size_t, double>>> X_by_row(K);
    X_by_row.reserve(K);
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_by_row[e.row].emplace_back(e.column, e.value);
    }

    // Preprocess A by rows (M) to avoid synchronization on Y
    std::vector<std::vector<COOElement>> A_by_row(M);
    A_by_row.reserve(M);
    for (auto const& e : A) {
        if (e.row < M && e.column < K)
            A_by_row[e.row].push_back(e);
    }

    // Parallel over rows of A/Y
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        double* yrow = Y.data() + i * N;
        auto const& row_elems = A_by_row[i];
        for (auto const& a : row_elems) {
            auto const& xrow = X_by_row[a.column];
            double aval = a.value;
            for (auto const& xc : xrow) {
                yrow[xc.first] += aval * xc.second;
            }
