          std::size_t M, std::size_t K, std::size_t N)
{
    if (Y.size() != M * N) Y.assign(M * N, 0.0);

    // Group A by row (i) and X by row (k)
    std::vector<std::vector<COOElement>> A_rows(M);
    A_rows.shrink_to_fit();
    for (auto const& a : A) {
        if (a.row < M && a.column < K) A_rows[a.row].push_back(a);
