    Y.assign(M * N, 0.0);

    // Group X by rows (row = k), each entry holds (j, x_kj)
    std::vector<std::vector<std::pair<size_t, double>>> X_rows(K);
    X_rows.shrink_to_fit();
    for (auto const& e : X) {
