   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,-2}, {0,1,1}, {1,1,-1}] X=[{0,1,2}, {1,0,-1}]
   output: Y=[{-1,-4}, {1,0}]
*/
void spmm(std::vector<COOElement> const& A, std::vector<COOElement> const& X, std::vector<double> &Y, size_t M, size_t K, size_t N) {

generated_output:
void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Sort X by row to build row pointers
    std::vector<COOElement> Xsorted = X;
    std::stable_sort(Xsorted.begin(), Xsorted.end(),
        [](COOElement const& a, COOElement const& b) {
            return a.row < b.row || (a.row == b.row && a.column < b.column);
        });

    // Build CSR-like row pointers for X
    std::vector<size_t> x_row_ptr(K + 1, 0);
    for (auto const& e : Xsorted) {
        if (e.row < K) ++x_row_ptr[e.row + 1];
    }
    for (size_t r = 1; r <= K; ++r) x_row_ptr[r] += x_row_ptr[r - 1];

    // Parallel over nonzeros of A
    hpx::for_loop(hpx::execution::par, size_t(0), A.size(),
        [&](size_t idx) {
            auto const& ae = A[idx];
            size_t i = ae.row;
            size_t k = ae.column;
            if (i >= M || k >= K) return;

            double a_val = ae.value;
            size_t begin = x_row_ptr[k];
            size_t end   = x_row_ptr[k + 1];

            for (size_t p = begin; p < end; ++p) {
                auto const& xe = Xsorted[p];
                size_t j = xe.column;
                if (j >= N) continue;

                double prod = a_val * xe.value;
                std::atomic_ref<double> ref(Y[i * N + j]);
                ref.fetch_add(prod, std::memory_order_relaxed);
            }
        });
}

