          std::vector<COOElement> const& X,
          std::vector<double>& Y,
          size_t M, size_t K, size_t N)
{
    // Prepare output
    Y.assign(M * N, 0.0);

    // Index X by row (k)
    std::vector<std::vector<COOElement>> X_by_row(K);
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            X_by_row[e.row].push_back(e);
    }

    // One mutex per output row to avoid races
    std::vector<std::mutex> row_mutexes(M);

    // Parallel over nonzeros of A
