void spmm(std::vector<COOElement> const& A,
          std::vector<COOElement> const& X,
          std::vector<double> &Y,
          size_t M, size_t K, size_t N)
{
    // Prepare adjacency lists: A by rows, X by rows
    std::vector<std::vector<std::pair<size_t,double>>> Arows(M);
    Arows.shrink_to_fit();
    for (auto const& e : A) {
        if (e.row < M && e.column < K)
            Arows[e.row].emplace_back(e.column, e.value);
    }

    std::vector<std::vector<std::pair<size_t,double>>> Xrows(K);
    Xrows.shrink_to_fit();
    for (auto const& e : X) {
        if (e.row < K && e.column < N)
            Xrows[e.row].emplace_back(e.column, e.value);
    }

    // Ensure Y is the right size and zero-initialized
    if (Y.size() != M * N) Y.assign(M * N, 0.0);
    else std::fill(Y.begin(), Y.end(), 0.0);

    // Parallel over rows of Y; rows are independent
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        auto const& arow = Arows[i];
        if (arow.empty()) return;

        double* yrow = Y.data() + i * N;
        for (auto const& [k, aval] : arow) {
            if (k >= Xrows.size()) continue;
            auto const& xrow = Xrows[k];
            for (auto const& [n, xval] : xrow) {
                yrow[n] += aval * xval;
            }
        }
    });
}

