generated_output:
void spmv(double alpha,
          std::vector<COOElement> const& A,
          std::vector<double> const& x,
          double beta,
          std::vector<double>& y,
          size_t M,
          size_t N)
{
    if (x.size() != N || y.size() != M)
        throw std::invalid_argument("Dimension mismatch");

    // y = beta * y
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
                  [beta](double& yi) { yi *= beta; });

    if (alpha == 0.0 || A.empty())
        return;

    // Accumulate alpha * A * x into y with per-row locking
    std::vector<std::mutex> locks(M);

    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
                  [&](COOElement const& e) {
                      if (e.row >= M || e.column >= N)
                          throw std::out_of_range("COO index out of range");
                      double contrib = alpha * e.value * x[e.column];
                      std::lock_guard<std::mutex> guard(locks[e.row]);
                      y[e.row] += contrib;
                  });
}

