generated_output:
void spmv(double alpha,
          std::vector<COOElement> const& A,
          std::vector<double> const& x,
          double beta,
          std::vector<double> &y,
          size_t M, size_t N)
{
    if (y.size() != M || x.size() != N) return;
    if (M == 0 || N == 0) return;

    // Sort entries by row (and column for determinism)
    std::vector<COOElement> Asorted = A;
    hpx::sort(hpx::execution::par, Asorted.begin(), Asorted.end(),
              [](COOElement const& a, COOElement const& b) {
                  return (a.row < b.row) || (a.row == b.row && a.column < b.column);
              });

    // Build row pointers (CSR-like)
    std::vector<size_t> row_ptr(M + 1, 0);
    for (auto const& e : Asorted) {
        if (e.row < M) row_ptr[e.row + 1]++;
    }
    std::partial_sum(row_ptr.begin(), row_ptr.end(), row_ptr.begin());

    // Indices 0..M-1 to iterate rows in parallel
    std::vector<size_t> rows(M);
    std::iota(rows.begin(), rows.end(), 0);

    hpx::for_each(hpx::execution::par, rows.begin(), rows.end(),
                  [&](size_t i) {
                      double sum = 0.0;
                      for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
                          auto const& e = Asorted[k];
                          // assume valid columns; skip if out-of-range
                          if (e.column < N) sum += e.value * x[e.column];
                      }
                      y[i] = alpha * sum + beta * y[i];
                  });
}

