void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {
    if (x.size() != N || y.size() != M) throw std::invalid_argument("Dimension mismatch");

    // Scale y by beta in parallel
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
                  [beta](double& yi) { yi *= beta; });

    // Accumulate alpha * A * x into a temporary vector with row-level locks
    std::vector<double> temp(M, 0.0);
    std::vector<hpx::spinlock> row_locks(M);

    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
                  [&](COOElement const& e) {
                      if (e.row >= M || e.column >= N) return;
                      double contrib = alpha * e.value * x[e.column];
                      std::scoped_lock<hpx::spinlock> l(row_locks[e.row]);
                      temp[e.row] += contrib;
                  });

    // y += temp in parallel
    hpx::for_each_n(hpx::execution::par, std::size_t{0}, M,
                    [&](std::size_t i) { y[i] += temp[i]; });
