    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) { y[i] *= beta; });

    // y += alpha * A * x
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        double sum = 0.0;
        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k) {
            auto const& e = As[k];
            sum += e.value * x[e.column];
