          std::vector<double> const& x,
          double beta,
          std::vector<double>& y,
          std::size_t M,
          std::size_t N)
{
    if (x.size() != N || y.size() != M) {
        throw std::invalid_argument("Dimension mismatch");
    }

    // Scale y by beta
    if (beta == 0.0) {
        hpx::fill(hpx::execution::par, y.begin(), y.end(), 0.0);
