generated_output:
void spmv(double alpha,
          std::vector<COOElement> const& A,
          std::vector<double> const& x,
          double beta,
          std::vector<double>& y,
          size_t M,
          size_t N)
{
    if (x.size() != N || y.size() != M)
        throw std::invalid_argument("Dimension mismatch");

    // y = beta*y
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
                  [beta](double& yi) { yi *= beta; });

    // tmp = alpha * A * x (atomic row accumulators)
    std::vector<hpx::atomic<double>> tmp(M);
    for (auto& t : tmp) t.store(0.0, std::memory_order_relaxed);

    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
                  [&](COOElement const& e) {
                      if (e.row >= M || e.column >= N)
                          throw std::out_of_range("COO index out of bounds");
                      double contrib = alpha * e.value * x[e.column];
                      tmp[e.row].fetch_add(contrib, std::memory_order_relaxed);
                  });

    // y += tmp
    auto b = hpx::util::make_counting_iterator<size_t>(0);
    auto e = hpx::util::make_counting_iterator<size_t>(M);
    hpx::for_each(hpx::execution::par, b, e,
                  [&](size_t i) { y[i] += tmp[i].load(std::memory_order_relaxed); });
}

