    // Scale y by beta
    hpx::for_each(hpx::execution::par, y.begin(), y.end(), [beta](double& yi) { yi *= beta; });

    // Temporary atomic accumulation per row
    std::vector<std::atomic<double>> tmp(M);
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) { tmp[i].store(0.0, std::memory_order_relaxed); });

