    if (y.size() != M) y.resize(M, 0.0);

    // Scale y by beta (or zero it if beta == 0)
    if (beta == 0.0) {
        hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) { y[i] = 0.0; });
    } else if (beta != 1.0) {
