void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {
    if (y.size() != M || x.size() != N) {
        throw std::invalid_argument("Dimension mismatch");
    }

    // temp = A * x
    std::vector<double> temp(M, 0.0);
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
        [&](COOElement const& e) {
            double contrib = e.value * x[e.column];
            std::atomic_ref<double> ref(temp[e.row]);
            ref.fetch_add(contrib, std::memory_order_relaxed);
