    // y = beta*y + alpha*temp
    auto first = hpx::make_counting_iterator<size_t>(0);
    auto last  = hpx::make_counting_iterator<size_t>(M);
    hpx::for_each(hpx::execution::par, first, last,
        [&](size_t i) {
            y[i] = beta * y[i] + alpha * temp[i];
        });
}

