generated_output:
void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {
    if (x.size() != N || y.size() != M) throw std::invalid_argument("Dimension mismatch");

    const size_t nnz = A.size();

    // Build CSR-like row structure from COO
    std::vector<size_t> counts(M, 0);
    for (auto const& e : A) {
        if (e.row >= M || e.column >= N) throw std::out_of_range("COO index out of range");
        counts[e.row]++;
    }

    std::vector<size_t> row_offsets(M + 1, 0);
    for (size_t i = 0; i < M; ++i) row_offsets[i + 1] = row_offsets[i] + counts[i];

    std::vector<size_t> cols(nnz);
    std::vector<double> vals(nnz);
    std::vector<size_t> curs = row_offsets;
    for (auto const& e : A) {
        size_t pos = curs[e.row]++;
        cols[pos] = e.column;
        vals[pos] = e.value;
    }

    // y = alpha * A * x + beta * y
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        double sum = 0.0;
        for (size_t k = row_offsets[i]; k < row_offsets[i + 1]; ++k) {
            sum += vals[k] * x[cols[k]];
        }
        y[i] = alpha * sum + beta * y[i];
    });
}

