void spmv(double alpha,
          std::vector<COOElement> const& A,
          std::vector<double> const& x,
          double beta,
          std::vector<double> &y,
          size_t M, size_t N)
{
    if (y.size() != M || x.size() != N) {
        throw std::invalid_argument("Dimension mismatch");
    }

    // y = beta * y
    hpx::for_loop(hpx::execution::par, size_t(0), M,
                  [&](size_t i) { y[i] *= beta; });

    if (alpha == 0.0 || A.empty()) return;

    // Protect per-row accumulation
    std::vector<hpx::spinlock> row_locks(M);

    // y[row] += alpha * A_ij * x[col]
    hpx::for_each(hpx::execution::par, A.begin(), A.end(),
                  [&](COOElement const& e) {
                      if (e.row >= M || e.column >= N) {
                          throw std::out_of_range("COO index out of bounds");
                      }
                      double contrib = alpha * e.value * x[e.column];
                      std::lock_guard<hpx::spinlock> lk(row_locks[e.row]);
                      y[e.row] += contrib;
                  });
}

