void spmv(double alpha, std::vector<COOElement> const& A, std::vector<double> const& x, double beta, std::vector<double> &y, size_t M, size_t N) {

generated_output:
void spmv(double alpha, std::vector<COOElement> const& Acoo, std::vector<double> const& x,
          double beta, std::vector<double> &y, size_t M, size_t N)
{
    // Build CSR from COO
    std::vector<COOElement> A = Acoo;
    std::sort(A.begin(), A.end(), [](auto const& a, auto const& b){
        return a.row < b.row || (a.row == b.row && a.column < b.column);
    });

    std::vector<size_t> row_ptr(M + 1, 0);
    std::vector<size_t> col_idx; col_idx.reserve(A.size());
    std::vector<double> val;     val.reserve(A.size());

    for (auto const& e : A) {
        if (e.row < M) row_ptr[e.row + 1]++;
    }
    for (size_t i = 1; i <= M; ++i) row_ptr[i] += row_ptr[i - 1];

    col_idx.resize(A.size());
    val.resize(A.size());
    // Temporary copy of row_ptr to use as insertion positions
    std::vector<size_t> next(row_ptr.begin(), row_ptr.end());
    for (auto const& e : A) {
        if (e.row >= M || e.column >= N) continue;
        auto pos = next[e.row]++;
        col_idx[pos] = e.column;
        val[pos]     = e.value;
    }

    // y = alpha*A*x + beta*y (parallel over rows)
    hpx::for_loop(hpx::execution::par, size_t(0), M, [&](size_t i) {
        double sum = 0.0;
        for (size_t k = row_ptr[i]; k < row_ptr[i + 1]; ++k)
            sum += val[k] * x[col_idx[k]];
        y[i] = alpha * sum + beta * y[i];
    });
}

