    // Ensure z is large enough
    size_t max_idx = 0;
    for (auto const& e : x) if (e.index > max_idx) max_idx = e.index;
    for (auto const& e : y) if (e.index > max_idx) max_idx = e.index;
    if (z.size() <= max_idx) z.resize(max_idx + 1);

    // Atomic buffer for safe parallel accumulation
    std::vector<std::atomic<double>> za(z.size());
    hpx::for_each(hpx::execution::par, za.begin(), za.end(),
        [](std::atomic<double>& a) { a.store(0.0, std::memory_order_relaxed); });

    // Accumulate alpha*x
    hpx::for_each(hpx::execution::par, x.begin(), x.end(),
        [alpha, &za](Element const& e) {
