generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    using hpx::execution::par;

    // Build combined list: tmp = alpha*x followed by y
    std::vector<Element> tmp(x.size() + y.size());
    hpx::for_loop(par, std::size_t(0), x.size(), [&](std::size_t i) {
        tmp[i].index = x[i].index;
        tmp[i].value = alpha * x[i].value;
    });
    hpx::for_loop(par, std::size_t(0), y.size(), [&](std::size_t i) {
        tmp[x.size() + i].index = y[i].index;
        tmp[x.size() + i].value = y[i].value;
    });

    if (tmp.empty()) {
        std::fill(z.begin(), z.end(), 0.0);
        return;
    }

    // Sort by index (parallel)
    hpx::sort(par, tmp.begin(), tmp.end(),
              [](Element const& a, Element const& b) { return a.index < b.index; });

    // Reduce duplicates (sequential linear pass after parallel sort)
    std::vector<Element> uniq;
    uniq.reserve(tmp.size());
    Element accum = tmp[0];
    for (std::size_t i = 1; i < tmp.size(); ++i) {
        if (tmp[i].index == accum.index)
            accum.value += tmp[i].value;
        else {
            if (accum.value != 0.0) uniq.push_back(accum);
            accum = tmp[i];
        }
    }
    if (accum.value != 0.0) uniq.push_back(accum);

    // Resize/zero z, then scatter results
    std::size_t max_index = uniq.empty() ? 0 : uniq.back().index;
    if (z.size() < max_index + 1) z.resize(max_index + 1, 0.0);
    else std::fill(z.begin(), z.end(), 0.0);

    hpx::for_loop(par, std::size_t(0), uniq.size(), [&](std::size_t i) {
        z[uniq[i].index] = uniq[i].value;
    });
}

