   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    using idx_t = std::size_t;

    // Build contributions: z[i] += alpha*x[i] and z[i] += y[i]
    struct Pair { idx_t idx; double val; };
    std::vector<Pair> contrib;
    contrib.resize(x.size() + y.size());

    // Fill contributions in parallel
    hpx::for_loop(hpx::execution::par, std::size_t(0), x.size(), [&](std::size_t i) {
        contrib[i] = {x[i].index, alpha * x[i].value};
    });
    hpx::for_loop(hpx::execution::par, std::size_t(0), y.size(), [&](std::size_t j) {
        contrib[x.size() + j] = {y[j].index, y[j].value};
    });

    // If both empty, just clear z
    if (contrib.empty()) {
        z.clear();
        return;
    }

    // Determine required size for z
    idx_t max_idx = 0;
    for (auto const& p : contrib) max_idx = std::max(max_idx, p.idx);
    if (z.size() < max_idx + 1) z.resize(max_idx + 1, 0.0);

    // Zero-initialize z in parallel
    hpx::for_loop(hpx::execution::par, std::size_t(0), z.size(), [&](std::size_t i) { z[i] = 0.0; });

    // Sort contributions by index (parallel)
    hpx::ranges::sort(hpx::execution::par, contrib, [](auto const& a, auto const& b) {
        return a.idx < b.idx;
    });

    // Find segments of equal indices
    std::vector<std::pair<std::size_t, std::size_t>> segments; // [begin, end) in contrib
    segments.reserve(contrib.size());
    std::size_t begin = 0;
    for (std::size_t i = 1; i <= contrib.size(); ++i) {
        if (i == contrib.size() || contrib[i].idx != contrib[begin].idx) {
            segments.emplace_back(begin, i);
            begin = i;
        }
    }

    // Reduce each segment in parallel and write to z (no races: disjoint indices)
    hpx::for_loop(hpx::execution::par, std::size_t(0), segments.size(), [&](std::size_t s) {
        auto [b, e] = segments[s];
        double sum = 0.0;
        for (std::size_t k = b; k < e; ++k) sum += contrib[k].val;
        z[contrib[b].idx] = sum;
    });
}

