void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    // Determine required size
    size_t max_idx = 0;
    if (!x.empty())
        max_idx = std::max(max_idx, std::max_element(x.begin(), x.end(),
                             [](auto const& a, auto const& b){ return a.index < b.index; })->index);
    if (!y.empty())
        max_idx = std::max(max_idx, std::max_element(y.begin(), y.end(),
                             [](auto const& a, auto const& b){ return a.index < b.index; })->index);

    if (z.size() < max_idx + 1) z.resize(max_idx + 1, 0.0);
    else std::fill(z.begin(), z.end(), 0.0);

    // First set y
    hpx::ranges::for_each(hpx::execution::par, y, [&](Element const& e) {
        z[e.index] = e.value;
    });

    // Then add alpha * x
    hpx::ranges::for_each(hpx::execution::par, x, [&](Element const& e) {
        z[e.index] += alpha * e.value;
    });
}

