void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    // Determine size
    size_t max_idx = 0;
    if (!x.empty()) max_idx = std::max(max_idx, hpx::ranges::max_element(x, {}, &Element::index)->index);
    if (!y.empty()) max_idx = std::max(max_idx, hpx::ranges::max_element(y, {}, &Element::index)->index);

    z.assign(max_idx + 1, 0.0);

    // z = y
    hpx::ranges::for_each(hpx::execution::par, y,
        [&z](Element const& e) { z[e.index] = e.value; });

    // z += alpha * x
    if (alpha != 0.0) {
        hpx::ranges::for_each(hpx::execution::par, x,
            [&z, alpha](Element const& e) { z[e.index] += alpha * e.value; });
    }
}

