   Example:

   input: x=[{5, 12}, {8, 3}, {12, -1}], y=[{3, 1}, {5, -2}, {7, 1}, {8, -3}], alpha=1
   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    // Determine output size
    std::size_t max_idx = 0;
    auto upd_max = [&](std::vector<Element> const& v) {
        for (auto const& e : v) max_idx = std::max(max_idx, e.index);
    };
    upd_max(x);
    upd_max(y);
    std::size_t n = (z.empty() ? 0 : z.size());
    if (max_idx + 1 > n) n = max_idx + 1;

    z.assign(n, 0.0);

    // Lock striping to avoid races on overlapping indices
    static constexpr std::size_t stripes = 4096;
    std::array<hpx::spinlock, stripes> locks;

    auto add_vec = [&](std::vector<Element> const& v, double scale) {
        hpx::for_each(hpx::execution::par, v.begin(), v.end(),
            [&](Element const& e) {
                if (e.index >= z.size()) return; // safety
                auto& m = locks[e.index % stripes];
                std::lock_guard<hpx::spinlock> l(m);
                z[e.index] += scale * e.value;
            });
    };

    auto f1 = hpx::async([&] { add_vec(x, alpha); });
    auto f2 = hpx::async([&] { add_vec(y, 1.0); });
    hpx::wait_all(f1, f2);
}

