   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    auto max_index_in = [](std::vector<Element> const& v) -> std::size_t {
        if (v.empty()) return 0;
        return std::max_element(v.begin(), v.end(),
                                [](Element const& a, Element const& b) { return a.index < b.index; })
            ->index;
    };

    if (x.empty() && y.empty()) {
        z.clear();
        return;
    }

    std::size_t max_idx = std::max(max_index_in(x), max_index_in(y));
    z.assign(max_idx + 1, 0.0);

    std::vector<Element> combined;
    combined.resize(x.size() + y.size());

    hpx::transform(hpx::execution::par, x.begin(), x.end(), combined.begin(),
                   [alpha](Element const& e) { return Element{e.index, alpha * e.value}; });
    hpx::transform(hpx::execution::par, y.begin(), y.end(), combined.begin() + x.size(),
                   [](Element const& e) { return e; });

    hpx::sort(hpx::execution::par, combined.begin(), combined.end(),
              [](Element const& a, Element const& b) { return a.index < b.index; });

    if (combined.empty()) return;

    std::size_t curr = combined[0].index;
    double acc = 0.0;
    for (auto const& e : combined) {
        if (e.index != curr) {
            z[curr] = acc;
            curr = e.index;
            acc = e.value;
        } else {
            acc += e.value;
        }
    }
    z[curr] = acc;
}

