    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
        [&](Element const& e) {
            auto& m = locks[e.index];
            std::lock_guard<hpx::lcos::local::spinlock> lk(m);
            z[e.index] += e.value;
        });
}

