   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double>& z)
{
    // Handle empty inputs
    if (x.empty() && y.empty()) {
        z.clear();
        return;
    }

    // Determine required size
    std::size_t max_index = 0;
    auto update_max = [&max_index](std::vector<Element> const& v) {
        for (auto const& e : v) max_index = std::max(max_index, e.index);
    };
    update_max(x);
    update_max(y);

    std::size_t n = max_index + 1;
    if (z.size() != n) {
        z.assign(n, 0.0);
    } else {
        std::fill(z.begin(), z.end(), 0.0);
    }

    // One lock per position to avoid data races on z[i]
    std::vector<hpx::spinlock> locks(n);

    // y contribution
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
        [&](Element const& e) {
            auto idx = e.index;
            auto val = e.value;
            std::scoped_lock<hpx::spinlock> l(locks[idx]);
            z[idx] += val;
        });

    // alpha * x contribution
    if (alpha != 0.0) {
        hpx::for_each(hpx::execution::par, x.begin(), x.end(),
            [&](Element const& e) {
                auto idx = e.index;
                auto val = alpha * e.value;
                std::scoped_lock<hpx::spinlock> l(locks[idx]);
                z[idx] += val;
            });
    }
}

