void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
  // Determine required size
  auto max_idx = std::size_t{0};
  if (!x.empty())
    max_idx = std::max(max_idx, std::max_element(x.begin(), x.end(),
                  [](auto const& a, auto const& b){ return a.index < b.index; })->index);
  if (!y.empty())
    max_idx = std::max(max_idx, std::max_element(y.begin(), y.end(),
                  [](auto const& a, auto const& b){ return a.index < b.index; })->index);

  // Resize/clear z
  if (z.size() < max_idx + 1) z.assign(max_idx + 1, 0.0);
  else std::fill(z.begin(), z.end(), 0.0);

  // Parallel add: z[idx] += scale * value
  auto add_vec = [&](std::vector<Element> const& v, double scale) {
    hpx::for_each(hpx::execution::par, v.begin(), v.end(),
      [&](Element const& e) {
        std::atomic_ref<double> ref(z[e.index]);
        ref.fetch_add(scale * e.value, std::memory_order_relaxed);
      });
  };

  add_vec(x, alpha);
  add_vec(y, 1.0);
}

