generated_output:
void sparseAxpy(double alpha,
                std::vector<Element> const& x,
                std::vector<Element> const& y,
                std::vector<double>& z)
{
    // Determine required size
    std::size_t max_idx = 0;
    auto upd_max = [&](std::vector<Element> const& v) {
        if (!v.empty()) {
            auto it = std::max_element(v.begin(), v.end(),
                                       [](auto const& a, auto const& b) { return a.index < b.index; });
            max_idx = std::max(max_idx, it->index);
        }
    };
    upd_max(x);
    upd_max(y);

    std::size_t n = max_idx + 1;
    z.assign(n, 0.0);

    // Atomic accumulation buffer to avoid races
    std::vector<std::atomic<double>> za(n);
    for (auto& a : za) a.store(0.0, std::memory_order_relaxed);

    // Accumulate alpha*x
    hpx::for_each(hpx::execution::par, x.begin(), x.end(),
                  [&](Element const& e) {
                      za[e.index].fetch_add(alpha * e.value, std::memory_order_relaxed);
                  });

    // Accumulate y
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
                  [&](Element const& e) {
                      za[e.index].fetch_add(e.value, std::memory_order_relaxed);
                  });

    // Copy back to dense z
    hpx::for_each(hpx::execution::par, std::size_t(0), n,
                  [&](std::size_t i) { z[i] = za[i].load(std::memory_order_relaxed); });
}

