    std::size_t max_idx = 0;
    for (auto const& e : x) max_idx = std::max(max_idx, e.index);
    for (auto const& e : y) max_idx = std::max(max_idx, e.index);
    std::size_t needed = max_idx + 1;

    if (z.size() < needed)
        z.assign(needed, 0.0);
    else
        hpx::for_each(hpx::execution::par, z.begin(), z.end(), [](double& v) { v = 0.0; });

