    auto add_y = [&z](Element const& e) {
        std::atomic_ref<double> ref(z[e.index]);
        ref.fetch_add(e.value, std::memory_order_relaxed);
    };

    hpx::for_each(hpx::execution::par, x.begin(), x.end(), add_x);
    hpx::for_each(hpx::execution::par, y.begin(), y.end(), add_y);
}

