    using hpx::execution::par;

    // Determine required size
    auto max_index_in = [](std::vector<Element> const& v) {
        return v.empty()
            ? std::size_t{0}
            : hpx::transform_reduce(
                  par, v.begin(), v.end(), std::size_t{0},
                  hpx::max<std::size_t>(),
                  [](Element const& e) { return e.index; });
    };

    std::size_t max_idx = 0;
    if (!x.empty()) max_idx = std::max(max_idx, max_index_in(x));
    if (!y.empty()) max_idx = std::max(max_idx, max_index_in(y));

    // Resize and zero-initialize z
    std::size_t needed = max_idx + 1;
    if (z.size() != needed) {
        z.assign(needed, 0.0);
    } else {
        hpx::fill(par, z.begin(), z.end(), 0.0);
