    z.assign(max_index + 1, 0.0);

    hpx::for_each(hpx::execution::par, x.begin(), x.end(),
        [&](Element const& e) { z[e.index] += alpha * e.value; });

    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
        [&](Element const& e) { z[e.index] += e.value; });
}

