   Example:

   input: x=[{5, 12}, {8, 3}, {12, -1}], y=[{3, 1}, {5, -2}, {7, 1}, {8, -3}], alpha=1
   output: z=[0, 0, 0, 1, 0, 10, 0, 1, 0, 0, 0, 0, -1]
*/
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {

generated_output:
void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double>& z)
{
    if (x.empty() && y.empty()) {
        z.clear();
        return;
    }

    // Determine size of dense vector
    std::size_t max_idx = 0;
    if (!x.empty())
        max_idx = std::max(max_idx, std::max_element(x.begin(), x.end(),
                           [](auto const& a, auto const& b){ return a.index < b.index; })->index);
    if (!y.empty())
        max_idx = std::max(max_idx, std::max_element(y.begin(), y.end(),
                           [](auto const& a, auto const& b){ return a.index < b.index; })->index);

    z.assign(max_idx + 1, 0.0);

    // z += alpha * x
    hpx::for_each(hpx::execution::par, x.begin(), x.end(),
        [&](Element const& e){
            z[e.index] += alpha * e.value;
        });

    // z += y
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
        [&](Element const& e){
            z[e.index] += e.value;
        });
}

