generated_output:
void sparseAxpy(double alpha,
                std::vector<Element> const& x,
                std::vector<Element> const& y,
                std::vector<double>& z)
{
    // Determine required size for z
    std::size_t max_idx = 0;
    for (auto const& e : x) max_idx = std::max(max_idx, e.index);
    for (auto const& e : y) max_idx = std::max(max_idx, e.index);

    z.assign(max_idx + 1, 0.0);

    // Use atomic buffer to allow parallel accumulation with potential index collisions
    std::vector<std::atomic<double>> za(z.size());
    // Initialize atomics to zero
    hpx::for_each(hpx::execution::par, za.begin(), za.end(),
                  [](std::atomic<double>& a) { a.store(0.0, std::memory_order_relaxed); });

    // Accumulate alpha * x
    hpx::for_each(hpx::execution::par, x.begin(), x.end(),
                  [&](Element const& e) {
                      za[e.index].fetch_add(alpha * e.value, std::memory_order_relaxed);
                  });

    // Accumulate y
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
                  [&](Element const& e) {
                      za[e.index].fetch_add(e.value, std::memory_order_relaxed);
                  });

    // Copy back to dense vector
    hpx::for_each_n(hpx::execution::par, std::size_t{0}, za.size(),
                    [&](std::size_t i) {
                        z[i] = za[i].load(std::memory_order_relaxed);
                    });
}

