void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double>& z)
{
    // Determine required size
    std::size_t max_idx = 0;
    for (auto const& e : x) max_idx = std::max(max_idx, e.index);
    for (auto const& e : y) max_idx = std::max(max_idx, e.index);

    z.assign(max_idx + 1, 0.0);

    // Build combined list: alpha*x and y
    std::vector<Element> combined(x.size() + y.size());
    hpx::for_loop(hpx::execution::par, std::size_t(0), x.size(),
        [&](std::size_t i) { combined[i] = Element{x[i].index, alpha * x[i].value}; });
    hpx::for_loop(hpx::execution::par, std::size_t(0), y.size(),
        [&](std::size_t i) { combined[x.size() + i] = Element{y[i].index, y[i].value}; });

    // Sort by index in parallel
    hpx::sort(hpx::execution::par, combined.begin(), combined.end(),
              [](Element const& a, Element const& b) { return a.index < b.index; });

    // Reduce by key (sequential pass; small critical section vs. parallel sort)
    std::vector<Element> reduced;
    reduced.reserve(combined.size());
    std::size_t i = 0;
    while (i < combined.size()) {
        std::size_t idx = combined[i].index;
        double sum = 0.0;
        do { sum += combined[i].value; ++i; } while (i < combined.size() && combined[i].index == idx);
        reduced.push_back(Element{idx, sum});
    }

    // Scatter to dense vector in parallel (no races, unique indices)
    hpx::for_each(hpx::execution::par, reduced.begin(), reduced.end(),
                  [&](Element const& e) { z[e.index] = e.value; });
}

