void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    // Determine result size
    size_t max_idx = 0;
    for (auto const& e : x) max_idx = std::max(max_idx, e.index);
    for (auto const& e : y) max_idx = std::max(max_idx, e.index);
    size_t n = (x.empty() && y.empty()) ? 0 : (max_idx + 1);

    z.assign(n, 0.0);
    if (n == 0) return;

    // Temporary dense buffers to avoid write races
    std::vector<double> zx(n, 0.0), zy(n, 0.0);

    hpx::ranges::for_each(hpx::execution::par, x,
        [&](Element const& e) { zx[e.index] = alpha * e.value; });

    hpx::ranges::for_each(hpx::execution::par, y,
        [&](Element const& e) { zy[e.index] = e.value; });

    hpx::ranges::transform(hpx::execution::par, zx, zy, z.begin(), std::plus<double>{});
}

