void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    // Determine required size
    std::size_t max_idx = 0;
    auto upd_max = [&max_idx](std::vector<Element> const& v) {
        for (auto const& e : v) max_idx = std::max(max_idx, e.index);
    };
    if (!x.empty()) upd_max(x);
    if (!y.empty()) upd_max(y);
    std::size_t n = (x.empty() && y.empty()) ? 0 : (max_idx + 1);

    // Prepare accumulator of atomics to avoid races
    std::vector<std::atomic<double>> acc(n);
    for (std::size_t i = 0; i < n; ++i) acc[i].store(0.0, std::memory_order_relaxed);

    // Parallel add y
    hpx::for_each(hpx::execution::par, y.begin(), y.end(),
        [&acc](Element const& e) {
            acc[e.index].fetch_add(e.value, std::memory_order_relaxed);
        });

    // Parallel add alpha * x
    hpx::for_each(hpx::execution::par, x.begin(), x.end(),
        [alpha, &acc](Element const& e) {
            acc[e.index].fetch_add(alpha * e.value, std::memory_order_relaxed);
        });

    // Write back to dense vector
    z.resize(n);
    hpx::for_each(hpx::execution::par, std::size_t(0), n,
        [&acc, &z](std::size_t i) {
            z[i] = acc[i].load(std::memory_order_relaxed);
        });
}

