#include <hpx/hpx_main.hpp>

struct COOElement {
   size_t row, column;
   double value;
};

/* Factorize the sparse matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   A is a sparse NxN matrix stored in COO format.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,4}, {0,1,3}, {1,0,6}, {1,1,3}]
   output: L=[{0,0,1},{1,0,1.5}, {1,1,1}] U=[{0,0,4}, {0,1,3}, {1,1,-1.5}]
*/
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    // Dense copy of A
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        M[idx(e.row, e.column)] = e.value;
    }

    // Prepare L (identity) and U (zeros)
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[idx(i, i)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j >= k
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) {
                sum += L[idx(k, s)] * U[idx(s, j)];
            }
            U[idx(k, j)] = M[idx(k, j)] - sum;
        });

        // Ensure U[k,k] is ready and non-zero (no pivoting)
        double pivot = U[idx(k, k)];
        if (pivot == 0.0) {
            throw std::runtime_error("Zero pivot encountered; no pivoting implemented.");
        }

        // Compute L[i, k] for i > k
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) {
                sum += L[idx(i, s)] * U[idx(s, k)];
            }
            L[idx(i, k)] = (M[idx(i, k)] - sum) / U[idx(k, k)];
        });
    }
}

