void luFactorize(std::vector<COOElement> const& Acoo,
                 std::vector<double> &L,
                 std::vector<double> &U,
                 std::size_t N)
{
    // Dense buffers
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        A[idx(e.row, e.column, N)] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    for (std::size_t k = 0; k < N; ++k) {
        // U[k, j] for j = k..N-1 (row k of U)
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p) {
                sum += L[idx(k, p, N)] * U[idx(p, j, N)];
            }
            U[idx(k, j, N)] = A[idx(k, j, N)] - sum;
        });

        double Ukk = U[idx(k, k, N)];
        if (Ukk == 0.0) throw std::runtime_error("Zero pivot encountered (no pivoting implemented)");

        // Set L[k,k] = 1
        L[idx(k, k, N)] = 1.0;

        // L[i, k] for i = k+1..N-1 (column k of L)
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p) {
                sum += L[idx(i, p, N)] * U[idx(p, k, N)];
            }
            L[idx(i, k, N)] = (A[idx(i, k, N)] - sum) == 0.0 ? 0.0 : (A[idx(i, k, N)] - sum) / Ukk;
        });
    }
}

