/* Factorize the sparse matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   A is a sparse NxN matrix stored in COO format.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,4}, {0,1,3}, {1,0,6}, {1,1,3}]
   output: L=[{0,0,1},{1,0,1.5}, {1,1,1}] U=[{0,0,4}, {0,1,3}, {1,1,-1.5}]
*/
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 std::size_t N)
{
    // Dense work buffers
    std::vector<double> Ad(N * N, 0.0), Ld(N * N, 0.0), Ud(N * N, 0.0);
    auto idx = [N](std::size_t i, std::size_t j) { return i * N + j; };

    for (auto const& e : A) {
        Ad[idx(e.row, e.column)] = e.value;
    }

    // LU factorization without pivoting
    for (std::size_t k = 0; k < N; ++k) {
        // U(k,k)
        double sumkk = 0.0;
        for (std::size_t p = 0; p < k; ++p)
            sumkk += Ld[idx(k, p)] * Ud[idx(p, k)];
        Ud[idx(k, k)] = Ad[idx(k, k)] - sumkk;

        // U(k, j), j = k+1..N-1
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](std::size_t j) {
            double s = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                s += Ld[idx(k, p)] * Ud[idx(p, j)];
            Ud[idx(k, j)] = Ad[idx(k, j)] - s;
        });

        // L(k,k) = 1
        Ld[idx(k, k)] = 1.0;

        // L(i, k), i = k+1..N-1
        double Ukk = Ud[idx(k, k)];
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](std::size_t i) {
            double s = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                s += Ld[idx(i, p)] * Ud[idx(p, k)];
            Ld[idx(i, k)] = (Ad[idx(i, k)] - s) / Ukk;
        });
    }

    // Compress to COO (skip near-zeros)
    L.clear();
    U.clear();
    L.reserve(N + N * 2);
    U.reserve(N + N * 2);
    const double eps = 1e-12;

    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j <= i; ++j) { // L is lower, incl diag
            double v = Ld[idx(i, j)];
            if (std::fabs(v) > eps) L.push_back({i, j, v});
        }
        for (std::size_t j = i; j < N; ++j) { // U is upper, incl diag
            double v = Ud[idx(i, j)];
            if (std::fabs(v) > eps) U.push_back({i, j, v});
        }
    }
}

