void luFactorize(std::vector<COOElement> const& Acoo, std::vector<double>& L, std::vector<double>& U, std::size_t N) {
    // Prepare dense A
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        A[e.row * N + e.column] = e.value;
    }

    // Initialize L (unit diagonal) and U
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (std::size_t i = 0; i < N; ++i) M(L, N, i, i) = 1.0;

    for (std::size_t k = 0; k < N; ++k) {
        std::vector<hpx::future<void>> futs;
        futs.reserve((N - k) + (N - (k + 1)));

        // Compute U[k, j] for j = k..N-1 in parallel
        for (std::size_t j = k; j < N; ++j) {
            futs.push_back(hpx::async([&, k, j] {
                double sum = 0.0;
                for (std::size_t p = 0; p < k; ++p) {
                    sum += Mconst(L, N, k, p) * Mconst(U, N, p, j);
                }
                M(U, N, k, j) = Mconst(A, N, k, j) - sum;
            }));
        }

        hpx::wait_all(futs);
        futs.clear();

        // Pivot check
        double pivot = Mconst(U, N, k, k);
        if (pivot == 0.0) throw std::runtime_error("Zero pivot encountered; pivoting not implemented.");

        // Compute L[i, k] for i = k+1..N-1 in parallel
        for (std::size_t i = k + 1; i < N; ++i) {
            futs.push_back(hpx::async([&, k, i, pivot] {
                double sum = 0.0;
                for (std::size_t p = 0; p < k; ++p) {
                    sum += Mconst(L, N, i, p) * Mconst(U, N, p, k);
                }
                M(L, N, i, k) = (Mconst(A, N, i, k) - sum) / pivot;
            }));
        }

        hpx::wait_all(futs);
    }
}

