generated_output:
void luFactorize(std::vector<COOElement> const& Acoo,
                 std::vector<double> &L,
                 std::vector<double> &U,
                 std::size_t N)
{
    // Dense copy of A
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo)
        A[idx(e.row, e.column, N)] = e.value;

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    // Set L diagonal to 1
    for (std::size_t i = 0; i < N; ++i)
        L[idx(i, i, N)] = 1.0;

    for (std::size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j=k..N-1 in parallel
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += L[idx(k, p, N)] * U[idx(p, j, N)];
            U[idx(k, j, N)] = A[idx(k, j, N)] - sum;
        });

        double pivot = U[idx(k, k, N)];
        if (std::abs(pivot) < 1e-12)
            throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented).");

        // Compute L[i, k] for i=k+1..N-1 in parallel (L[k,k] is 1 already)
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += L[idx(i, p, N)] * U[idx(p, k, N)];
            L[idx(i, k, N)] = (A[idx(i, k, N)] - sum) / pivot;
        });
    }
}

