    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) {
        Ad[idx(e.row, e.column)] = e.value;
    }

    // Initialize L as identity and U as zero
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) { L[idx(i, i)] = 1.0; });

