generated_output:
void luFactorize(std::vector<COOElement> const& Acoo,
                 std::vector<COOElement> &Lcoo,
                 std::vector<COOElement> &Ucoo,
                 size_t N)
{
    using hpx::for_loop;
    using hpx::execution::par;

    // Dense workspace
    std::vector<double> A(N * N, 0.0), L(N * N, 0.0), U(N * N, 0.0);

    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    // Build dense A from COO
    for (auto const& e : Acoo) {
        A[idx(e.row, e.column)] = e.value;
    }

    // Set L diagonal to 1
    for (size_t i = 0; i < N; ++i) L[idx(i, i)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U row k (j = k..N-1)
        for_loop(par, k, N, [&](size_t j) {
            U[idx(k, j)] = A[idx(k, j)];
        });

        double pivot = U[idx(k, k)];
        if (std::abs(pivot) == 0.0)
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");

        // Compute L column k (i = k+1..N-1)
        for_loop(par, k + 1, N, [&](size_t i) {
            L[idx(i, k)] = A[idx(i, k)] / pivot;
        });

        // Schur update of trailing submatrix: A(i,j) -= L(i,k) * U(k,j)
        for_loop(par, k + 1, N, [&](size_t i) {
            double Lik = L[idx(i, k)];
            for (size_t j = k + 1; j < N; ++j) {
                A[idx(i, j)] -= Lik * U[idx(k, j)];
            }
        });
    }

    // Convert dense L, U to COO (sparse) form
    Lcoo.clear(); Ucoo.clear();
    Lcoo.reserve(N + N * 4); // heuristic
    Ucoo.reserve(N + N * 4);

    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j <= i; ++j) {
            double v = L[idx(i, j)];
            if (v != 0.0) Lcoo.push_back({i, j, v});
        }
        for (size_t j = i; j < N; ++j) {
            double v = U[idx(i, j)];
            if (v != 0.0) Ucoo.push_back({i, j, v});
        }
    }
}

