generated_output:
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[i * N + i] = 1.0;

    std::unordered_map<size_t, double> a_map;
    a_map.reserve(A.size());
    for (auto const& e : A) a_map[e.row * N + e.column] = e.value;

    constexpr double eps = 1e-14;

    for (size_t k = 0; k < N; ++k) {
        // U row k
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) sum += L[k * N + p] * U[p * N + j];
            double a_kj = 0.0;
            auto it = a_map.find(k * N + j);
            if (it != a_map.end()) a_kj = it->second;
            U[k * N + j] = a_kj - sum;
        });

        if (std::abs(U[k * N + k]) < eps) throw std::runtime_error("Zero pivot encountered (no pivoting).");

        // L column k
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) sum += L[i * N + p] * U[p * N + k];
            double a_ik = 0.0;
            auto it = a_map.find(i * N + k);
            if (it != a_map.end()) a_ik = it->second;
            L[i * N + k] = (a_ik - sum) / U[k * N + k];
        });
    }
}

