void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 size_t N)
{
    // Build dense matrix from COO
    std::vector<double> M(N * N, 0.0);
    auto idx = [N](size_t r, size_t c) { return r * N + c; };
    for (auto const& e : A) {
        M[idx(e.row, e.column)] = e.value;
    }

    // Allocate dense L and U (L with unit diagonal)
    std::vector<double> Ld(N * N, 0.0), Ud(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) Ld[idx(i, i)] = 1.0;

    // Doolittle LU (no pivoting)
    for (size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j = k..N-1 (in parallel)
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) {
                sum += Ld[idx(k, s)] * Ud[idx(s, j)];
            }
            Ud[idx(k, j)] = M[idx(k, j)] - sum;
        });

        double pivot = Ud[idx(k, k)];
        // Optional: handle near-zero pivot (no pivoting here)
        // if (std::abs(pivot) < 1e-14) throw std::runtime_error("Zero pivot encountered");

        // Compute L[i, k] for i = k+1..N-1 (in parallel)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) {
                sum += Ld[idx(i, s)] * Ud[idx(s, k)];
            }
            Ld[idx(i, k)] = (M[idx(i, k)] - sum) / pivot;
        });

        // Update trailing submatrix M[i, j] = A - L*U partial products (optional optimization)
        // Not required for Doolittle if we always recompute sums; keeping M unchanged here.
    }

    // Convert dense L and U to COO, skipping zeros (keep L unit diagonal)
    L.clear(); U.clear();
    L.reserve(N + N); // rough
    U.reserve(N + N);

    const double eps = 0.0; // set to small threshold if you want to prune near-zeros
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            double lv = Ld[idx(i, j)];
            double uv = Ud[idx(i, j)];
            if (std::abs(lv) > eps) L.push_back({i, j, lv});
            if (std::abs(uv) > eps) U.push_back({i, j, uv});
        }
    }
}

