void luFactorize(std::vector<COOElement> const& A, std::vector<double>& L, std::vector<double>& U, size_t N) {
    // Build dense A from COO
    std::vector<double> dense(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of bounds");
        dense[idx(e.row, e.column, N)] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // U[k, j] for j = k..N-1
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s)
                sum += L[idx(k, s, N)] * U[idx(s, j, N)];
            U[idx(k, j, N)] = dense[idx(k, j, N)] - sum;
        });

        double pivot = U[idx(k, k, N)];
        if (std::abs(pivot) < 1e-12) throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting)");

        L[idx(k, k, N)] = 1.0;

        // L[i, k] for i = k+1..N-1
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s)
                sum += L[idx(i, s, N)] * U[idx(s, k, N)];
            L[idx(i, k, N)] = (dense[idx(i, k, N)] - sum) / pivot;
        });
    }
}

