*/
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 std::size_t N)
{
    const double eps = 1e-12;

    // Dense storage
    std::vector<double> a(N * N, 0.0), Ld(N * N, 0.0), Ud(N * N, 0.0);
    auto idx = [N](std::size_t r, std::size_t c) { return r * N + c; };

    // Build dense A
    for (auto const& e : A) {
        a[idx(e.row, e.column)] = e.value;
    }

    // Unit diagonal for L
    for (std::size_t i = 0; i < N; ++i) Ld[idx(i, i)] = 1.0;

    for (std::size_t k = 0; k < N; ++k) {
        // U row k, columns j = k..N-1 (parallel)
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double s = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                s += Ld[idx(k, p)] * Ud[idx(p, j)];
            Ud[idx(k, j)] = a[idx(k, j)] - s;
        });

        // Pivot check
        double pivot = Ud[idx(k, k)];
        if (std::abs(pivot) < eps)
            throw std::runtime_error("Zero (or near-zero) pivot encountered in LU.");

        // L column k, rows i = k+1..N-1 (parallel)
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double s = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                s += Ld[idx(i, p)] * Ud[idx(p, k)];
            Ld[idx(i, k)] = (a[idx(i, k)] - s) / Ud[idx(k, k)];
        });
    }

    // Convert dense L, U to COO (sparse)
    L.clear(); U.clear();
    L.reserve(N + N * 2); // rough guess
    U.reserve(N + N * 2);

    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j < N; ++j) {
            double lv = Ld[idx(i, j)];
            if (std::abs(lv) > eps) L.push_back({i, j, lv});
            double uv = Ud[idx(i, j)];
            if (std::abs(uv) > eps) U.push_back({i, j, uv});
        }
    }
}

