void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement> &L,
                 std::vector<COOElement> &U,
                 size_t N)
{
    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    std::vector<double> Ad(N * N, 0.0), Ld(N * N, 0.0), Ud(N * N, 0.0);

    // Build dense A from COO
    for (auto const& e : A) {
        Ad[idx(e.row, e.column)] = e.value;
    }
    // Initialize L with unit diagonal
    for (size_t i = 0; i < N; ++i) Ld[idx(i, i)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U row k in parallel: j = k..N-1
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t m = 0; m < k; ++m)
                sum += Ld[idx(k, m)] * Ud[idx(m, j)];
            Ud[idx(k, j)] = Ad[idx(k, j)] - sum;
        });

        double pivot = Ud[idx(k, k)];
        if (std::abs(pivot) < 1e-14)
            throw std::runtime_error("Zero or tiny pivot encountered (no pivoting implemented).");

        // Compute L column k in parallel: i = k+1..N-1
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t m = 0; m < k; ++m)
                sum += Ld[idx(i, m)] * Ud[idx(m, k)];
            Ld[idx(i, k)] = (Ad[idx(i, k)] - sum) / pivot;
        });
    }

    // Convert dense L and U to COO with threshold
    const double eps = 1e-12;
    L.clear(); U.clear(); L.reserve(N + A.size()); U.reserve(A.size());

    for (size_t i = 0; i < N; ++i) {
        // L lower (including diagonal)
        for (size_t j = 0; j <= i; ++j) {
            double v = Ld[idx(i, j)];
            if (std::abs(v) > eps)
                L.push_back({i, j, v});
        }
        // U upper
        for (size_t j = i; j < N; ++j) {
            double v = Ud[idx(i, j)];
            if (std::abs(v) > eps)
                U.push_back({i, j, v});
        }
    }
}

