generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<double>& L,
                 std::vector<double>& U,
                 size_t N)
{
    const double eps = 1e-12;

    // Dense working copy of A (row-major)
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        M[e.row * N + e.column] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // U row k: U[k, j] = M[k, j] for j >= k
        hpx::for_loop(hpx::execution::par, k, N,
            [&](size_t j) { U[k * N + j] = M[k * N + j]; });

        double pivot = U[k * N + k];
        if (std::abs(pivot) < eps) {
            throw std::runtime_error("Zero or near-zero pivot encountered in LU factorization");
        }

        // L diagonal is 1
        L[k * N + k] = 1.0;

        // L column k: L[i, k] = M[i, k] / pivot for i > k
        hpx::for_loop(hpx::execution::par, k + 1, N,
            [&](size_t i) { L[i * N + k] = M[i * N + k] / pivot; });

        // Update trailing submatrix: M[i, j] -= L[i,k] * U[k,j] for i>k, j>k
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double lik = L[i * N + k];
            for (size_t j = k + 1; j < N; ++j) {
                M[i * N + j] -= lik * U[k * N + j];
            }
            M[i * N + k] = 0.0; // maintain structural zero below pivot in M
        });
    }
}

