void luFactorize(std::vector<COOElement> const& A,
                 std::vector<double> &L,
                 std::vector<double> &U,
                 size_t N)
{
    // Dense workspace from COO (accumulate duplicates)
    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) {
        Ad[e.row * N + e.column] += e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[i * N + i] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // U(k,k)
        double sum = 0.0;
        for (size_t p = 0; p < k; ++p)
            sum += L[k * N + p] * U[p * N + k];
        U[k * N + k] = Ad[k * N + k] - sum;

        if (std::abs(U[k * N + k]) == 0.0)
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");

        // U(k, j) for j > k
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t j) {
            double s = 0.0;
            for (size_t p = 0; p < k; ++p)
                s += L[k * N + p] * U[p * N + j];
            U[k * N + j] = Ad[k * N + j] - s;
        });

        // L(i, k) for i >= k (keep L(k,k)=1)
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t i) {
            if (i == k) { L[k * N + k] = 1.0; return; }
            double s = 0.0;
            for (size_t p = 0; p < k; ++p)
                s += L[i * N + p] * U[p * N + k];
            L[i * N + k] = (Ad[i * N + k] - s) / U[k * N + k];
        });
    }
}

