/* Factorize the sparse matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   A is a sparse NxN matrix stored in COO format.
   Use HPX to compute in parallel. Assume HPX has already been initialized.
   Example:

   input: A=[{0,0,4}, {0,1,3}, {1,0,6}, {1,1,3}]
   output: L=[{0,0,1},{1,0,1.5}, {1,1,1}] U=[{0,0,4}, {0,1,3}, {1,1,-1.5}]
*/
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 std::size_t N)
{
    // Dense workspaces
    std::vector<double> M(N * N, 0.0);
    std::vector<double> Ld(N * N, 0.0);
    std::vector<double> Ud(N * N, 0.0);

    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        at(M, N, e.row, e.column) = e.value;
    }

    // Doolittle: L has unit diagonal
    for (std::size_t k = 0; k < N; ++k) {
        at(Ld, N, k, k) = 1.0;

        // Compute U row k: j = k..N-1 in parallel
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += atc(Ld, N, k, p) * atc(Ud, N, p, j);
            at(Ud, N, k, j) = atc(M, N, k, j) - sum;
        });

        double pivot = atc(Ud, N, k, k);
        if (std::abs(pivot) == 0.0)
            throw std::runtime_error("Singular matrix: zero pivot encountered");

        // Compute L column k: i = k+1..N-1 in parallel
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += atc(Ld, N, i, p) * atc(Ud, N, p, k);
            at(Ld, N, i, k) = (atc(M, N, i, k) - sum) / pivot;
        });
    }

    // Convert dense L and U to sparse COO with tolerance
    auto to_coo = [&](std::vector<double> const& D, std::vector<COOElement>& C) {
        C.clear();
        C.reserve(N * 3); // heuristic
        constexpr double eps = 1e-12;
        for (std::size_t i = 0; i < N; ++i) {
            for (std::size_t j = 0; j < N; ++j) {
                double v = atc(D, N, i, j);
                if (std::abs(v) > eps)
                    C.push_back({i, j, v});
            }
        }
    };

    to_coo(Ld, L);
    to_coo(Ud, U);
}

