generated_output:
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
    // Dense (row-major) storage for L and U
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    // Build dense A from COO
    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) {
        Ad[idx(e.row, e.column)] = e.value;
    }

    // Set L diagonal to 1
    for (size_t i = 0; i < N; ++i) L[idx(i, i)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j >= k in parallel
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) {
                sum += L[idx(k, s)] * U[idx(s, j)];
            }
            U[idx(k, j)] = Ad[idx(k, j)] - sum;
        });

        // Check pivot
        double pivot = U[idx(k, k)];
        if (std::abs(pivot) < 1e-14) {
            throw std::runtime_error("Zero or near-zero pivot encountered; pivoting required.");
        }

        // Compute L[i, k] for i > k in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) {
                sum += L[idx(i, s)] * U[idx(s, k)];
            }
            L[idx(i, k)] = (Ad[idx(i, k)] - sum) / pivot;
        });
    }
}

