void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 size_t N)
{
    // dense A
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of bounds");
        M[idx(e.row, e.column, N)] = e.value;
    }

    for (size_t k = 0; k < N; ++k) {
        double pivot = M[idx(k, k, N)];
        if (pivot == 0.0) throw std::runtime_error("Zero pivot encountered; no pivoting implemented");

        // Compute multipliers for column k (rows k+1..N-1)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            M[idx(i, k, N)] /= pivot;
        });

        // Schur complement update: for each i>k, j>k: M[i,j] -= M[i,k]*M[k,j]
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double lik = M[idx(i, k, N)];
            double const* rowK = &M[idx(k, 0, N)];
            double* rowI = &M[idx(i, 0, N)];
            for (size_t j = k + 1; j < N; ++j) {
                rowI[j] -= lik * rowK[j];
            }
        });
    }

    // Build L (unit diagonal) and U from M, and convert to COO
    L.clear(); U.clear();
    L.reserve(N * 2); U.reserve(N * 2); // rough guess

    for (size_t i = 0; i < N; ++i) {
        // L diagonal 1
        L.push_back({i, i, 1.0});
        for (size_t j = 0; j < i; ++j) {
            double v = M[idx(i, j, N)];
            if (v != 0.0) L.push_back({i, j, v});
        }
        for (size_t j = i; j < N; ++j) {
            double v = M[idx(i, j, N)];
            if (v != 0.0) U.push_back({i, j, v});
        }
    }
}

