{
    // Dense A
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo)
        A[e.row * N + e.column] = e.value;

    // Resize/initialize L (identity) and U (zeros)
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[i * N + i] = 1.0;

