*/
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& Acoo, std::vector<double> &L, std::vector<double> &U, size_t N) {
    // Dense storage (row-major) for computation
    std::vector<double> A(N * N, 0.0);
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    // Build dense A from COO
    for (auto const& e : Acoo) {
        A[idx(e.row, e.column)] = e.value;
    }

    for (size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j = k..N-1 in parallel
        std::vector<hpx::future<void>> fu;
        fu.reserve(N - k);
        for (size_t j = k; j < N; ++j) {
            fu.push_back(hpx::async([&, k, j]() {
                double sum = 0.0;
                for (size_t s = 0; s < k; ++s) {
                    sum += L[idx(k, s)] * U[idx(s, j)];
                }
                U[idx(k, j)] = A[idx(k, j)] - sum;
            }));
        }
        hpx::wait_all(fu);

        // Check pivot
        double pivot = U[idx(k, k)];
        if (pivot == 0.0) {
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");
        }

        // Set unit diagonal for L
        L[idx(k, k)] = 1.0;

        // Compute L[i, k] for i = k+1..N-1 in parallel
        std::vector<hpx::future<void>> fl;
        fl.reserve(N - k - 1);
        for (size_t i = k + 1; i < N; ++i) {
            fl.push_back(hpx::async([&, i, k, pivot]() {
                double sum = 0.0;
                for (size_t s = 0; s < k; ++s) {
                    sum += L[idx(i, s)] * U[idx(s, k)];
                }
                L[idx(i, k)] = (A[idx(i, k)] - sum) / pivot;
            }));
        }
        hpx::wait_all(fl);
    }
}

