void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 size_t N)
{
    // Build dense A
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        M[e.row * N + e.column] = e.value;
    }

    std::vector<double> Ld(N * N, 0.0);
    std::vector<double> Ud(N * N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // U[k, j] for j >= k
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s)
                sum += at_c(Ld, N, k, s) * at_c(Ud, N, s, j);
            at(Ud, N, k, j) = at_c(M, N, k, j) - sum;
        });

        double piv = at_c(Ud, N, k, k);
        if (std::abs(piv) == 0.0) {
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");
        }

