        at(Ld, N, k, k) = 1.0;
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s)
                sum += at_c(Ld, N, i, s) * at_c(Ud, N, s, k);
            at(Ld, N, i, k) = (at_c(M, N, i, k) - sum) / piv;
