        // Not required for L and U computation since we always read from M and partial L/U.
    }

    // Convert to COO (skip zeros)
    L.clear(); U.clear();
    L.reserve(N + N * 4); // heuristic
    U.reserve(N + N * 4);

    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j <= std::min(i, N - 1); ++j) {
            double v = at_c(Ld, N, i, j);
