generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 std::size_t N)
{
    const double eps = 1e-12;

    // Dense storage
    std::vector<double> a(N * N, 0.0);
    std::vector<double> Ld(N * N, 0.0);
    std::vector<double> Ud(N * N, 0.0);

    auto idx = [N](std::size_t r, std::size_t c) { return r * N + c; };

    // Fill dense A
    for (auto const& e : A)
        a[idx(e.row, e.column)] = e.value;

    // Initialize L as identity
    for (std::size_t i = 0; i < N; ++i)
        Ld[idx(i, i)] = 1.0;

    // Doolittle LU without pivoting
    for (std::size_t k = 0; k < N; ++k) {
        // U row k, columns j >= k
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += Ld[idx(k, p)] * Ud[idx(p, j)];
            Ud[idx(k, j)] = a[idx(k, j)] - sum;
        });

        // Pivot check
        double piv = Ud[idx(k, k)];
        if (std::abs(piv) < eps)
            throw std::runtime_error("Zero (or near-zero) pivot encountered; pivoting required.");

        // L column k, rows i > k
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += Ld[idx(i, p)] * Ud[idx(p, k)];
            Ld[idx(i, k)] = (a[idx(i, k)] - sum) / piv;
        });
    }

    // Convert back to COO
    L.clear(); U.clear();
    L.reserve(N + A.size()); // rough guess
    U.reserve(A.size());

    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j < N; ++j) {
            double lv = Ld[idx(i, j)];
            if (std::abs(lv) > eps)
                L.push_back({i, j, lv});
        }
    }
    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j < N; ++j) {
            double uv = Ud[idx(i, j)];
            if (std::abs(uv) > eps)
                U.push_back({i, j, uv});
        }
    }
}

