void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 std::size_t N)
{
    auto idx = [N](std::size_t i, std::size_t j) { return i * N + j; };

    std::vector<double> M(N * N, 0.0), Ld(N * N, 0.0), Ud(N * N, 0.0);

    for (auto const& e : A) M[idx(e.row, e.column)] = e.value;

    for (std::size_t k = 0; k < N; ++k) {
        // Compute U row k in parallel: j = k..N-1
        hpx::for_loop(hpx::execution::par, k, N, [&](std::size_t j) {
            double s = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                s += Ld[idx(k, p)] * Ud[idx(p, j)];
            Ud[idx(k, j)] = M[idx(k, j)] - s;
        });

        double pivot = Ud[idx(k, k)];
        if (std::abs(pivot) < 1e-14)
            throw std::runtime_error("Zero (or near-zero) pivot encountered; pivoting not implemented.");

        // Set L diagonal
        Ld[idx(k, k)] = 1.0;

        // Compute L column k in parallel: i = k+1..N-1
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](std::size_t i) {
            double s = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                s += Ld[idx(i, p)] * Ud[idx(p, k)];
            Ld[idx(i, k)] = (M[idx(i, k)] - s) / pivot;
        });
    }

    // Compress to COO
    L.clear(); U.clear();
    L.reserve(N + N * 2); // rough guess
    U.reserve(N + N * 2);

    const double tol = 0.0; // change if you want to drop tiny fill-in
    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j <= i; ++j) {
            double v = Ld[idx(i, j)];
            if (std::abs(v) > tol) L.push_back({i, j, v});
        }
        for (std::size_t j = i; j < N; ++j) {
            double v = Ud[idx(i, j)];
            if (std::abs(v) > tol) U.push_back({i, j, v});
        }
    }
}

