void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<double>& L,
                 std::vector<double>& U,
                 size_t N)
{
    // Build sparse lookup for A
    std::unordered_map<size_t, double> Amap;
    Amap.reserve(A.size() * 2);
    for (auto const& e : A) {
        Amap[idx(e.row, e.column, N)] += e.value; // accumulate duplicates
    }
    auto Aat = [&](size_t i, size_t j) -> double {
        auto it = Amap.find(idx(i, j, N));
        return it == Amap.end() ? 0.0 : it->second;
    };

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[idx(i, i, N)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j >= k in parallel
        std::vector<hpx::future<void>> fu;
        fu.reserve(N - k);
        for (size_t j = k; j < N; ++j) {
            fu.push_back(hpx::async([&, k, j] {
                double sum = 0.0;
                for (size_t s = 0; s < k; ++s) {
                    sum += L[idx(k, s, N)] * U[idx(s, j, N)];
                }
                U[idx(k, j, N)] = Aat(k, j) - sum;
            }));
        }
        hpx::when_all(fu).wait();

        double pivot = U[idx(k, k, N)];
        if (std::abs(pivot) < 1e-14) {
            throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented).");
        }

        // Compute L[i, k] for i > k in parallel
        std::vector<hpx::future<void>> fl;
        fl.reserve(N - k - 1);
        for (size_t i = k + 1; i < N; ++i) {
            fl.push_back(hpx::async([&, k, i, pivot] {
                double sum = 0.0;
                for (size_t s = 0; s < k; ++s) {
                    sum += L[idx(i, s, N)] * U[idx(s, k, N)];
                }
                L[idx(i, k, N)] = (Aat(i, k) - sum) / pivot;
            }));
        }
        hpx::when_all(fl).wait();
    }
}

