void luFactorize(std::vector<COOElement> const& A,
                 std::vector<double> &L,
                 std::vector<double> &U,
                 std::size_t N)
{
    const double eps = 1e-14;

    // Dense copy of A
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) {
            throw std::out_of_range("COO element index out of range");
        }
        M[idx(e.row, e.column, N)] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    // Set unit diagonal for L
    hpx::for_loop(hpx::execution::par, std::size_t(0), N, [&](std::size_t i) {
        L[idx(i, i, N)] = 1.0;
    });

    for (std::size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j >= k (row k of U)
        auto futU = hpx::async([&, k] {
            hpx::for_loop(hpx::execution::par, k, N, [&](std::size_t j) {
                double sum = 0.0;
                for (std::size_t p = 0; p < k; ++p) {
                    sum += L[idx(k, p, N)] * U[idx(p, j, N)];
                }
                U[idx(k, j, N)] = M[idx(k, j, N)] - sum;
            });
        });
        futU.wait();

        // Pivot check
        double pivot = U[idx(k, k, N)];
        if (std::abs(pivot) < eps) {
            throw std::runtime_error("Zero or near-zero pivot encountered");
        }

        // Compute L[i, k] for i > k (column k of L)
        auto futL = hpx::async([&, k, pivot] {
            hpx::for_loop(hpx::execution::par, k + 1, N, [&](std::size_t i) {
                double sum = 0.0;
                for (std::size_t p = 0; p < k; ++p) {
                    sum += L[idx(i, p, N)] * U[idx(p, k, N)];
                }
                L[idx(i, k, N)] = (M[idx(i, k, N)] - sum) * (1.0 / pivot);
            });
        });
        futL.wait();
    }
}

