generated_output:
void luFactorize(std::vector<COOElement> const& Acoo,
                 std::vector<COOElement>& Lcoo,
                 std::vector<COOElement>& Ucoo,
                 std::size_t N)
{
    const double eps = 1e-12;

    // Dense work buffers
    std::vector<double> A(N * N, 0.0);
    std::vector<double> L(N * N, 0.0);
    std::vector<double> U(N * N, 0.0);

    // Build dense A from COO
    for (auto const& e : Acoo) {
        if (e.row >= N || e.column >= N)
            throw std::out_of_range("COO index out of range");
        A[e.row * N + e.column] = e.value;
    }

    // Unit diagonal for L
    for (std::size_t i = 0; i < N; ++i) L[i * N + i] = 1.0;

    for (std::size_t k = 0; k < N; ++k) {
        // U(k, j) for j >= k
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t s = 0; s < k; ++s)
                sum += L[k * N + s] * U[s * N + j];
            U[k * N + j] = A[k * N + j] - sum;
        });

        double pivot = U[k * N + k];
        if (std::abs(pivot) < eps)
            throw std::runtime_error("Singular matrix or zero pivot encountered");

        // L(i, k) for i > k
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t s = 0; s < k; ++s)
                sum += L[i * N + s] * U[s * N + k];
            L[i * N + k] = (A[i * N + k] - sum) / pivot;
        });
    }

    // Convert to COO, keeping sparsity (with tolerance)
    Lcoo.clear();
    Ucoo.clear();
    Lcoo.reserve(N * 2);  // rough guess
    Ucoo.reserve(N * 2);

    for (std::size_t i = 0; i < N; ++i) {
        // L: lower-triangular with unit diagonal
        for (std::size_t j = 0; j <= i; ++j) {
            double v = (i == j) ? 1.0 : L[i * N + j];
            if (std::abs(v) > eps)
                Lcoo.push_back({i, j, v});
        }
        // U: upper-triangular
        for (std::size_t j = i; j < N; ++j) {
            double v = U[i * N + j];
            if (std::abs(v) > eps)
                Ucoo.push_back({i, j, v});
        }
    }
}

