void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 size_t N)
{
    const double eps = 1e-12;

    // Dense workspace
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N)
            throw std::out_of_range("COO element index out of range");
        M[idx(e.row, e.column, N)] = e.value;
    }

    // Doolittle (no pivoting)
    for (size_t k = 0; k < N; ++k) {
        double piv = M[idx(k, k, N)];
        if (std::abs(piv) < eps)
            throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented)");

        // Compute L column k below diagonal: M(i,k) = M(i,k)/U(k,k)
