            double lik = M[idx(i, k, N)];
            double const* Urowk = &M[idx(k, 0, N)];
            double* rowi = &M[idx(i, 0, N)];
            for (size_t j = k + 1; j < N; ++j) {
                rowi[j] -= lik * Urowk[j];
            }
        });
    }

    // Extract L (unit diagonal) and U to COO
    L.clear(); U.clear();
    L.reserve(N * 2); // rough
    U.reserve(N * 2);

    for (size_t i = 0; i < N; ++i) {
        L.push_back({i, i, 1.0});
        for (size_t j = 0; j < i; ++j) {
            double v = M[idx(i, j, N)];
            if (std::abs(v) > eps) L.push_back({i, j, v});
        }
        for (size_t j = i; j < N; ++j) {
            double v = M[idx(i, j, N)];
            if (std::abs(v) > eps) U.push_back({i, j, v});
        }
    }
}

