void luFactorize(std::vector<COOElement> const& A,
                 std::vector<double>& L,
                 std::vector<double>& U,
                 size_t N)
{
    auto idx = [N](size_t r, size_t c) { return r * N + c; };

    // Dense workspace for A
    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        Ad[idx(e.row, e.column)] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[idx(i, i)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // U[k, j] for j = k..N-1
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += L[idx(k, p)] * U[idx(p, j)];
            U[idx(k, j)] = Ad[idx(k, j)] - sum;
        });

        double pivot = U[idx(k, k)];
        if (std::abs(pivot) < 1e-12)
            throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented)");

        // L[i, k] for i = k+1..N-1
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += L[idx(i, p)] * U[idx(p, k)];
            L[idx(i, k)] = (Ad[idx(i, k)] - sum) / U[idx(k, k)];
        });
    }
}

