    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) {
        Ad[e.row * N + e.column] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[i * N + i] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // U row k (j = k..N-1)
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) {
                sum += L[k * N + p] * U[p * N + j];
            }
            U[k * N + j] = Ad[k * N + j] - sum;
        });

        // Check pivot
        double pivot = U[k * N + k];
        if (pivot == 0.0) {
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");
        }

        // L column k (i = k+1..N-1)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) {
                sum += L[i * N + p] * U[p * N + k];
            }
            L[i * N + k] = (Ad[i * N + k] - sum) / pivot;
        });
    }
}

