void luFactorize(std::vector<COOElement> const& Acoo, std::vector<double> &L, std::vector<double> &U, size_t N) {
    auto idx = [N](size_t i, size_t j) { return i * N + j; };

    // Dense A
    std::vector<double> A(N * N, 0.0);
    // Fill from COO (assumes no duplicates)
    hpx::for_loop(hpx::execution::par, size_t(0), Acoo.size(), [&](size_t t) {
        auto const& e = Acoo[t];
        A[idx(e.row, e.column)] = e.value;
    });

    // Prepare L (unit diagonal) and U
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    hpx::for_loop(hpx::execution::par, size_t(0), N, [&](size_t i) {
        L[idx(i, i)] = 1.0;
    });

    // Doolittle LU without pivoting
    for (size_t k = 0; k < N; ++k) {
        // Compute U row k for j >= k
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) {
                sum += L[idx(k, p)] * U[idx(p, j)];
            }
            U[idx(k, j)] = A[idx(k, j)] - sum;
        });

        // Check pivot
        double pivot = U[idx(k, k)];
        if (pivot == 0.0) {
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");
        }

        // Compute L column k for i > k
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) {
                sum += L[idx(i, p)] * U[idx(p, k)];
            }
            L[idx(i, k)] = (A[idx(i, k)] - sum) / pivot;
        });
    }
}

