void luFactorize(std::vector<COOElement> const& Acoo, std::vector<double>& L, std::vector<double>& U, size_t N) {
    // Dense workspace (row-major)
    std::vector<double> A(N * N, 0.0);
    A.reserve(N * N);

    // Build dense from COO (accumulate duplicates)
    for (auto const& e : Acoo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        at(A, N, e.row, e.column) += e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) at(L, N, i, i) = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U(k,k) first
        {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) sum += atc(L, N, k, p) * atc(U, N, p, k);
            at(U, N, k, k) = atc(A, N, k, k) - sum;
            if (atc(U, N, k, k) == 0.0) throw std::runtime_error("Zero pivot encountered (no pivoting implemented)");
        }

        // Compute U(k, j) for j=k+1..N-1 in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) sum += atc(L, N, k, p) * atc(U, N, p, j);
            at(U, N, k, j) = atc(A, N, k, j) - sum;
        });

        // Compute L(i, k) for i=k+1..N-1 in parallel
        double Ukk = atc(U, N, k, k);
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) sum += atc(L, N, i, p) * atc(U, N, p, k);
            at(L, N, i, k) = (atc(A, N, i, k) - sum) / Ukk;
        });
    }
}

