generated_output:
void luFactorize(std::vector<COOElement> const& Acoo,
                 std::vector<COOElement>& Lcoo,
                 std::vector<COOElement>& Ucoo,
                 size_t N)
{
    const double eps = 1e-12;

    // Dense A
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        A[idx(e.row, e.column, N)] = e.value;
    }

    // Dense L, U
    std::vector<double> L(N * N, 0.0), U(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[idx(i, i, N)] = 1.0; // unit diagonal

    for (size_t k = 0; k < N; ++k) {
        // U row k (j = k..N-1) in parallel
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double s = 0.0;
            for (size_t p = 0; p < k; ++p) s += L[idx(k, p, N)] * U[idx(p, j, N)];
            U[idx(k, j, N)] = A[idx(k, j, N)] - s;
        });

        double pivot = U[idx(k, k, N)];
        if (std::abs(pivot) < eps) throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented)");

        // L column k (i = k+1..N-1) in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double s = 0.0;
            for (size_t p = 0; p < k; ++p) s += L[idx(i, p, N)] * U[idx(p, k, N)];
            L[idx(i, k, N)] = (A[idx(i, k, N)] - s) / pivot;
        });
    }

    // Convert back to COO (drop near-zeros)
    Lcoo.clear();
    Ucoo.clear();
    Lcoo.reserve(N + N * 4); // rough guess
    Ucoo.reserve(N * 4);

    for (size_t i = 0; i < N; ++i) {
        // Ensure unit diagonal in L
        Lcoo.push_back({i, i, 1.0});
        for (size_t j = 0; j < i; ++j) {
            double v = L[idx(i, j, N)];
            if (std::abs(v) > eps) Lcoo.push_back({i, j, v});
        }
        for (size_t j = i; j < N; ++j) {
            double v = U[idx(i, j, N)];
            if (std::abs(v) > eps) Ucoo.push_back({i, j, v});
        }
    }
}

