void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 size_t N)
{
    // Build dense A
    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) Ad[e.row * N + e.column] = e.value;

    std::vector<double> Ld(N * N, 0.0), Ud(N * N, 0.0);

    // Doolittle LU (no pivoting), parallelized with HPX
    for (size_t k = 0; k < N; ++k) {
        // U[k, j] for j >= k
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) sum += Ld[k * N + s] * Ud[s * N + j];
            Ud[k * N + j] = Ad[k * N + j] - sum;
        });

        // L[i, k] for i >= k, with L[k,k] = 1
        Ld[k * N + k] = 1.0;

        // Check for zero pivot (no pivoting strategy implemented)
        double Ukk = Ud[k * N + k];
        if (Ukk == 0.0) throw std::runtime_error("Zero pivot encountered (no pivoting).");

        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t s = 0; s < k; ++s) sum += Ld[i * N + s] * Ud[s * N + k];
            Ld[i * N + k] = (Ad[i * N + k] - sum) / Ukk;
        });

        // Update trailing submatrix rows i>k, cols j>k (optional for dense A reuse)
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            for (size_t j = k + 1; j < N; ++j) {
                double sum = 0.0;
                for (size_t s = 0; s < k + 1; ++s) sum += Ld[i * N + s] * Ud[s * N + j];
                Ad[i * N + j] = Ad[i * N + j] - sum;
            }
        });
    }

    // Convert dense L and U to COO (skip zeros)
    L.clear(); U.clear(); L.reserve(N * 2); U.reserve(N * 2);
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j <= i; ++j) {
            double v = Ld[i * N + j];
            if (v != 0.0) L.push_back({i, j, v});
        }
        for (size_t j = i; j < N; ++j) {
            double v = Ud[i * N + j];
            if (v != 0.0) U.push_back({i, j, v});
        }
    }
}

