void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& L,
                 std::vector<COOElement>& U,
                 std::size_t N)
{
    // Build dense matrix from COO
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        M[e.row * N + e.column] = e.value;
    }

    std::vector<double> Ld(N * N, 0.0);
    std::vector<double> Ud(N * N, 0.0);

    for (std::size_t k = 0; k < N; ++k) {
        // U[k,j] for j=k..N-1
        hpx::for_loop(hpx::execution::par, k, N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t s = 0; s < k; ++s)
                sum += Ld[k * N + s] * Ud[s * N + j];
            Ud[k * N + j] = M[k * N + j] - sum;
        });

        double pivot = Ud[k * N + k];
        if (std::abs(pivot) < 1e-15)
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented).");

        // L[i,k] for i=k..N-1 (L[k,k] = 1)
        Ld[k * N + k] = 1.0;
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t s = 0; s < k; ++s)
                sum += Ld[i * N + s] * Ud[s * N + k];
            Ld[i * N + k] = (M[i * N + k] - sum) / pivot;
        });

        // Update trailing submatrix M[i,j] = M[i,j] - L[i,k]*U[k,j] (optional; not required for correctness here)
        // We skip explicit Schur updates since we recompute sums directly from L and U each step.
    }

    // Convert dense L and U to COO (skip zeros)
    L.clear(); U.clear();
    L.reserve(N + N); // rough
    U.reserve(N + N);

    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j <= i; ++j) { // L is lower with unit diag
            double v = Ld[i * N + j];
            if (std::abs(v) > 0.0) L.push_back({i, j, v});
        }
        for (std::size_t j = i; j < N; ++j) { // U is upper
            double v = Ud[i * N + j];
            if (std::abs(v) > 0.0) U.push_back({i, j, v});
        }
    }
}

