void luFactorize(std::vector<COOElement> const& Acoo, std::vector<double>& L, std::vector<double>& U, size_t N) {
    // Dense working copy (in-place Schur updates)
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo) {
        A[e.row * N + e.column] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    for (size_t k = 0; k < N; ++k) {
        // U row k from current A
        for (size_t j = k; j < N; ++j) {
            U[k * N + j] = A[k * N + j];
        }
        // Unit diagonal for L
        L[k * N + k] = 1.0;

        double pivot = U[k * N + k];
        // No pivoting; assume non-singular
        // Compute L column k and update trailing matrix in parallel over rows i
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
