            L[i * N + k] = lik;

            // Schur complement update for row i, columns j > k
            for (size_t j = k + 1; j < N; ++j) {
                A[i * N + j] -= lik * U[k * N + j];
            }
            // Zero out below the pivot position to keep A consistent (not strictly necessary)
            A[i * N + k] = 0.0;
