generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<double>& L,
                 std::vector<double>& U,
                 size_t N)
{
    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);

    // Build dense matrix from COO
    std::vector<double> M(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N)
            throw std::out_of_range("COO index out of bounds");
        M[e.row * N + e.column] = e.value;
    }

    for (size_t k = 0; k < N; ++k) {
        // Compute U's k-th row from column k..N-1 in parallel
        hpx::for_loop(hpx::execution::par, k, N, [&](size_t j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += L[k * N + p] * U[p * N + j];
            U[k * N + j] = M[k * N + j] - sum;
        });

        // Check pivot
        double pivot = U[k * N + k];
        if (pivot == 0.0)
            throw std::runtime_error("Zero pivot encountered (no pivoting implemented)");

        // Set unit diagonal for L
        L[k * N + k] = 1.0;

        // Compute L's k-th column for rows k+1..N-1 in parallel
        hpx::for_loop(hpx::execution::par, k + 1, N, [&](size_t i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p)
                sum += L[i * N + p] * U[p * N + k];
            L[i * N + k] = (M[i * N + k] - sum) / pivot;
        });
    }
}

