void luFactorize(std::vector<COOElement> const& Acoo, std::vector<double>& L, std::vector<double>& U, size_t N)
{
    // Build dense A from COO
    std::vector<double> A(N * N, 0.0);
    for (auto const& e : Acoo) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        A[idx(e.row, e.column, N)] = e.value;
    }

    L.assign(N * N, 0.0);
    U.assign(N * N, 0.0);
    for (size_t i = 0; i < N; ++i) L[idx(i, i, N)] = 1.0;

    for (size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j >= k
        hpx::for_each(
            hpx::execution::par,
            hpx::make_counting_iterator<size_t>(k),
            hpx::make_counting_iterator<size_t>(N),
            [&](size_t j) {
                double sum = 0.0;
                for (size_t p = 0; p < k; ++p)
