            });

        double piv = U[idx(k, k, N)];
        if (std::abs(piv) < 1e-14) throw std::runtime_error("Zero or near-zero pivot encountered (no pivoting implemented)");

        // Compute L[i, k] for i > k
        hpx::for_each(
            hpx::execution::par,
            hpx::make_counting_iterator<size_t>(k + 1),
            hpx::make_counting_iterator<size_t>(N),
