   output: L=[{0,0,1},{1,0,1.5}, {1,1,1}] U=[{0,0,4}, {0,1,3}, {1,1,-1.5}]
*/
void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {

generated_output:
void luFactorize(std::vector<COOElement> const& A,
                 std::vector<COOElement>& Lcoo,
                 std::vector<COOElement>& Ucoo,
                 std::size_t N)
{
    // Build dense A
    std::vector<double> Ad(N * N, 0.0);
    for (auto const& e : A) {
        if (e.row >= N || e.column >= N) throw std::out_of_range("COO index out of range");
        Ad[idx(e.row, e.column, N)] = e.value;
    }

    // Dense L,U
    std::vector<double> L(N * N, 0.0), U(N * N, 0.0);
    for (std::size_t i = 0; i < N; ++i) L[idx(i, i, N)] = 1.0; // unit diagonal

    for (std::size_t k = 0; k < N; ++k) {
        // Compute U[k, j] for j = k..N-1 in parallel
        hpx::for_loop(hpx::execution::par, std::size_t(k), N, [&](std::size_t j) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += L[idx(k, p, N)] * U[idx(p, j, N)];
            U[idx(k, j, N)] = Ad[idx(k, j, N)] - sum;
        });

        double pivot = U[idx(k, k, N)];
        if (std::abs(pivot) == 0.0) throw std::runtime_error("Zero pivot encountered (no pivoting implemented)");

        // Compute L[i, k] for i = k+1..N-1 in parallel
        hpx::for_loop(hpx::execution::par, std::size_t(k + 1), N, [&](std::size_t i) {
            double sum = 0.0;
            for (std::size_t p = 0; p < k; ++p)
                sum += L[idx(i, p, N)] * U[idx(p, k, N)];
            L[idx(i, k, N)] = (Ad[idx(i, k, N)] - sum) / pivot;
        });
    }

    // Convert dense L and U to COO (skip zeros with a small tolerance)
    auto push_coo = [](std::vector<COOElement>& out, std::size_t i, std::size_t j, double v) {
        if (std::abs(v) > 0.0) out.push_back(COOElement{i, j, v});
    };

    Lcoo.clear(); Ucoo.clear();
    Lcoo.reserve(N + N * 4); // heuristic
    Ucoo.reserve(N + N * 4);

    const double tol = 0.0;
    for (std::size_t i = 0; i < N; ++i) {
        for (std::size_t j = 0; j <= i; ++j) {
            double v = L[idx(i, j, N)];
            if (std::abs(v) > tol) push_coo(Lcoo, i, j, v);
        }
        for (std::size_t j = i; j < N; ++j) {
            double v = U[idx(i, j, N)];
            if (std::abs(v) > tol) push_coo(Ucoo, i, j, v);
        }
    }
}
